insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('adm-cm:6-bd534d3019','adm-cm',6,'¿Qué mayoría se exige para aprobar el Reglamento de la Asamblea?','["Mayoría simple", "Tres quintos", "Mayoría absoluta", "Dos tercios"]'::jsonb,2,'Art. 12.1 EA','La aprobación y reforma del Reglamento requieren mayoría absoluta de los Diputados.',null),
('adm-cm:6-e337b9cea4','adm-cm',6,'¿Cuáles son los periodos ordinarios de sesiones de la Asamblea?','["De septiembre a diciembre y de febrero a junio", "De septiembre a diciembre y de enero a junio", "De octubre a diciembre y de febrero a julio", "Un único periodo de septiembre a junio"]'::jsonb,0,'Art. 14.1 EA','Hay dos periodos ordinarios: de septiembre a diciembre y de febrero a junio.',null),
('adm-cm:6-559740e8e1','adm-cm',6,'¿Qué órgano actúa entre los periodos de sesiones de la Asamblea?','["La Mesa", "La Junta de Portavoces", "El Gobierno", "La Diputación Permanente"]'::jsonb,3,'Art. 14.2 EA','Entre periodos de sesiones actúa la Diputación Permanente.',null),
('adm-cm:6-3d10c01fb8','adm-cm',6,'Con carácter general, ¿cómo adopta sus acuerdos la Asamblea?','["Por mayoría absoluta de sus miembros, salvo que se exijan mayorías especiales", "Por mayoría de los miembros presentes, salvo que se exijan mayorías especiales", "Por mayoría de tres quintos, salvo que se exija una mayoría distinta", "Por mayoría de los miembros presentes, sin excepción alguna"]'::jsonb,1,'Art. 14.4 EA','Los acuerdos se adoptan por mayoría de los miembros presentes, salvo mayorías especiales.',null),
('adm-cm:6-661fe9bfab','adm-cm',6,'Según el artículo 15, la iniciativa legislativa corresponde a:','["Los diputados, los Grupos Parlamentarios y la Mesa de la Asamblea", "El Gobierno y la Mesa de la Asamblea", "Los diputados, los Grupos Parlamentarios y el Gobierno", "El Presidente de la Comunidad y los Grupos Parlamentarios"]'::jsonb,2,'Art. 15.2 EA','Corresponde a los diputados, a los Grupos Parlamentarios y al Gobierno. Una ley de la Asamblea puede regular además la iniciativa popular y la de los Ayuntamientos.',null),
('adm-cm:6-9137362c03','adm-cm',6,'¿Puede la Asamblea delegar la potestad legislativa en el Gobierno?','["No, la potestad legislativa de la Asamblea es indelegable", "Sí, en los términos de los artículos 82 a 84 de la Constitución", "Sí, en los términos que fije cada año la ley de presupuestos", "Solo en materia tributaria y por un plazo máximo de un año"]'::jsonb,1,'Art. 15.3 EA','Solo en los términos de los arts. 82 a 84 de la Constitución.',null),
('adm-cm:6-70a5f868cd','adm-cm',6,'¿Qué órganos elige la Asamblea de entre sus miembros?','["El Consejo de Gobierno y el Presidente del TSJ", "El Defensor del Pueblo y la Cámara de Cuentas", "La Mesa y la Junta Electoral", "Su Presidente, la Mesa y la Diputación Permanente"]'::jsonb,3,'Art. 13.1 EA','La Asamblea elige de entre sus miembros a su Presidente, a la Mesa y a la Diputación Permanente.',null),
('adm-cm:6-1a6510eefb','adm-cm',6,'¿Cómo funciona la Asamblea de Madrid?','["En Pleno y por Comisiones", "Solo en Pleno", "Por Secciones territoriales", "En Salas especializadas"]'::jsonb,0,'Art. 13.3 EA','La Asamblea funciona en Pleno y por Comisiones.',null),
('adm-cm:6-e17201c75f','adm-cm',6,'¿A quién corresponde designar a los senadores que representan a la Comunidad de Madrid?','["Al Gobierno de la Comunidad", "A la Asamblea de Madrid", "Al Presidente de la Comunidad", "A la Mesa de la Asamblea"]'::jsonb,1,'Art. 16.3.i EA','Corresponde a la Asamblea designar a los senadores que representan a la Comunidad.',null),
('adm-cm:6-1484357ca3','adm-cm',6,'¿Quién elige al Presidente de la Comunidad de Madrid?','["Los ciudadanos, por elección directa", "El Gobierno de la Comunidad", "La Asamblea, de entre sus miembros", "El Rey, a propuesta del Gobierno de la Nación"]'::jsonb,2,'Arts. 16.1 y 18 EA','El Presidente es elegido por la Asamblea de entre sus miembros.',null),
('adm-cm:6-949e6a4bb7','adm-cm',6,'Una vez elegido, el Presidente de la Comunidad es nombrado por:','["El Rey", "El Presidente del Gobierno de la Nación", "El Presidente de la Asamblea", "El Pleno del Tribunal Superior de Justicia"]'::jsonb,0,'Art. 18.3 EA','El candidato elegido por la Asamblea es nombrado Presidente por el Rey.',null),
('adm-cm:6-32e3538b56','adm-cm',6,'En la investidura, ¿qué mayoría necesita el candidato en la primera votación?','["Mayoría simple", "Mayoría absoluta", "Tres quintos", "Dos tercios"]'::jsonb,1,'Art. 18.3 EA','En la primera votación se exige mayoría absoluta.',null),
('adm-cm:6-0e82e99bd8','adm-cm',6,'Si en la primera votación de investidura no hay mayoría absoluta:','["Se vota de nuevo a las 24 horas y se exige mayoría absoluta", "Se vota de nuevo a las 48 horas y se exige mayoría absoluta", "Se vota de nuevo a las 48 horas y basta la mayoría simple", "Se vota de nuevo a los 7 días y basta la mayoría simple"]'::jsonb,2,'Art. 18.3 EA','Se hace una nueva votación 48 horas después y basta la mayoría simple.',null),
('adm-cm:6-7b47c6dc22','adm-cm',6,'Si ningún candidato logra la investidura, ¿en qué plazo queda disuelta la Asamblea?','["Un mes", "Tres meses", "45 días", "Dos meses"]'::jsonb,3,'Art. 18.5 EA','Si en dos meses desde la primera votación ningún candidato es investido, la Asamblea queda disuelta.',null),
('adm-cm:6-c36e44c937','adm-cm',6,'La cuestión de confianza planteada por el Presidente se entiende otorgada cuando vota a favor:','["La mayoría simple", "La mayoría absoluta", "Tres quintos de los diputados", "Dos tercios de los diputados"]'::jsonb,0,'Art. 19.1 EA','La confianza se entiende otorgada por mayoría simple.',null),
('adm-cm:6-050f4f6171','adm-cm',6,'Si la Asamblea niega la confianza al Presidente, el Pleno para elegir uno nuevo debe convocarse en:','["10 días", "15 días", "30 días", "Dos meses"]'::jsonb,1,'Art. 19.2 EA','El Presidente de la Asamblea convoca el Pleno en un plazo máximo de quince días.',null),
('adm-cm:6-7e0ca8d0d5','adm-cm',6,'¿Qué porcentaje mínimo de diputados debe proponer una moción de censura?','["El 10 %", "El 20 %", "El 15 %", "El 25 %"]'::jsonb,2,'Art. 20.1 EA','La moción debe proponerla al menos el 15 % de los diputados.',null),
('adm-cm:6-4584e7f89e','adm-cm',6,'¿Qué mayoría se exige para aprobar una moción de censura?','["Mayoría simple", "Mayoría absoluta", "Tres quintos", "Dos tercios"]'::jsonb,1,'Art. 20.1 EA','La moción de censura se aprueba por mayoría absoluta.',null),
('adm-cm:6-561cb565fd','adm-cm',6,'¿Cuándo puede votarse como pronto una moción de censura?','["A las 48 horas de presentarse", "A los 2 días de presentarse", "A los 10 días de presentarse", "A los 5 días de presentarse"]'::jsonb,3,'Art. 20.2 EA','No puede votarse hasta que pasen cinco días desde su presentación.',null),
('adm-cm:6-1fb3268c04','adm-cm',6,'Si prospera una moción de censura:','["Cesa el Gobierno y el candidato de la moción es nombrado Presidente por el Rey", "Se disuelve la Asamblea y se convocan elecciones en un plazo de dos meses", "Cesa el Gobierno y el candidato es nombrado Presidente por la Asamblea, sin intervención del Rey", "Cesa el Gobierno y la Asamblea abre un plazo de dos meses para elegir Presidente"]'::jsonb,0,'Art. 20.3 EA','Cesan el Presidente y su Gobierno, y el candidato incluido en la moción es nombrado por el Rey.',null),
('adm-cm:6-9e4919aa62','adm-cm',6,'¿En qué caso NO puede el Presidente disolver anticipadamente la Asamblea?','["Durante el segundo año de la legislatura", "Durante el segundo periodo de sesiones de la legislatura", "Durante el primer periodo de sesiones de la legislatura", "Durante los meses de julio y agosto, salvo acuerdo de la Mesa"]'::jsonb,2,'Art. 21.2 EA','No cabe durante el primer periodo de sesiones, con menos de un año de legislatura por delante, con una moción de censura en trámite o con elecciones estatales convocadas.',null),
('adm-cm:6-b810a6dbda','adm-cm',6,'Tras una disolución anticipada, ¿cuándo puede acordarse otra?','["A los seis meses", "Al año", "A los dos años", "A los 18 meses"]'::jsonb,1,'Art. 21.2 EA','No procede nueva disolución antes de que transcurra un año desde la anterior.',null),
('adm-cm:6-9c0121abbe','adm-cm',6,'¿Quiénes componen el Gobierno de la Comunidad de Madrid?','["El Presidente, los Vicepresidentes y el Presidente de la Asamblea", "El Presidente, los Consejeros y los Viceconsejeros", "Los Vicepresidentes, en su caso, y los Consejeros, sin el Presidente", "El Presidente, los Vicepresidentes, en su caso, y los Consejeros"]'::jsonb,3,'Art. 22.2 EA','El Gobierno lo forman el Presidente, los Vicepresidentes si los hay y los Consejeros. Para ser Vicepresidente o Consejero no hace falta ser diputado.',null),
('adm-cm:6-ea6fbec230','adm-cm',6,'¿A quién corresponde la potestad reglamentaria no reservada a la Asamblea?','["A la Mesa de la Asamblea", "Al Gobierno", "A la Diputación Permanente", "Al Presidente de la Asamblea"]'::jsonb,1,'Art. 22.1 EA','El Gobierno ejerce la función ejecutiva y la potestad reglamentaria no reservada a la Asamblea.',null),
('adm-cm:6-6edc5219b5','adm-cm',6,'¿Cómo responde políticamente el Gobierno?','["Solidariamente ante la Asamblea, sin perjuicio de la responsabilidad de cada Consejero", "Individualmente cada Consejero ante la Asamblea, sin responsabilidad solidaria", "Solidariamente ante el Presidente de la Comunidad, que responde ante la Asamblea", "Solidariamente ante la Asamblea y ante el Gobierno de la Nación"]'::jsonb,0,'Art. 23.2 EA','Responde solidariamente ante la Asamblea, sin perjuicio de la responsabilidad directa de cada Consejero por su gestión.',null),
('adm-cm:6-14e2a603d3','adm-cm',6,'Cuando el Gobierno cesa, ¿quién gobierna hasta que toma posesión el nuevo?','["El Presidente de la Asamblea", "El Consejero más antiguo", "El Gobierno cesante, en funciones", "El Delegado del Gobierno en la Comunidad"]'::jsonb,2,'Art. 24.2 EA','El Gobierno cesante sigue en funciones hasta que toma posesión el nuevo.',null),
('adm-cm:6-37d27dbdbf','adm-cm',6,'El Presidente de la Comunidad ostenta:','["La suprema representación de la Comunidad y la de la Asamblea", "La suprema representación de la Comunidad y la ordinaria del Estado en ella", "La representación ordinaria de la Comunidad y la suprema del Estado en ella", "La representación del Gobierno de la Nación en el territorio de Madrid"]'::jsonb,1,'Art. 17.1 EA','Ostenta la suprema representación de la Comunidad y la ordinaria del Estado en ella.',null),
('adm-cm:6-f91e6bdc00','adm-cm',6,'Respecto a sus prerrogativas, los diputados de la Asamblea:','["Son inviolables por las opiniones manifestadas en cualquier ámbito", "Gozan de inmunidad y no pueden ser juzgados sin autorización de la Asamblea", "Son inviolables por las opiniones manifestadas en el ejercicio de sus funciones", "Solo pueden ser detenidos con autorización previa de la Mesa"]'::jsonb,2,'Art. 11.5 EA','Son inviolables por las opiniones manifestadas en el ejercicio de sus funciones.',null),
('adm-cm:6-ae02c51901','adm-cm',6,'¿Qué tribunal decide sobre la inculpación, prisión, procesamiento y juicio de los diputados por delitos cometidos en el territorio de la Comunidad?','["El Tribunal Supremo, Sala de lo Penal", "La Audiencia Nacional, Sala de lo Penal", "La Audiencia Provincial de Madrid", "El Tribunal Superior de Justicia de Madrid"]'::jsonb,3,'Art. 11.6 EA','Corresponde al TSJ de Madrid. Fuera del territorio de la Comunidad, a la Sala de lo Penal del Tribunal Supremo.',null),
('adm-cm:6-ee077ae9aa','adm-cm',6,'En ordenación del territorio, urbanismo y vivienda, la Comunidad de Madrid tiene competencia:','["Exclusiva", "De desarrollo legislativo y ejecución", "Solo de ejecución", "Ninguna: es competencia del Estado"]'::jsonb,0,'Art. 26.1.4 EA','Es una de las materias de competencia exclusiva.',null),
('adm-cm:6-6871e363be','adm-cm',6,'En sanidad e higiene, la Comunidad de Madrid tiene competencia:','["Exclusiva, sin perjuicio de la alta inspección y coordinación general que corresponden al Estado", "Desarrollo legislativo, potestad reglamentaria y ejecución, en el marco de la legislación básica estatal", "Solo de ejecución de la legislación estatal, sin potestad reglamentaria propia en la materia", "Desarrollo legislativo y potestad reglamentaria, pero la ejecución corresponde al Estado"]'::jsonb,1,'Art. 27.4 EA','Desarrollo legislativo, potestad reglamentaria y ejecución en el marco de la legislación básica del Estado.',null),
('adm-cm:6-3874d3c6fe','adm-cm',6,'En propiedad intelectual e industrial, la Comunidad de Madrid tiene competencia:','["Exclusiva", "De desarrollo legislativo", "De ejecución de la legislación del Estado", "De desarrollo legislativo y potestad reglamentaria"]'::jsonb,2,'Art. 28.1.11 EA','La legislación es estatal; a la Comunidad le corresponde su ejecución.',null),
('adm-cm:6-31992e787b','adm-cm',6,'En materia de régimen local, la Comunidad de Madrid tiene, en el marco de la legislación básica del Estado:','["Competencia exclusiva sin límites", "Competencia de desarrollo legislativo, potestad reglamentaria y ejecución", "Competencia de ejecución, pero no de desarrollo legislativo ni de potestad reglamentaria", "Solo competencia de ejecución de la legislación del Estado, sin desarrollo legislativo"]'::jsonb,1,'Art. 27.1 EA','El art. 27 recoge las competencias de desarrollo legislativo.',null),
('adm-cm:6-28a38cee60','adm-cm',6,'Según el art. 45 del Estatuto, el Tribunal Superior de Justicia de Madrid:','["Es un órgano de la Asamblea de Madrid que culmina la organización judicial en la Comunidad, aunque las instancias se agotan ante el Tribunal Supremo", "Culmina la organización judicial en el ámbito territorial de la Comunidad, agotándose ante él las sucesivas instancias procesales", "Depende del Gobierno de la Comunidad, que nombra a su Presidente a propuesta de la Asamblea y del Consejo General del Poder Judicial", "Sustituye al Tribunal Supremo en todo"]'::jsonb,1,'Art. 45 EA','Sin perjuicio de la jurisdicción del Tribunal Supremo.',null),
('adm-cm:6-917f36609c','adm-cm',6,'Según el art. 9 del Estatuto, la Asamblea de Madrid:','["Representa al pueblo de Madrid, ejerce la potestad legislativa, aprueba y controla el Presupuesto e impulsa y controla la acción del Gobierno", "Dirige la Administración autonómica, ejerce la potestad reglamentaria general y nombra a los Consejeros a propuesta del Presidente, a quien elige entre sus miembros", "Nombra a los magistrados del Tribunal Superior de Justicia, dirige la Administración autonómica, ejerce la potestad reglamentaria general y aprueba los decretos", "Ejerce la potestad reglamentaria general"]'::jsonb,0,'Art. 9 EA','Son las funciones básicas de la Asamblea.','abr. 2026 · 1.er ejercicio'),
('adm-cm:6-19ccaccf42','adm-cm',6,'Según el art. 44 del Estatuto, el control económico y presupuestario de la Comunidad de Madrid se ejerce por:','["La Cámara de Cuentas, sin perjuicio de lo que corresponda al Tribunal de Cuentas", "El Banco de España y la Intervención General de la Administración del Estado, conjuntamente", "El Defensor del Pueblo", "El Consejo de Gobierno, a través de la Intervención General, sin perjuicio de lo que corresponda al Tribunal de Cuentas"]'::jsonb,0,'Art. 44 EA','La Cámara de Cuentas es el órgano de control externo autonómico.',null),
('adm-cm:6-1ec42058f3','adm-cm',6,'Según el art. 51 del Estatuto, la Comunidad de Madrid:','["Depende de las transferencias del Estado y de los municipios, sin capacidad tributaria propia", "Tiene un régimen de concierto económico con el Estado, como los territorios forales, con plena capacidad normativa sobre los tributos estatales en su territorio", "Goza de autonomía financiera, dentro de los principios de coordinación con las Haciendas estatal y local y de solidaridad", "Goza de autonomía financiera plena, sin sujeción a principios de coordinación con la Hacienda del Estado ni con las Haciendas locales de su territorio"]'::jsonb,2,'Art. 51 EA','Principio de autonomía financiera.',null),
('adm-cm:6-3331499507','adm-cm',6,'Según el art. 22.1 del Estatuto, el Gobierno de la Comunidad de Madrid es:','["Un organismo autónomo adscrito a la Presidencia", "El órgano colegiado que dirige la política de la Comunidad de Madrid", "El órgano unipersonal que dirige la política y la Administración de la Comunidad", "Un órgano consultivo de la Asamblea, que dirige la Administración de la Comunidad"]'::jsonb,1,'Art. 22.1 EA','Le corresponden las funciones ejecutivas y administrativas y la potestad reglamentaria no reservada a la Asamblea.',null),
('adm-cm:6-f208f7468c','adm-cm',6,'Según el art. 24.1 del Estatuto, el Gobierno cesa:','["Cada dos años, o cuando dimita cualquiera de sus miembros", "Cuando dimita cualquier Consejero, cuando lo decida el Gobierno de la Nación o cuando la Asamblea rechace el proyecto de ley de presupuestos generales de la Comunidad", "Tras la celebración de elecciones a la Asamblea, en los casos de pérdida de la confianza parlamentaria, o por dimisión, incapacidad o fallecimiento del Presidente", "Cuando lo decida el Gobierno de la Nación"]'::jsonb,2,'Art. 24.1 EA','Son las causas de cese del Gobierno.',null),
('adm-cm:6-3be8f32b74','adm-cm',6,'Según el art. 26.1.1 del Estatuto, la Comunidad de Madrid tiene competencia exclusiva en:','["La legislación penal y penitenciaria aplicable a los delitos cometidos en su territorio", "Las relaciones internacionales", "La defensa y las Fuerzas Armadas", "La organización, régimen y funcionamiento de sus instituciones de autogobierno"]'::jsonb,3,'Art. 26.1.1 EA','Es la primera de las materias de competencia exclusiva.',null),
('adm-cm:6-609462f441','adm-cm',6,'Según el art. 1.1 del Estatuto, Madrid organiza su autogobierno como Comunidad Autónoma:','["De conformidad con la Constitución Española y con el propio Estatuto", "Según lo que decida en cada momento el Gobierno de la Nación", "De conformidad con los tratados de la Unión Europea y con las leyes orgánicas de transferencia", "De acuerdo con la Ley de Bases de Régimen Local"]'::jsonb,0,'Art. 1.1 EA','El Estatuto es la norma institucional básica de la Comunidad.',null),
('adm-cm:6-f20f7bfc05','adm-cm',6,'La propuesta de reforma del Estatuto requiere la aprobación de la Asamblea de Madrid por mayoría de:','["Tres quintos, y la aprobación de las Cortes Generales mediante ley ordinaria", "Mayoría absoluta y real decreto", "Dos tercios, y la aprobación de las Cortes Generales mediante ley orgánica", "Mayoría absoluta, y la ratificación posterior mediante referéndum en la Comunidad"]'::jsonb,2,'Art. 64.1 EA','Es el procedimiento de reforma estatutaria.',null),
('adm-cm:6-07bfc9ede4','adm-cm',6,'Según el art. 29.1 del Estatuto, corresponde a la Comunidad de Madrid en materia de enseñanza:','["El desarrollo legislativo y la ejecución de la enseñanza en toda su extensión, niveles y grados", "Solo la ejecución de la legislación estatal en materia de enseñanza no universitaria", "Solo la enseñanza universitaria", "La expedición de títulos académicos con validez estatal sin control del Estado"]'::jsonb,0,'Art. 29.1 EA','Sin perjuicio de las competencias del Estado del art. 149.1.30.ª CE.',null),
('adm-cm:6-34faedc245','adm-cm',6,'Si una propuesta de reforma del Estatuto no es aprobada por la Asamblea, no podrá ser sometida nuevamente a debate y votación hasta que haya transcurrido:','["Seis meses", "Una legislatura completa", "Dos años", "Un año"]'::jsonb,3,'Art. 64.2 EA','Así lo establece el art. 64.2.',null),
('adm-cm:6-0aea50b407','adm-cm',6,'La Comunidad de Madrid puede establecer acuerdos de cooperación con otras Comunidades Autónomas:','["Libremente sin ninguna comunicación", "Previa autorización de las Cortes Generales", "Solo con las Comunidades limítrofes", "Previa autorización del Tribunal Constitucional"]'::jsonb,1,'Art. 31.2 EA','Los convenios para gestión de servicios propios solo requieren comunicación a las Cortes.',null),
('adm-cm:6-02b17af4a9','adm-cm',6,'Según el art. 1.3 del Estatuto, la Comunidad de Madrid aspira a hacer realidad los principios de:','["Seguridad, prosperidad y paz", "Pluralismo, eficacia, jerarquía y coordinación entre sus instituciones", "Unidad, orden y progreso", "Libertad, justicia e igualdad para todos los madrileños"]'::jsonb,3,'Art. 1.3 EA','Así lo recoge el art. 1.3 del Estatuto.',null),
('adm-cm:6-19b282896e','adm-cm',6,'Según el art. 32.1, la Comunidad de Madrid puede solicitar al Gobierno de la Nación:','["La celebración de tratados o convenios internacionales en materias de interés para Madrid", "La disolución anticipada de las Cortes Generales", "El nombramiento de embajadores", "La declaración del estado de alarma en todo caso, en todo o parte de su territorio"]'::jsonb,0,'Art. 32.1 EA','La competencia en relaciones internacionales es del Estado.',null),
('adm-cm:6-4be454ebae','adm-cm',6,'Según el art. 7.1 del Estatuto, los derechos y deberes fundamentales de los ciudadanos de Madrid son:','["Los que fije la Asamblea por mayoría simple", "Los establecidos en la Constitución", "Los del Código Civil", "Los establecidos en una Carta de Derechos madrileña"]'::jsonb,1,'Art. 7.1 EA','El Estatuto se remite a la Constitución.',null),
('adm-cm:6-b34dff4e07','adm-cm',6,'Las leyes de la Asamblea de Madrid se publican en el BOCM y en el BOE y entran en vigor, salvo que dispongan otra cosa:','["A los veinte días de su publicación en el BOE", "El 1 de enero siguiente", "Al día siguiente de su publicación en el Boletín Oficial de la Comunidad de Madrid", "A los veinte días de su publicación en el Boletín Oficial de la Comunidad de Madrid"]'::jsonb,2,'Art. 40.1 EA','La fecha que cuenta es la de publicación en el BOCM.',null),
('adm-cm:6-4584775e97','adm-cm',6,'La iniciativa para la reforma del Estatuto corresponde, entre otros, a la Asamblea de Madrid a propuesta de:','["Cinco diputados", "La mitad más uno de sus miembros", "Un grupo parlamentario cualquiera", "Una tercera parte de sus miembros"]'::jsonb,3,'Art. 64.1 EA','También al Gobierno y a dos tercios de los municipios que representen la mayoría absoluta de la población.',null),
('adm-cm:6-b1592785bc','adm-cm',6,'Según el art. 23.2 del Estatuto, el Gobierno responde políticamente ante la Asamblea:','["Ante el Tribunal Constitucional", "De forma individual exclusivamente, respondiendo cada Consejero por su gestión, sin responsabilidad solidaria", "Solo ante el Rey", "De forma solidaria, sin perjuicio de la responsabilidad directa de cada Consejero por su gestión"]'::jsonb,3,'Art. 23.2 EA','Responsabilidad solidaria del Gobierno.',null),
('adm-cm:6-92e827416b','adm-cm',6,'La Comunidad de Madrid puede asumir competencias no previstas en el Estatuto:','["Por decreto del Consejo de Gobierno, previa autorización de la Asamblea por mayoría absoluta y comunicación al Gobierno de la Nación", "Por acuerdo con otra Comunidad", "Mediante reforma del Estatuto o mediante decisión de las Cortes Generales (leyes de los arts. 150.1 y 150.2 CE)", "Por referéndum municipal convocado en todos los municipios de la Comunidad con el acuerdo de la Asamblea por mayoría de tres quintos"]'::jsonb,2,'Art. 30.1 EA','Vías de ampliación competencial.',null),
('adm-cm:6-0038d027ea','adm-cm',6,'Para adquirir la condición plena de Diputado de la Asamblea de Madrid se requiere:','["Prometer o jurar acatamiento a la Constitución y al Estatuto de Autonomía", "Tener más de 25 años y estar empadronado en un municipio de la Comunidad", "Ser vecino de Madrid capital", "Ser funcionario"]'::jsonb,0,'Art. 11.2 EA','Es requisito para ser Diputado de pleno derecho.',null),
('adm-cm:6-c867a9060b','adm-cm',6,'Según el Estatuto, la Comunidad de Madrid se organiza territorialmente en:','["Distritos y barrios con personalidad jurídica propia", "Mancomunidades obligatorias", "Provincias y comarcas, con personalidad jurídica propia", "Municipios, que gozan de plena personalidad jurídica"]'::jsonb,3,'Art. 3.1 EA','Los municipios pueden agruparse voluntariamente (art. 3.2).',null),
('adm-cm:6-1edd879567','adm-cm',6,'Las leyes de la Asamblea de Madrid están sujetas únicamente al control de constitucionalidad ejercido por:','["La Cámara de Cuentas", "El Tribunal Constitucional", "El Tribunal Superior de Justicia de Madrid", "El Consejo de Estado"]'::jsonb,1,'Art. 42 EA','Los reglamentos y actos se controlan por la jurisdicción contencioso-administrativa (art. 43).',null),
('adm-cm:6-afcee02039','adm-cm',6,'Tienen la condición política de ciudadanos de la Comunidad de Madrid:','["Los empadronados con más de diez años de residencia", "Todos los residentes en la Comunidad de Madrid, sean o no españoles, con independencia de su vecindad", "Los españoles que tengan vecindad administrativa en cualquiera de los municipios de la Comunidad", "Los nacidos en Madrid y los residentes extranjeros con más de diez años de empadronamiento en la Comunidad"]'::jsonb,2,'Art. 7.2 EA','La condición política depende de la vecindad administrativa.',null),
('adm-cm:6-e61de01db0','adm-cm',6,'Según el art. 33 del Estatuto, en las materias de competencia exclusiva de la Comunidad, el Derecho propio de Madrid:','["Es supletorio del Derecho estatal, que se aplica con preferencia en todo el territorio nacional", "Necesita confirmación de las Cortes", "Solo se aplica en la capital", "Es aplicable en su territorio con preferencia a cualquier otro, siendo el Derecho estatal supletorio"]'::jsonb,3,'Art. 33 EA','El Derecho estatal tiene carácter supletorio.',null),
('adm-cm:7-8d86124bdd','adm-cm',7,'Según la Ley 1/1983, ¿cuáles son los órganos superiores de Gobierno y Administración de la Comunidad de Madrid?','["El Presidente, el Consejo de Gobierno y los Consejeros", "El Presidente, la Asamblea y los Consejeros", "El Consejo de Gobierno y los Viceconsejeros", "El Presidente, los Consejeros y los Directores Generales"]'::jsonb,0,'Art. 1.1 Ley 1/1983','Los órganos superiores son el Presidente, el Consejo de Gobierno y los Consejeros.',null),
('adm-cm:7-c5eec221c5','adm-cm',7,'El Presidente de la Comunidad de Madrid, elegido por la Asamblea, es nombrado:','["Por el Presidente del Gobierno de la Nación mediante decreto", "Por el Rey mediante Real Decreto", "Por la Asamblea mediante resolución", "Por el Consejo de Gobierno"]'::jsonb,1,'Art. 4 Ley 1/1983','Es elegido por la Asamblea de entre sus miembros y nombrado por el Rey mediante Real Decreto.',null),
('adm-cm:7-9b7a556c50','adm-cm',7,'¿Qué tratamiento corresponde al Presidente de la Comunidad?','["Ilustrísimo", "Señoría", "Excelencia", "Honorable"]'::jsonb,2,'Art. 5 Ley 1/1983','El Presidente tiene tratamiento de excelencia.',null),
('adm-cm:7-fbbb3a31e6','adm-cm',7,'El sueldo del Presidente de la Comunidad no puede superar el asignado en los Presupuestos Generales del Estado a:','["Un Ministro", "El Presidente del Gobierno", "Un diputado del Congreso", "Un Secretario de Estado"]'::jsonb,3,'Art. 5 Ley 1/1983','No puede ser superior al de un Secretario de Estado.',null),
('adm-cm:7-5b9f007071','adm-cm',7,'El cargo de Presidente de la Comunidad es compatible con:','["La condición de Diputado de la Asamblea", "El cargo de alcalde de un municipio de la Comunidad de Madrid", "La condición de senador por designación autonómica", "La condición de Diputado en el Congreso"]'::jsonb,0,'Art. 6 Ley 1/1983','Es incompatible con otras funciones públicas, salvo la de Diputado de la Asamblea, y con cualquier actividad laboral, profesional o empresarial.','nov. 2024 · 1.er ejercicio'),
('adm-cm:7-3832267c00','adm-cm',7,'El Presidente de la Comunidad promulga las Leyes de la Asamblea y los Decretos legislativos:','["En nombre de la Asamblea", "En nombre del Rey", "En nombre del pueblo de Madrid", "No los promulga: lo hace el Presidente de la Asamblea"]'::jsonb,1,'Art. 8 a) Ley 1/1983','Los promulga en nombre del Rey.',null),
('adm-cm:7-2cc9187e41','adm-cm',7,'¿Quién convoca las elecciones a la Asamblea de Madrid?','["El Presidente de la Asamblea", "El Consejo de Gobierno", "El Presidente de la Comunidad", "La Junta Electoral"]'::jsonb,2,'Art. 7 c) Ley 1/1983','Las convoca el Presidente de la Comunidad, en los términos del art. 11 del Estatuto.',null),
('adm-cm:7-a09d50ec30','adm-cm',7,'El Presidente plantea ante la Asamblea la cuestión de confianza:','["Previa autorización de la Asamblea", "Previo acuerdo de cuatro quintos del Consejo", "Sin ningún trámite previo", "Previa deliberación del Consejo de Gobierno"]'::jsonb,3,'Art. 9 l) Ley 1/1983','La plantea previa deliberación del Consejo de Gobierno.',null),
('adm-cm:7-6449d6352c','adm-cm',7,'Cuando el Presidente delega funciones ejecutivas o de representación, debe dar cuenta a la Asamblea en:','["48 horas, y publicar la delegación en el BOCM", "15 días, y publicar la delegación en el BOCM", "72 horas, sin necesidad de publicarla en ningún boletín", "Un mes, y publicar la delegación en el BOE"]'::jsonb,0,'Art. 10.1 Ley 1/1983','Da cuenta a la Asamblea en 48 horas y publica la delegación en el BOCM.',null),
('adm-cm:7-8e96507e68','adm-cm',7,'¿Cuál de estas atribuciones NO puede delegar el Presidente?','["La representación en un acto oficial", "Nombrar y separar a los Consejeros", "Funciones ejecutivas propias en un Vicepresidente", "Funciones de representación en un Consejero"]'::jsonb,1,'Art. 10.2 Ley 1/1983','No son delegables, entre otras, las del art. 9 a): nombrar y separar a los Consejeros.',null),
('adm-cm:7-3069042591','adm-cm',7,'¿Cuántos asesores puede tener como máximo el Gabinete del Presidente?','["Cuatro", "Cinco", "Seis", "Ocho"]'::jsonb,2,'Art. 11.2 Ley 1/1983','El Gabinete tiene hasta seis asesores.',null),
('adm-cm:7-5ce407792f','adm-cm',7,'El Jefe del Gabinete del Presidente tiene rango de:','["Viceconsejero", "Secretario General Técnico", "Consejero", "Director general"]'::jsonb,3,'Art. 11.3 Ley 1/1983','Tiene rango de Director general y lo nombra el Consejo de Gobierno a propuesta del Presidente.',null),
('adm-cm:7-3033b6ba7d','adm-cm',7,'Las ausencias temporales del Presidente de más de un mes requieren:','["Autorización previa de la Asamblea", "Acuerdo del Consejo de Gobierno", "Autorización del Rey", "Ningún requisito"]'::jsonb,0,'Art. 12 Ley 1/1983','Requieren autorización previa de la Asamblea.',null),
('adm-cm:7-21d507548e','adm-cm',7,'La incapacidad transitoria del Presidente exige un acuerdo del Consejo de Gobierno adoptado por:','["Mayoría absoluta", "Cuatro quintas partes de sus miembros", "Dos tercios de sus miembros", "Tres quintas partes de sus miembros"]'::jsonb,1,'Art. 13.1 Ley 1/1983','Se exige acuerdo del Consejo por cuatro quintas partes de sus miembros.',null),
('adm-cm:7-f9c5ad1267','adm-cm',7,'La Asamblea puede revocar el acuerdo de incapacidad transitoria del Presidente por:','["Mayoría simple", "Tres quintos", "Mayoría absoluta", "Dos tercios"]'::jsonb,2,'Art. 13.3 Ley 1/1983','La Asamblea puede revocarlo por mayoría absoluta.',null),
('adm-cm:7-0316ef17d0','adm-cm',7,'¿Qué limitación tiene el Presidente interino?','["No puede presidir el Consejo de Gobierno ni firmar decretos de estructura de las Consejerías", "No puede firmar ningún acto ni disposición administrativa sin autorización de la Asamblea", "No puede nombrar Consejeros, pero sí separarlos de su cargo", "No puede definir el programa de Gobierno ni nombrar o separar Consejeros"]'::jsonb,3,'Art. 14 Ley 1/1983','No puede definir el programa de Gobierno ni nombrar o separar Consejeros.',null),
('adm-cm:7-f0731bc9e7','adm-cm',7,'¿Cuánto puede durar como máximo la interinidad en la Presidencia?','["Dos meses, ampliables otros dos por acuerdo de la Asamblea por mayoría absoluta", "Un mes, ampliable otro más por acuerdo de la Asamblea por mayoría simple", "Seis meses, sin posibilidad de prórroga", "Tres meses, ampliables otros tres por acuerdo del Consejo de Gobierno"]'::jsonb,0,'Art. 15.1 Ley 1/1983','No puede superar dos meses, ampliables en otros dos con acuerdo de la Asamblea por mayoría absoluta.',null),
('adm-cm:7-7933ce7e55','adm-cm',7,'¿Cuál de las siguientes NO es causa de cese del Presidente?','["Dimisión comunicada a la Asamblea", "Fallecimiento o incapacidad física permanente", "Incapacidad permanente declarada por la Asamblea", "Pérdida de la afiliación a su partido"]'::jsonb,3,'Art. 16.1 Ley 1/1983','Las causas son: renovación de la Asamblea, moción de censura, denegación de la cuestión de confianza, dimisión, incapacidad permanente y fallecimiento.',null),
('adm-cm:7-56c859ca52','adm-cm',7,'¿Quién sustituye al Presidente?','["El Presidente de la Asamblea y, después, los Vicepresidentes", "Los Vicepresidentes y, después, los Consejeros por el orden establecido", "El Consejero más antiguo y, después, el de mayor edad, por orden de nombramiento", "Los Consejeros por orden de antigüedad, sin pasar por los Vicepresidentes"]'::jsonb,1,'Art. 17.1 Ley 1/1983','Primero los Vicepresidentes y después los Consejeros, por el orden del art. 19.2.',null),
('adm-cm:7-ee94aafc0f','adm-cm',7,'El Presidente en funciones:','["Puede ser objeto de moción de censura, pero no plantear la cuestión de confianza", "Puede plantear la cuestión de confianza, pero no ser objeto de moción de censura", "No puede ser objeto de moción de censura ni plantear la cuestión de confianza", "Puede disolver la Asamblea, pero no plantear la cuestión de confianza"]'::jsonb,2,'Art. 17.2 Ley 1/1983','No puede ser objeto de moción de censura ni plantear la cuestión de confianza.',null),
('adm-cm:7-ec71c75bd9','adm-cm',7,'Según el art. 18, el Consejo de Gobierno ejerce:','["La potestad legislativa, la función ejecutiva y la potestad reglamentaria", "La iniciativa legislativa, la función ejecutiva y el control de la Asamblea", "La iniciativa legislativa, la función ejecutiva y la potestad reglamentaria", "La función ejecutiva y la potestad reglamentaria, pero no la iniciativa legislativa"]'::jsonb,2,'Art. 18 Ley 1/1983','Dirige la política y la Administración, y ejerce la iniciativa legislativa, la función ejecutiva y la potestad reglamentaria.',null),
('adm-cm:7-3154382594','adm-cm',7,'¿Con qué periodicidad se reúne el Consejo de Gobierno?','["Con una periodicidad igual o menor a un mes, salvo convocatoria urgente", "Con una periodicidad igual o menor a una semana", "Cuando lo convoque su Presidente, sin periodicidad fija", "Con una periodicidad igual o menor a quince días"]'::jsonb,3,'Art. 23.1 Ley 1/1983','Se reúne por convocatoria del Presidente con una periodicidad igual o menor a quince días.',null),
('adm-cm:7-3c25ba6f18','adm-cm',7,'Para que las reuniones del Consejo de Gobierno sean válidas se requiere la presencia de:','["El Presidente o su sustituto y, al menos, la mitad de los Consejeros", "El Presidente o su sustituto y, al menos, dos tercios de los Consejeros", "El Presidente y, al menos, un tercio de los Consejeros", "El Presidente, sin sustitución posible, y la mayoría de los Consejeros"]'::jsonb,0,'Art. 24 Ley 1/1983','Presidente o sustituto y, al menos, la mitad de los Consejeros.',null),
('adm-cm:7-51ddca4a60','adm-cm',7,'En caso de empate en una votación del Consejo de Gobierno:','["Se repite la votación en la siguiente sesión", "Decide el voto del Presidente", "Decide la Asamblea", "Se entiende rechazada la propuesta"]'::jsonb,1,'Art. 24 Ley 1/1983','El voto del Presidente es dirimente.',null),
('adm-cm:7-490c877f80','adm-cm',7,'Las deliberaciones del Consejo de Gobierno:','["Son públicas, salvo que el Consejo acuerde lo contrario", "Se recogen íntegramente en actas que se publican en el BOCM", "Tienen carácter reservado y sus miembros deben guardar secreto", "Son reservadas, pero cualquier Consejero puede difundir su voto"]'::jsonb,2,'Art. 25.1 Ley 1/1983','Tienen carácter reservado y sus miembros deben guardar secreto.',null),
('adm-cm:7-d41dc58288','adm-cm',7,'¿Quién actúa como Secretario del Consejo de Gobierno y extiende las actas?','["El Consejero de Hacienda", "El Vicepresidente primero de la Comunidad", "El Secretario General Técnico de la Consejería de Presidencia", "El Consejero de la Presidencia"]'::jsonb,3,'Art. 25.3 Ley 1/1983','Extiende las actas el Consejero de la Presidencia como Secretario.',null),
('adm-cm:7-07fd40912f','adm-cm',7,'Las Comisiones Delegadas del Consejo de Gobierno están presididas por:','["El Presidente, que puede delegar en el Consejero de la Presidencia", "El Presidente, que puede delegar en el Consejero más antiguo", "El Consejero de la Presidencia, sin posibilidad de delegación", "El Vicepresidente primero, que puede delegar en un Viceconsejero"]'::jsonb,0,'Art. 26 Ley 1/1983','Las preside el Presidente, que puede delegar en el Consejero de la Presidencia.',null),
('adm-cm:7-d6aa735934','adm-cm',7,'¿Quién refrenda los Decretos aprobados a propuesta de una Consejería?','["El Presidente de la Asamblea", "El Consejero correspondiente", "El Secretario General Técnico", "Nadie: no requieren refrendo"]'::jsonb,1,'Art. 31 b) Ley 1/1983','Los Consejeros proponen los proyectos de Decreto de su Consejería y los refrendan una vez aprobados.',null),
('adm-cm:7-a141d9c7f7','adm-cm',7,'El Consejo de Gobierno responde de su política:','["Individualmente cada Consejero ante la Asamblea, sin responsabilidad solidaria", "Solidariamente ante el Tribunal Superior de Justicia de Madrid", "Solidariamente ante la Asamblea, sin perjuicio de la responsabilidad de cada Consejero", "Solidariamente ante el Presidente, que responde ante la Asamblea"]'::jsonb,2,'Art. 34.1 Ley 1/1983','Responde solidariamente ante la Asamblea, sin perjuicio de la responsabilidad individual de cada Consejero.',null),
('adm-cm:7-cdb7e32809','adm-cm',7,'¿Cómo se nombra a los Viceconsejeros, Secretarios Generales Técnicos y Directores Generales?','["Por orden del Consejero correspondiente, dando cuenta al Consejo de Gobierno", "Por decreto del Presidente, a propuesta del Consejero correspondiente", "Por acuerdo de la Asamblea, a propuesta del Consejo de Gobierno", "Por Decreto del Consejo de Gobierno, a propuesta del Consejero correspondiente"]'::jsonb,3,'Arts. 39.3, 44.3 y 45 Ley 1/1983','Se nombran por Decreto del Consejo de Gobierno, a propuesta del Consejero correspondiente.','oct. 2026 · 1.er ejercicio'),
('adm-cm:7-8c51f89d78','adm-cm',7,'¿Cómo se estructuran las Consejerías?','["Secretaría General Técnica y Direcciones Generales, y pueden tener Viceconsejeros", "Direcciones Generales y Subdirecciones Generales, sin Secretaría General Técnica propia", "Subsecretaría y Secretarías Generales, igual que los ministerios del Estado", "Viceconsejería y Delegaciones territoriales en cada zona de la región, sin Direcciones Generales"]'::jsonb,0,'Art. 39.1 Ley 1/1983','Cada Consejería tiene una Secretaría General Técnica, se estructura en Direcciones Generales y puede tener Viceconsejeros.','oct. 2026 · 1.er ejercicio'),
('adm-cm:7-4f01be6487','adm-cm',7,'Si el Presidente delega temporalmente funciones en un Consejero, ¿queda exento de responsabilidad política?','["Sí, la asume el Consejero", "No", "Solo si la delegación se publica en el BOCM", "Solo si la Asamblea la autoriza"]'::jsonb,1,'Art. 35 Ley 1/1983','La delegación temporal no exime al Presidente de responsabilidad política.',null),
('adm-cm:7-bc7b73801f','adm-cm',7,'Según el art. 2 de la Ley 1/1983, el Presidente de la Comunidad ostenta:','["La suprema representación de la Comunidad Autónoma y la ordinaria del Estado en ella", "La jefatura del Consejo de Gobierno, pero no la representación del Estado", "La representación ordinaria de la Comunidad y la suprema del Estado en ella", "La presidencia de la Asamblea"]'::jsonb,0,'Art. 2 Ley 1/1983','Así lo establece el art. 2.',null),
('adm-cm:7-1edaba5e3d','adm-cm',7,'Corresponde al Presidente, como Presidente del Consejo de Gobierno, resolver:','["Los conflictos de competencias entre las distintas Consejerías", "Los recursos contencioso-administrativos", "Los conflictos de competencias entre la Comunidad y los municipios de su territorio", "Los recursos de amparo y los conflictos con otras Comunidades Autónomas"]'::jsonb,0,'Art. 9 e) Ley 1/1983','Es una atribución presidencial indelegable.',null),
('adm-cm:7-febd193923','adm-cm',7,'Según el art. 37.2 de la Ley 1/1983, la actuación de la Administración de la Comunidad se rige, entre otros, por los principios de:','["Objetividad, publicidad, celeridad, eficacia y economía", "Centralización, jerarquía, unidad de mando y reserva de las actuaciones", "Secreto y discrecionalidad", "Jerarquía, reserva de las actuaciones y libre arbitrio del órgano"]'::jsonb,0,'Art. 37.2 Ley 1/1983','Son principios de actuación administrativa.',null),
('adm-cm:7-f990d31bb5','adm-cm',7,'Corresponde al Consejo de Gobierno dictar Decretos legislativos:','["Libremente", "Previa autorización de las Cortes Generales", "Previo dictamen del Tribunal Constitucional", "Previa autorización de la Asamblea"]'::jsonb,3,'Art. 21 e) Ley 1/1983','Es la delegación legislativa autonómica.',null),
('adm-cm:7-bec9451af6','adm-cm',7,'Los Consejeros cesan:','["Solo por moción de censura individual aprobada por la Asamblea", "Por decisión de la Asamblea en todo caso", "Por dimisión aceptada por el Presidente, por cese decretado por el Presidente o por fallecimiento", "Por cese acordado por el Consejo de Gobierno, por dimisión aceptada por la Asamblea o por fallecimiento"]'::jsonb,2,'Art. 29 Ley 1/1983','También cesan cuando cesa el Presidente que los nombró.',null),
('adm-cm:7-78daf28fd3','adm-cm',7,'Las reclamaciones previas a la vía judicial civil y laboral en la Comunidad de Madrid las resuelven:','["Los Directores generales", "El Consejo de Gobierno", "El Presidente de la Comunidad", "Los Consejeros respectivos"]'::jsonb,3,'Art. 53.7 Ley 1/1983','Según el art. 53.7 de la Ley 1/1983.',null),
('adm-cm:7-d12b350017','adm-cm',7,'Según la Ley 1/1983, conoce en única instancia de las reclamaciones económico-administrativas en la Comunidad de Madrid:','["El Tribunal Económico-Administrativo Central", "La Cámara de Cuentas", "La Junta Superior de Hacienda", "El Consejo de Gobierno"]'::jsonb,2,'Art. 54.2 Ley 1/1983','Órgano de la Comunidad para reclamaciones económico-administrativas.',null),
('adm-cm:7-0899cc3b35','adm-cm',7,'Corresponde al Consejo de Gobierno, según la Ley 1/1983:','["Interponer recursos de inconstitucionalidad y personarse ante el Tribunal Constitucional", "Designar a los Senadores que corresponden a la Comunidad y proponer su cese a la Asamblea", "Juzgar a los Consejeros y exigirles responsabilidad penal y civil por los actos cometidos en el ejercicio de su cargo", "Aprobar el Reglamento de la Asamblea"]'::jsonb,0,'Art. 21 l) Ley 1/1983','Es una atribución del Consejo de Gobierno.',null),
('adm-cm:7-d73dc5b6be','adm-cm',7,'Corresponde al Consejo de Gobierno nombrar y separar a los altos cargos de la Comunidad con categoría:','["De Jefe de Negociado", "Igual o superior a Director general", "Igual o superior a Jefe de Servicio", "De funcionario de carrera"]'::jsonb,1,'Art. 21 m) Ley 1/1983','Los nombramientos se hacen por Decreto.',null),
('adm-cm:7-28f4172036','adm-cm',7,'Ponen fin a la vía administrativa, según la Ley 1/1983:','["Los actos de trámite que decidan directa o indirectamente el fondo del asunto", "Las resoluciones del Presidente, del Consejo de Gobierno y sus Comisiones, y de los Consejeros, entre otras", "Las resoluciones de los Directores generales y de los Secretarios Generales Técnicos, en todo caso", "Las resoluciones de los Jefes de Servicio"]'::jsonb,1,'Art. 53.1 Ley 1/1983','Salvo que una ley establezca otra cosa.',null),
('adm-cm:7-a11ee30ee5','adm-cm',7,'El Consejo de Gobierno puede variar la denominación y el número de las Consejerías:','["Solo mediante ley de la Asamblea", "Por Decreto, dentro del límite establecido en el Estatuto", "Por orden del Consejero de Presidencia, previa deliberación del Consejo de Gobierno", "Solo mediante reforma del Estatuto"]'::jsonb,1,'Art. 19.3 Ley 1/1983','La estructura de Consejerías se fija por Decreto.',null),
('adm-cm:7-7d86ff06da','adm-cm',7,'Las disposiciones de los Consejeros adoptan la forma de:','["Decretos", "Acuerdos", "Decretos legislativos", "Órdenes"]'::jsonb,3,'Art. 50 Ley 1/1983','Las de los órganos inferiores se llaman Resoluciones.',null),
('adm-cm:7-9fde2258e0','adm-cm',7,'Los Directores generales deben elevar anualmente al Consejero:','["Su declaración de bienes y actividades", "La memoria anual de la Cámara de Cuentas sobre su centro directivo", "Un informe sobre la marcha, rendimiento y costes de sus servicios", "El anteproyecto de presupuesto de su Dirección General, que aprueba directamente el Consejero"]'::jsonb,2,'Art. 47 c) Ley 1/1983','Es una atribución de los Directores generales.',null),
('adm-cm:7-a2addd09f4','adm-cm',7,'Según la Ley 1/1983, la tramitación de los expedientes de gasto de la Consejería corresponde a:','["La Dirección General de Presupuestos en todo caso", "La Intervención General", "La Secretaría General Técnica", "El Gabinete del Consejero"]'::jsonb,2,'Art. 46.5 Ley 1/1983','Es una de las funciones de la Secretaría General Técnica.',null),
('adm-cm:7-279f1bd763','adm-cm',7,'En caso de ausencia de un Consejero, el Presidente puede encargar el despacho de su Consejería a otro Consejero:','["Previa autorización del Tribunal Superior de Justicia", "Sin ninguna comunicación", "Dando cuenta por escrito a la Asamblea", "Previo acuerdo de la Mesa de la Asamblea"]'::jsonb,2,'Art. 9 i) Ley 1/1983','Debe comunicarse por escrito a la Asamblea.',null),
('adm-cm:7-5e0cd31f4b','adm-cm',7,'La competencia para resolver los procedimientos de responsabilidad patrimonial corresponde, según la Ley 1/1983:','["Al Consejero respectivo", "Al Presidente de la Comunidad", "A la Asamblea", "Al Tribunal Superior de Justicia"]'::jsonb,0,'Art. 55.2 Ley 1/1983','Salvo los supuestos atribuidos a otros órganos.',null),
('adm-cm:7-85bdd63e69','adm-cm',7,'Según el art. 30.3 de la Ley 1/1983, la denominación de «Consejero»:','["Puede usarla cualquier asesor del Gobierno", "Es la que corresponde a los diputados de la Asamblea que forman parte de las comisiones de gobierno", "Corresponde también a los Viceconsejeros y a los Directores generales, cuando asistan al Consejo de Gobierno", "Queda reservada a los miembros del Gobierno o de determinadas instituciones de la Comunidad"]'::jsonb,3,'Art. 30.3 Ley 1/1983','Apartado añadido por la Ley 3/2007.',null),
('adm-cm:7-dee37d4725','adm-cm',7,'Las disposiciones y resoluciones del Consejo de Gobierno adoptan la forma de:','["Decretos del Consejo de Gobierno o Acuerdos", "Instrucciones", "Leyes o Decretos legislativos del Gobierno regional", "Órdenes del Consejo de Gobierno o Resoluciones"]'::jsonb,0,'Art. 50 Ley 1/1983','Las de los Consejeros adoptan la forma de Órdenes y las de órganos inferiores, Resoluciones.',null),
('adm-cm:7-57ce187c07','adm-cm',7,'Según la Ley 1/1983, las disposiciones administrativas de carácter general entran en vigor, salvo que dispongan otra cosa:','["Al día siguiente de su publicación en el Boletín Oficial del Estado", "A los veinte días de su publicación en el Boletín Oficial de la Comunidad de Madrid", "A los tres meses", "Al mes de su aprobación"]'::jsonb,1,'Art. 51.3 Ley 1/1983','Distinto de las leyes, que entran en vigor al día siguiente de su publicación en el BOCM (art. 40 EA).',null),
('adm-cm:7-9eb0a1a1ff','adm-cm',7,'Los Consejeros tienen la obligación de:','["Residir en la sede de la Asamblea", "Formar parte de la Mesa de la Asamblea y asistir a todas las sesiones de las comisiones parlamentarias", "Pedir autorización a la Asamblea para cada Orden", "Acudir a la Asamblea cuando esta lo reclame y contestar a sus preguntas e interpelaciones"]'::jsonb,3,'Art. 32.1 Ley 1/1983','Es parte del control parlamentario.',null),
('adm-cm:7-054d5bca12','adm-cm',7,'El cargo de Viceconsejero es:','["Compatible con el de Senador y con el de Diputado al mismo tiempo, acumulando sus dietas", "Compatible con el de Diputado de la Asamblea, sin acumular las dietas de este", "Un cargo electivo designado por la Asamblea a propuesta del Consejero correspondiente", "Incompatible con el de Diputado"]'::jsonb,1,'Art. 44.4 Ley 1/1983','Así lo dispone la Ley 1/1983.',null),
('adm-cm:8-6776e6b248','adm-cm',8,'¿Qué tratado creó en 1951 la Comunidad Europea del Carbón y del Acero?','["El Tratado de Roma", "El Tratado de Bruselas", "El Tratado de Maastricht", "El Tratado de París"]'::jsonb,3,'Tratados constitutivos','Los Tratados de Roma de 1957 crearon la CEE y la Comunidad Europea de la Energía Atómica (Euratom).',null),
('adm-cm:8-f5761dad8e','adm-cm',8,'Los Tratados de Roma de 1957 crearon:','["La Comunidad Europea del Carbón y del Acero y el Consejo de Europa con sede en Estrasburgo", "La Comunidad Económica Europea y la Comunidad Europea de la Energía Atómica", "La Unión Europea y el Banco Central Europeo como su institución monetaria común", "El Espacio Económico Europeo y la Unión Europea Occidental de defensa común"]'::jsonb,1,'Tratados constitutivos','La CECA se creó en 1951 por el Tratado de París.',null),
('adm-cm:8-aa9b1478e5','adm-cm',8,'¿Qué tratado creó la Unión Europea?','["El Tratado de Maastricht de 1992", "El Tratado de Ámsterdam de 1997", "El Tratado de Lisboa de 2007", "El Acta Única Europea de 1986"]'::jsonb,0,'Tratado de la Unión Europea','Se firmó en 1992 y entró en vigor en noviembre de 1993.',null),
('adm-cm:8-8f9bc182e1','adm-cm',8,'¿Cuándo entró en vigor el Tratado de Lisboa?','["El 1 de enero de 2008", "El 13 de diciembre de 2007", "El 1 de diciembre de 2009", "El 1 de noviembre de 1993"]'::jsonb,2,'Tratado de Lisboa','Se firmó el 13 de diciembre de 2007.',null),
('adm-cm:8-6e4d36b25f','adm-cm',8,'¿Desde qué fecha es España miembro de las Comunidades Europeas?','["Desde el 1 de enero de 1986", "Desde el 1 de enero de 1981", "Desde el 1 de noviembre de 1993", "Desde el 12 de junio de 1985"]'::jsonb,0,'Adhesión de España','El Tratado de adhesión se firmó el 12 de junio de 1985, junto con Portugal.',null),
('adm-cm:8-e6a795c94b','adm-cm',8,'¿Cuántas instituciones enumera el artículo 13 del Tratado de la Unión Europea?','["Cinco", "Seis", "Nueve", "Siete"]'::jsonb,3,'Art. 13 TUE','Parlamento Europeo, Consejo Europeo, Consejo, Comisión, Tribunal de Justicia de la UE, Banco Central Europeo y Tribunal de Cuentas.',null),
('adm-cm:8-cf380e4fcb','adm-cm',8,'¿Cuál de los siguientes NO es una institución de la Unión según el artículo 13 del TUE?','["El Comité de las Regiones", "El Tribunal de Cuentas", "El Banco Central Europeo", "El Consejo Europeo"]'::jsonb,0,'Art. 13 TUE','El Comité de las Regiones y el Comité Económico y Social son órganos consultivos, no instituciones.',null),
('adm-cm:8-c7e8d3b894','adm-cm',8,'¿Por cuánto tiempo se elige a los miembros del Parlamento Europeo?','["Cinco años", "Cuatro años", "Dos años y medio", "Seis años"]'::jsonb,0,'Art. 14.3 TUE','Se eligen por sufragio universal directo, libre y secreto.',null),
('adm-cm:8-55407166f5','adm-cm',8,'El número de miembros del Parlamento Europeo no puede exceder de:','["700, incluido el Presidente", "750, más el Presidente", "751, más el Presidente", "800, más el Presidente"]'::jsonb,1,'Art. 14.2 TUE','Ningún Estado puede tener más de 96 escaños ni menos de 6.',null),
('adm-cm:8-4314eeb997','adm-cm',8,'¿Dónde tiene su sede oficial el Parlamento Europeo?','["En Fráncfort", "En Luxemburgo", "En Bruselas", "En Estrasburgo"]'::jsonb,3,'Sedes de las instituciones','También trabaja en Bruselas y su Secretaría General está en Luxemburgo.',null),
('adm-cm:8-dcf5e10bed','adm-cm',8,'¿Quiénes componen el Consejo Europeo?','["Los Ministros de Asuntos Exteriores de los Estados miembros, el Alto Representante y el Presidente de la Comisión", "Un representante de cada Estado miembro de rango ministerial", "Los Presidentes de los Parlamentos nacionales de los Estados miembros y el Presidente del Parlamento Europeo", "Los Jefes de Estado o de Gobierno de los Estados miembros, su Presidente y el Presidente de la Comisión"]'::jsonb,3,'Art. 15.2 TUE','El Alto Representante participa en sus trabajos, pero no es miembro.',null),
('adm-cm:8-674f0e7e85','adm-cm',8,'El Presidente del Consejo Europeo es elegido por un mandato de:','["Seis meses, coincidiendo con la presidencia rotatoria", "Cinco años, no renovable", "Dos años, renovable indefinidamente", "Dos años y medio, renovable una sola vez"]'::jsonb,3,'Art. 15.5 TUE','Lo elige el propio Consejo Europeo por mayoría cualificada.',null),
('adm-cm:8-4a12198dae','adm-cm',8,'El Consejo de la Unión Europea está compuesto por:','["Un representante de cada Estado miembro de rango ministerial", "Un comisario por cada Estado miembro, nombrado por su Gobierno nacional", "Los Jefes de Estado o de Gobierno de los Estados miembros y su Presidente", "Los embajadores de los Estados miembros ante la Unión, con rango de representantes permanentes"]'::jsonb,0,'Art. 16.2 TUE','Ese representante puede comprometer al Gobierno de su Estado y ejercer el derecho de voto.',null),
('adm-cm:8-187bf9b6ec','adm-cm',8,'¿Cada cuánto tiempo rota la presidencia del Consejo de la Unión Europea entre los Estados miembros?','["Cada año", "Cada dos años y medio", "Cada seis meses", "Cada tres meses"]'::jsonb,2,'Presidencia del Consejo','La única excepción es el Consejo de Asuntos Exteriores, que preside el Alto Representante.',null),
('adm-cm:8-991d8d6fce','adm-cm',8,'Desde 2014, la mayoría cualificada en el Consejo se define como:','["Al menos dos tercios de los Estados miembros que representen como mínimo la mitad de la población de la Unión", "La mayoría absoluta de los Estados miembros, sea cual sea su población, siempre que incluya a los cuatro más poblados", "Al menos el 55 % de los miembros del Consejo que representen al menos el 65 % de la población de la Unión", "Al menos el 65 % de los miembros del Consejo que representen como mínimo el 55 % de la población de la Unión"]'::jsonb,2,'Art. 16.4 TUE','La minoría de bloqueo debe incluir al menos a cuatro miembros del Consejo.',null),
('adm-cm:8-76973ff4a7','adm-cm',8,'¿Qué institución tiene, como regla general, la iniciativa legislativa en la Unión Europea?','["La Comisión Europea", "El Consejo Europeo", "El Consejo de la Unión", "El Parlamento Europeo"]'::jsonb,0,'Art. 17.2 TUE','Los actos legislativos solo pueden adoptarse a propuesta de la Comisión, salvo que los Tratados dispongan otra cosa.',null),
('adm-cm:8-20126f5efb','adm-cm',8,'¿Cómo se elige al Presidente de la Comisión Europea?','["Lo eligen los ciudadanos de la Unión por sufragio universal directo cada cinco años", "Lo nombra el Consejo de la Unión por mayoría simple, a propuesta del Parlamento Europeo", "El Consejo Europeo propone un candidato por mayoría cualificada y el Parlamento Europeo lo elige por mayoría de sus miembros", "Lo elige directamente el Consejo Europeo por unanimidad, sin intervención del Parlamento"]'::jsonb,2,'Art. 17.7 TUE','El Consejo Europeo tiene en cuenta el resultado de las elecciones al Parlamento Europeo.',null),
('adm-cm:8-835612793e','adm-cm',8,'¿Qué cargo ocupa el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad dentro de la Comisión?','["Es su Secretario General, con voz pero sin voto", "Es uno de sus Vicepresidentes", "Es su Presidente, por razón de su cargo", "No forma parte de la Comisión, sino del Consejo Europeo"]'::jsonb,1,'Art. 18.4 TUE','Además preside el Consejo de Asuntos Exteriores.',null),
('adm-cm:8-739469b78f','adm-cm',8,'¿Dónde tiene su sede el Tribunal de Justicia de la Unión Europea?','["En Bruselas", "En Estrasburgo", "En Luxemburgo", "En La Haya"]'::jsonb,2,'Sedes de las instituciones','En La Haya está el Tribunal Internacional de Justicia y en Estrasburgo el Tribunal Europeo de Derechos Humanos, que no son órganos de la UE.',null),
('adm-cm:8-a744911a7d','adm-cm',8,'¿Dónde tiene su sede el Banco Central Europeo?','["En Ámsterdam", "En Luxemburgo", "En Bruselas", "En Fráncfort"]'::jsonb,3,'Sedes de las instituciones','El BCE dirige la política monetaria de la zona euro.',null),
('adm-cm:8-5cec018daf','adm-cm',8,'Según el artículo 288 del TFUE, el reglamento:','["Obliga al Estado destinatario en cuanto al resultado, dejando a las autoridades nacionales la elección de la forma y los medios", "No es vinculante y solo expresa una opinión de las instituciones", "Tiene alcance general, es obligatorio en todos sus elementos y directamente aplicable en cada Estado miembro", "Solo es obligatorio para sus destinatarios, que deben estar designados en él"]'::jsonb,2,'Art. 288 TFUE','La segunda opción describe la directiva, la tercera la decisión y la cuarta los dictámenes.',null),
('adm-cm:8-296ba9ef0e','adm-cm',8,'¿Qué acto de la Unión obliga al Estado miembro destinatario en cuanto al resultado que deba conseguirse, dejando a las autoridades nacionales la elección de la forma y de los medios?','["La recomendación", "La decisión", "El reglamento", "La directiva"]'::jsonb,3,'Art. 288 TFUE','Las directivas deben transponerse al derecho interno.',null),
('adm-cm:8-e990657e8d','adm-cm',8,'Según el artículo 288 del TFUE, las recomendaciones y los dictámenes:','["Son obligatorios en todos sus elementos", "Solo obligan a sus destinatarios", "Obligan solo en cuanto al resultado", "No son vinculantes"]'::jsonb,3,'Art. 288 TFUE','Son actos de las instituciones sin fuerza obligatoria.',null),
('adm-cm:8-4af4277374','adm-cm',8,'En el procedimiento legislativo ordinario, los actos se adoptan conjuntamente por:','["El Consejo Europeo y el Parlamento, a propuesta del Consejo", "La Comisión y el Consejo Europeo, oído el Parlamento", "El Parlamento Europeo y el Consejo, a propuesta de la Comisión", "El Consejo de la Unión por unanimidad, previa consulta al Parlamento"]'::jsonb,2,'Art. 294 TFUE','Antes del Tratado de Lisboa se llamaba procedimiento de codecisión.',null),
('adm-cm:8-3b58342af9','adm-cm',8,'¿Quién elige al Defensor del Pueblo Europeo?','["El Tribunal de Justicia", "El Consejo Europeo", "El Parlamento Europeo", "La Comisión Europea"]'::jsonb,2,'Art. 228 TFUE','Recibe reclamaciones sobre casos de mala administración en la acción de las instituciones, órganos y organismos de la Unión.',null),
('adm-cm:8-0923eceabd','adm-cm',8,'¿Cuántos ciudadanos de la Unión, como mínimo, deben respaldar una iniciativa ciudadana europea?','["Quinientos mil, de al menos cinco Estados miembros distintos de la Unión", "Dos millones, procedentes como mínimo de la mitad de los Estados miembros", "Cien mil, sin importar su nacionalidad ni su Estado de residencia", "Un millón, de un número significativo de Estados miembros"]'::jsonb,3,'Art. 11.4 TUE','Con ella se invita a la Comisión a presentar una propuesta legislativa.',null),
('adm-cm:8-5569a567a5','adm-cm',8,'¿Qué artículo del Tratado de la Unión Europea regula la retirada voluntaria de un Estado miembro?','["El artículo 7", "El artículo 49", "El artículo 50", "El artículo 48"]'::jsonb,2,'Art. 50 TUE','El artículo 49 regula la adhesión, el 7 la suspensión de derechos y el 48 la revisión de los Tratados.',null),
('adm-cm:8-8bd6788b0e','adm-cm',8,'¿Cuántos Estados miembros tiene actualmente la Unión Europea?','["28", "25", "26", "27"]'::jsonb,3,'Estados miembros','Son 27 desde la salida del Reino Unido en 2020.',null),
('adm-cm:8-cd514b8a8d','adm-cm',8,'¿A qué institución corresponde el control de las cuentas de la Unión?','["Al Banco Central Europeo", "A la Oficina Europea de Lucha contra el Fraude", "Al Tribunal de Justicia de la Unión", "Al Tribunal de Cuentas Europeo"]'::jsonb,3,'Art. 285 TFUE','Tiene su sede en Luxemburgo y está formado por un nacional de cada Estado miembro.',null),
('adm-cm:9-d246a16197','adm-cm',9,'Según el art. 1.1 del Código Civil, las fuentes del ordenamiento jurídico español son:','["La ley, la costumbre y los principios generales del derecho", "La ley, la jurisprudencia del Tribunal Supremo y los principios generales del derecho", "La ley, la costumbre y la jurisprudencia", "La Constitución, la ley y la costumbre"]'::jsonb,0,'Art. 1.1 CC','Las fuentes son la ley, la costumbre y los principios generales del derecho.','oct. 2026 · 1.er ejercicio | nov. 2024 · 1.er ejercicio'),
('adm-cm:9-f9280f5337','adm-cm',9,'Según el Código Civil, las disposiciones que contradigan otra de rango superior:','["Son válidas si son posteriores", "Carecerán de validez", "Prevalecen si son más específicas", "Solo son anulables a instancia de parte"]'::jsonb,1,'Art. 1.2 CC','Carecerán de validez las disposiciones que contradigan otra de rango superior.',null),
('adm-cm:9-ad161133fe','adm-cm',9,'La costumbre rige:','["En defecto de ley aplicable, aunque sea contraria a la moral, siempre que resulte probada ante el juez", "En igualdad de rango con la ley, siempre que resulte probada y no sea contraria al orden público ni a la moral", "En defecto de ley aplicable, si no es contraria a la moral ni al orden público y resulta probada", "Solo cuando la reconozca expresamente una sentencia firme del Tribunal Supremo"]'::jsonb,2,'Art. 1.3 CC','La costumbre solo rige en defecto de ley aplicable, siempre que no sea contraria a la moral o al orden público y que resulte probada.',null),
('adm-cm:9-2c2dabc7ec','adm-cm',9,'Los principios generales del derecho se aplican:','["Antes que la costumbre, por su carácter informador de todo el ordenamiento jurídico", "Solo cuando así lo prevea expresamente una ley", "En igualdad de rango con la ley y con la costumbre, según el caso concreto", "En defecto de ley o costumbre, sin perjuicio de su carácter informador del ordenamiento"]'::jsonb,3,'Art. 1.4 CC','Se aplican en defecto de ley o costumbre, sin perjuicio de su carácter informador del ordenamiento jurídico.',null),
('adm-cm:9-67276a6f39','adm-cm',9,'Según el Código Civil, la jurisprudencia:','["Complementa el ordenamiento con la doctrina reiterada del Tribunal Supremo", "Es fuente directa del ordenamiento, al mismo nivel que la ley", "Complementa el ordenamiento con la doctrina de cualquier juzgado o tribunal", "Complementa el ordenamiento con la doctrina reiterada del Tribunal Constitucional"]'::jsonb,0,'Art. 1.6 CC','Complementa el ordenamiento con la doctrina reiterada del Tribunal Supremo al interpretar y aplicar la ley, la costumbre y los principios generales.',null),
('adm-cm:9-815ca613d9','adm-cm',9,'Los jueces y tribunales, ante un asunto del que conozcan:','["Pueden abstenerse de resolver si no encuentran ley aplicable", "Tienen el deber inexcusable de resolver, ateniéndose al sistema de fuentes", "Tienen el deber de resolver solo si existe ley o jurisprudencia previa", "Deben elevar consulta al Tribunal Supremo si no hay ley aplicable"]'::jsonb,1,'Art. 1.7 CC','Tienen el deber inexcusable de resolver en todo caso, ateniéndose al sistema de fuentes establecido.',null),
('adm-cm:9-e528fa043d','adm-cm',9,'Si una ley no dice otra cosa, ¿cuándo entra en vigor?','["Al día siguiente de su completa publicación en el BOE", "Al mes de su completa publicación en el Boletín Oficial del Estado", "A los veinte días de su completa publicación en el BOE", "A los quince días hábiles de su completa publicación en el Boletín Oficial del Estado"]'::jsonb,2,'Art. 2.1 CC','Las leyes entran en vigor a los veinte días de su completa publicación en el BOE, si en ellas no se dispone otra cosa.',null),
('adm-cm:9-c72e19db00','adm-cm',9,'Según el Código Civil, las leyes se derogan:','["Por el desuso", "Por la costumbre contraria", "Por sentencia de cualquier juez", "Solo por otras leyes posteriores"]'::jsonb,3,'Art. 2.2 CC','Las leyes solo se derogan por otras posteriores.',null),
('adm-cm:9-b446e92343','adm-cm',9,'Según el Código Civil, las leyes:','["No tienen efecto retroactivo si no dispusieren lo contrario", "Tienen efecto retroactivo si no dispusieren lo contrario", "No pueden tener efecto retroactivo en ningún caso, aunque lo disponga expresamente la propia ley", "Solo tienen efecto retroactivo si son favorables y así lo dicen"]'::jsonb,0,'Art. 2.3 CC','Las leyes no tienen efecto retroactivo si no dispusieren lo contrario.',null),
('adm-cm:9-9b20924022','adm-cm',9,'La ignorancia de las leyes:','["Excusa de su cumplimiento", "No excusa de su cumplimiento", "Excusa solo a los extranjeros", "Excusa durante el primer año de vigencia"]'::jsonb,1,'Art. 6.1 CC','La ignorancia de las leyes no excusa de su cumplimiento.',null),
('adm-cm:9-a420f6b08b','adm-cm',9,'Podrá prescindirse de los trámites de consulta, audiencia e información públicas en el caso de normas:','["Tributarias o sancionadoras, o cuando concurran razones graves de interés público", "Que afecten a derechos de los ciudadanos, o cuando concurran razones de urgencia", "Sancionadoras y de organización del procedimiento", "Presupuestarias u organizativas, o cuando concurran razones graves de interés público"]'::jsonb,3,'Art. 133.4 Ley 39/2015','Excepción prevista para normas presupuestarias u organizativas o razones graves de interés público.',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('adm-cm:9-1a6b8fcfdc','adm-cm',9,'Con carácter previo a la elaboración de un proyecto de ley o reglamento, se sustanciará una consulta pública a través del portal web sobre:','["El coste de la publicación de la norma en el BOE", "La opinión del Consejo de Estado y del órgano proponente", "Los problemas que se pretenden solucionar, la necesidad y oportunidad, los objetivos y las posibles soluciones alternativas", "El texto articulado completo del proyecto, el informe de impacto normativo, la memoria económica y el dictamen del Consejo de Estado"]'::jsonb,2,'Art. 133.1 Ley 39/2015','Son los cuatro aspectos de la consulta pública previa.',null),
('adm-cm:9-eb665216e3','adm-cm',9,'Para que entren en vigor y produzcan efectos jurídicos, las normas con rango de ley, los reglamentos y disposiciones administrativas habrán de:','["Publicarse en el diario oficial correspondiente", "Firmarse por el Rey y comunicarse a las Cortes Generales", "Comunicarse a todos los Ayuntamientos y Diputaciones afectados", "Aprobarse por referéndum"]'::jsonb,0,'Art. 131 Ley 39/2015','La publicación en el diario oficial es requisito de entrada en vigor.',null),
('adm-cm:9-5a819fe6d9','adm-cm',9,'¿Cuáles son los principios de buena regulación del art. 129 de la Ley 39/2015?','["Eficacia, jerarquía, descentralización, desconcentración y coordinación", "Necesidad, eficacia, proporcionalidad, seguridad jurídica, transparencia y eficiencia", "Igualdad, mérito, capacidad y publicidad", "Necesidad, eficacia, proporcionalidad, seguridad jurídica, publicidad y jerarquía"]'::jsonb,1,'Art. 129.1 Ley 39/2015','Son seis principios de buena regulación.',null),
('adm-cm:9-33d53e9ab4','adm-cm',9,'Los reglamentos y disposiciones administrativas NO podrán:','["Desarrollar una ley", "Publicarse en el BOE", "Regular la organización interna de la Administración ni el funcionamiento de sus órganos colegiados y unidades administrativas", "Tipificar delitos, faltas o infracciones administrativas, establecer penas o sanciones, ni tributos"]'::jsonb,3,'Art. 128.2 Ley 39/2015','Tampoco vulnerar la Constitución o las leyes ni regular materias reservadas a las Cortes o a las Asambleas autonómicas.',null),
('adm-cm:9-140a90c80d','adm-cm',9,'Según la Ley 39/2015, el Gobierno de la Nación ejercerá la iniciativa legislativa en los términos de la Constitución mediante:','["La iniciativa legislativa popular", "Las proposiciones de ley del Senado", "La elaboración y aprobación de los anteproyectos de ley y la remisión de los proyectos de ley a las Cortes Generales", "La elaboración de proposiciones de ley que remite a las Cortes Generales a través del Consejo de Estado"]'::jsonb,2,'Art. 127 Ley 39/2015','También podrá aprobar reales decretos-leyes y reales decretos legislativos.',null),
('adm-cm:9-d5710db4cf','adm-cm',9,'Según el principio de eficiencia del art. 129.6, la iniciativa normativa debe:','["Aumentar los trámites para garantizar el control", "Aprobarse sin consulta pública previa ni trámite de audiencia, para reducir la duración del procedimiento normativo", "Evitar cargas administrativas innecesarias o accesorias y racionalizar la gestión de los recursos públicos", "Evitar cargas administrativas innecesarias, aunque suponga aumentar el gasto público y crear nuevos órganos"]'::jsonb,2,'Art. 129.6 Ley 39/2015','Eficiencia: evitar cargas innecesarias o accesorias.',null),
('adm-cm:9-3ea6857090','adm-cm',9,'El Plan Anual Normativo que deben aprobar las Administraciones contiene:','["Los presupuestos y las normas fiscales del año siguiente", "Las iniciativas legales o reglamentarias que vayan a ser elevadas para su aprobación en el año siguiente", "Las iniciativas reglamentarias, pero no las legales, que se aprobarán en los cuatro años siguientes", "Las normas derogadas el año anterior"]'::jsonb,1,'Art. 132.1 Ley 39/2015','Se aprueba anualmente y se publica en el Portal de la Transparencia.',null),
('adm-cm:9-e58eedd5dc','adm-cm',9,'Según el art. 128.3 de la Ley 39/2015, las disposiciones administrativas:','["Se ajustarán al orden de jerarquía y ninguna podrá vulnerar los preceptos de otra de rango superior", "Tienen todas el mismo rango, y prevalece la posterior", "Prevalecen sobre las leyes", "Se ajustarán al orden de jerarquía, salvo que la de rango inferior sea posterior en el tiempo y regule una materia más específica"]'::jsonb,0,'Art. 128.3 Ley 39/2015','Principio de jerarquía normativa.',null),
('adm-cm:9-c4cfa32d6e','adm-cm',9,'Según el art. 130.1, las Administraciones Públicas revisarán periódicamente su normativa vigente para:','["Derogarla cada cuatro años y aprobar textos refundidos", "Remitirla al Tribunal Constitucional para que verifique su adecuación a la Constitución y a los Estatutos de Autonomía", "Adaptarla a los principios de buena regulación, sin necesidad de evaluar si ha conseguido sus objetivos", "Adaptarla a los principios de buena regulación y comprobar en qué medida han conseguido sus objetivos"]'::jsonb,3,'Art. 130.1 Ley 39/2015','El resultado de la evaluación se plasma en un informe que se hará público.',null),
('adm-cm:9-3257431fd3','adm-cm',9,'Según la Ley 50/1997, del Gobierno, ¿qué reglamentos tienen mayor rango?','["Los aprobados por orden ministerial conjunta de varios Ministros", "Los aprobados por real decreto", "Los aprobados por resolución de un Secretario de Estado", "Los aprobados por instrucción o circular de un Subsecretario"]'::jsonb,1,'Art. 24.2 Ley 50/1997','Primero van las disposiciones aprobadas por real decreto del Presidente del Gobierno o acordado en el Consejo de Ministros, y después las aprobadas por orden ministerial.',null),
('adm-cm:9-803a3e5d41','adm-cm',9,'Según el Código Civil, las normas jurídicas contenidas en los tratados internacionales serán de aplicación directa en España:','["Cuando hayan pasado a formar parte del ordenamiento interno mediante su publicación íntegra en el BOE", "Desde su ratificación por el Rey, aunque la publicación en el BOE sea solo de un extracto", "Desde su firma por el Gobierno, aunque todavía no se hayan publicado en ningún diario oficial", "A los veinte días de su publicación en el Diario Oficial de la Unión Europea, en todo caso"]'::jsonb,0,'Art. 1.5 CC','El art. 1.5 CC exige que hayan pasado a formar parte del ordenamiento interno mediante su publicación íntegra en el BOE.',null),
('adm-cm:9-46b5145778','adm-cm',9,'Según el art. 3.1 del Código Civil, las normas se interpretarán atendiendo fundamentalmente a:','["Su sentido literal", "Sus antecedentes históricos", "Su espíritu y finalidad", "La realidad social del momento en que se aprobaron"]'::jsonb,2,'Art. 3.1 CC','Se atiende al sentido de las palabras, el contexto, los antecedentes y la realidad social, pero fundamentalmente al espíritu y finalidad.',null),
('adm-cm:9-29e03bfba9','adm-cm',9,'Según el Código Civil, las resoluciones de los tribunales solo podrán descansar de manera exclusiva en la equidad:','["Cuando no exista costumbre aplicable al caso", "Cuando las partes lo soliciten de común acuerdo", "Cuando la ley expresamente lo permita", "En los asuntos de cuantía inferior a 6.000 euros"]'::jsonb,2,'Art. 3.2 CC','La equidad se pondera en la aplicación de las normas, pero las resoluciones solo pueden basarse exclusivamente en ella cuando la ley lo permita.',null),
('adm-cm:9-cf21c3cf42','adm-cm',9,'Procede la aplicación analógica de las normas cuando estas no contemplen un supuesto específico, pero regulen otro semejante:','["Siempre que se trate de normas penales o sancionadoras", "Aunque no exista identidad de razón entre ambos", "Solo si así lo acuerda la jurisprudencia del Tribunal Supremo", "Entre los que se aprecie identidad de razón"]'::jsonb,3,'Art. 4.1 CC','El art. 4.1 CC exige que entre el supuesto regulado y el no regulado se aprecie identidad de razón.',null),
('adm-cm:9-cefa1de2de','adm-cm',9,'Según el Código Civil, ¿qué leyes NO se aplicarán a supuestos ni en momentos distintos de los comprendidos expresamente en ellas?','["Las orgánicas, las ordinarias y los decretos legislativos", "Las penales, las excepcionales y las de ámbito temporal", "Las de bases, las de armonización y los decretos-leyes", "Las autonómicas, las forales y las de régimen local"]'::jsonb,1,'Art. 4.2 CC','Las leyes penales, las excepcionales y las de ámbito temporal no admiten aplicación analógica.',null),
('adm-cm:9-50dc426aa0','adm-cm',9,'Las disposiciones del Código Civil se aplicarán en las materias regidas por otras leyes:','["Como supletorias", "Solo en defecto de costumbre", "Con carácter preferente", "Solo si lo prevé la otra ley"]'::jsonb,0,'Art. 4.3 CC','El art. 4.3 CC establece la aplicación supletoria del Código Civil en las materias regidas por otras leyes.',null),
('adm-cm:9-012e6dc664','adm-cm',9,'En el cómputo civil de los plazos, según el Código Civil:','["Se excluyen los días inhábiles del mes de agosto", "No se excluyen los días inhábiles", "Se excluyen los sábados y domingos", "Se excluyen solo los días festivos nacionales"]'::jsonb,1,'Art. 5.2 CC','A diferencia del cómputo administrativo, en el cómputo civil no se excluyen los días inhábiles.',null),
('adm-cm:9-263aa6b504','adm-cm',9,'La exclusión voluntaria de la ley aplicable y la renuncia a los derechos en ella reconocidos solo serán válidas:','["Cuando las autorice previamente el juez del domicilio del renunciante", "Cuando consten en documento público otorgado ante notario, en todo caso", "Cuando se refieran a derechos patrimoniales de cuantía inferior a 3.000 euros", "Cuando no contraríen el interés o el orden público ni perjudiquen a terceros"]'::jsonb,3,'Art. 6.2 CC','El art. 6.2 CC solo admite la exclusión o renuncia si no contraría el interés o el orden público ni perjudica a terceros.',null),
('adm-cm:9-bb2c76dd6a','adm-cm',9,'Según el Código Civil, los actos contrarios a las normas imperativas y a las prohibitivas son:','["Anulables a instancia de parte durante el plazo de cuatro años desde su celebración", "Nulos de pleno derecho en todo caso, sin que la norma pueda prever otro efecto", "Nulos de pleno derecho, salvo que en ellas se establezca un efecto distinto para el caso de contravención", "Válidos, aunque quien los realiza debe indemnizar los daños y perjuicios causados"]'::jsonb,2,'Art. 6.3 CC','Son nulos de pleno derecho, salvo que la norma establezca un efecto distinto para el caso de contravención.',null),
('adm-cm:9-a692fa8fed','adm-cm',9,'Los actos realizados al amparo de una norma que persigan un resultado prohibido por el ordenamiento se consideran ejecutados en fraude de ley y:','["No impedirán la debida aplicación de la norma que se hubiere tratado de eludir", "Serán válidos si la norma de cobertura tiene rango de ley", "Darán lugar siempre a responsabilidad penal de sus autores", "Producirán efectos hasta que un juez declare su nulidad"]'::jsonb,0,'Art. 6.4 CC','El fraude de ley no impide la debida aplicación de la norma que se hubiere tratado de eludir.',null),
('adm-cm:9-dd7f5bffb6','adm-cm',9,'Según el art. 7 del Código Civil, la ley no ampara:','["La aplicación supletoria del propio Código Civil", "La renuncia a derechos que no perjudique a terceros", "El ejercicio de los derechos conforme a la buena fe", "El abuso del derecho ni su ejercicio antisocial"]'::jsonb,3,'Art. 7.2 CC','El art. 7.2 CC: la ley no ampara el abuso del derecho o su ejercicio antisocial; el art. 7.1 exige ejercitar los derechos conforme a la buena fe.',null),
('adm-cm:9-c3f1b0c85f','adm-cm',9,'La consulta pública previa a la elaboración de un proyecto normativo, a través del portal web de la Administración competente, es un instrumento de:','["Participación ciudadana en la elaboración de normas", "Rendición de cuentas de los altos cargos ante el Congreso", "Fiscalización económica de la Administración", "Control parlamentario del Gobierno"]'::jsonb,0,'Art. 133.1 Ley 39/2015','Busca la opinión de los sujetos y organizaciones más representativas potencialmente afectados por la futura norma.',null),
('adm-cm:10-404cc06afb','adm-cm',10,'Según la Ley 40/2015, ¿qué carácter tiene la competencia de los órganos administrativos?','["Delegable en todo caso", "Renunciable con autorización del superior", "Transferible a otras Administraciones por convenio", "Irrenunciable"]'::jsonb,3,'Art. 8.1 Ley 40/2015','La competencia es irrenunciable y se ejerce por los órganos que la tengan atribuida como propia, salvo delegación o avocación.',null),
('adm-cm:10-6e6bf57c91','adm-cm',10,'¿Cuál de estas técnicas sí altera la titularidad de la competencia?','["La desconcentración", "La delegación de competencias", "La delegación de firma", "La encomienda de gestión"]'::jsonb,0,'Art. 8 Ley 40/2015','La delegación, la encomienda, la delegación de firma y la suplencia no alteran la titularidad; la desconcentración transfiere titularidad y ejercicio a órganos dependientes.',null),
('adm-cm:10-e9711fb132','adm-cm',10,'Si una norma atribuye una competencia a una Administración sin especificar el órgano, ¿a quién corresponde instruir y resolver?','["Al órgano superior de esa Administración por razón de la materia, en todo caso y sin excepción", "A los órganos inferiores competentes por razón de la materia y del territorio", "Al órgano que designe en cada caso el titular del departamento ministerial correspondiente", "Al órgano que primero conozca del asunto"]'::jsonb,1,'Art. 8.3 Ley 40/2015','Corresponde a los órganos inferiores competentes por materia y territorio; si hay varios, a su superior jerárquico común.',null),
('adm-cm:10-f5bc47695b','adm-cm',10,'¿Puede delegarse la competencia para adoptar disposiciones de carácter general?','["Sí, en órganos dependientes jerárquicamente", "Sí, si lo autoriza el superior jerárquico", "Solo en el ámbito de la Administración local", "No, en ningún caso"]'::jsonb,3,'Art. 9.2 b) Ley 40/2015','No pueden delegarse las competencias relativas a la adopción de disposiciones de carácter general.',null),
('adm-cm:10-90130f901d','adm-cm',10,'¿Puede delegarse la resolución de recursos en el mismo órgano que dictó el acto recurrido?','["Sí, si el recurso es de reposición", "Sí, con publicación en el boletín oficial", "No, está expresamente prohibido", "Solo si lo prevé el reglamento orgánico"]'::jsonb,2,'Art. 9.2 c) Ley 40/2015','No pueden delegarse las competencias relativas a la resolución de recursos en los órganos que hayan dictado los actos recurridos.',null),
('adm-cm:10-2ad4696214','adm-cm',10,'¿Dónde deben publicarse las delegaciones de competencias de un órgano de la Comunidad Autónoma de Canarias?','["No necesitan publicación", "En el Boletín Oficial del Estado", "En el Boletín Oficial de Canarias", "En el tablón de anuncios del órgano"]'::jsonb,2,'Art. 9.3 Ley 40/2015','Las delegaciones y su revocación se publican en el boletín de la Administración a que pertenezca el órgano delegante: para Canarias, el BOC.',null),
('adm-cm:10-e1b18af876','adm-cm',10,'¿A qué órgano se consideran dictadas las resoluciones adoptadas por delegación?','["A ambos de forma solidaria", "Al órgano delegado", "Al superior jerárquico común", "Al órgano delegante"]'::jsonb,3,'Art. 9.4 Ley 40/2015','Las resoluciones adoptadas por delegación indicarán esta circunstancia y se considerarán dictadas por el órgano delegante.',null),
('adm-cm:10-b0ed6d05e0','adm-cm',10,'¿Pueden delegarse las competencias que se ejercen por delegación?','["No, salvo autorización expresa de una ley", "No, en ningún caso, ni siquiera por ley", "Sí, con consentimiento del delegante", "Sí, siempre que se publique"]'::jsonb,0,'Art. 9.5 Ley 40/2015','Salvo autorización expresa de una ley, no podrán delegarse las competencias que se ejerzan por delegación.',null),
('adm-cm:10-1abfbe59ca','adm-cm',10,'¿Cuándo puede revocarse una delegación de competencias?','["Previa audiencia del órgano delegado", "En cualquier momento, por el órgano que la confirió", "Solo al finalizar el plazo fijado", "Solo por el superior jerárquico del delegante"]'::jsonb,1,'Art. 9.6 Ley 40/2015','La delegación es revocable en cualquier momento por el órgano que la haya conferido.',null),
('adm-cm:10-2b95cadff2','adm-cm',10,'¿Cabe recurso contra el acuerdo de avocación?','["Sí, recurso de alzada ante el superior jerárquico del órgano que haya acordado la avocación", "Solo recurso contencioso-administrativo directo", "No, aunque puede impugnarse en el recurso contra la resolución del procedimiento", "Sí, recurso potestativo de reposición"]'::jsonb,2,'Art. 10.2 Ley 40/2015','Contra el acuerdo de avocación no cabe recurso, aunque puede impugnarse en el que se interponga contra la resolución final.',null),
('adm-cm:10-0282267023','adm-cm',10,'¿Qué requisito formal debe cumplir la avocación?','["Publicación en el boletín oficial correspondiente antes de que surta efecto la avocación", "Acuerdo motivado notificado a los interesados antes o a la vez que la resolución final", "Informe previo del órgano delegado", "Autorización del órgano colegiado superior"]'::jsonb,1,'Art. 10.2 Ley 40/2015','La avocación se realiza mediante acuerdo motivado notificado a los interesados con anterioridad o simultáneamente a la resolución final.',null),
('adm-cm:10-9061bc4410','adm-cm',10,'En una delegación en órganos no dependientes jerárquicamente, ¿quién puede avocar un asunto?','["Cualquier órgano superior", "El órgano delegado, devolviéndolo", "El superior jerárquico del órgano delegado", "Únicamente el órgano delegante"]'::jsonb,3,'Art. 10.1 Ley 40/2015','En la delegación en órganos no dependientes jerárquicamente, solo puede avocar el órgano delegante.',null),
('adm-cm:10-700f1e48d7','adm-cm',10,'¿Qué puede ser objeto de encomienda de gestión?','["Actividades de carácter material o técnico", "La adopción de disposiciones generales", "La resolución de procedimientos", "Prestaciones propias de los contratos del sector público"]'::jsonb,0,'Art. 11.1 Ley 40/2015','Se encomienda la realización de actividades de carácter material o técnico; no puede tener por objeto prestaciones propias de los contratos.',null),
('adm-cm:10-463eaa93a5','adm-cm',10,'En una encomienda de gestión, ¿qué condición tiene el órgano encomendado respecto de los datos personales?','["Corresponsable del tratamiento", "Encargado del tratamiento", "Responsable del tratamiento", "Delegado de protección de datos"]'::jsonb,1,'Art. 11.2 Ley 40/2015','El órgano o entidad encomendado tiene la condición de encargado del tratamiento de los datos personales.',null),
('adm-cm:10-b95ed8c591','adm-cm',10,'¿Cómo se formaliza una encomienda de gestión entre órganos de distintas Administraciones?','["Por resolución del órgano encomendado", "Por acuerdo verbal de los titulares", "Mediante convenio publicado en el boletín oficial correspondiente", "Mediante contrato administrativo de servicios adjudicado sin publicidad"]'::jsonb,2,'Art. 11.3 b) Ley 40/2015','Entre distintas Administraciones se formaliza mediante convenio, que debe publicarse en el boletín correspondiente.',null),
('adm-cm:10-63205ad571','adm-cm',10,'¿Necesita publicación la delegación de firma para su validez?','["Sí, en el boletín oficial correspondiente", "Solo si afecta a resoluciones sancionadoras", "Sí, en el tablón de edictos", "No"]'::jsonb,3,'Art. 12.2 Ley 40/2015','La delegación de firma no altera la competencia del delegante y para su validez no es necesaria su publicación.',null),
('adm-cm:10-81415c3291','adm-cm',10,'¿En quién puede delegarse la firma de resoluciones y actos?','["En los titulares de órganos o unidades que dependan del delegante", "En cualquier funcionario de la Administración", "En órganos de otras Administraciones", "Solo en el superior jerárquico"]'::jsonb,0,'Art. 12.1 Ley 40/2015','La firma puede delegarse en los titulares de los órganos o unidades administrativas que dependan del delegante.',null),
('adm-cm:10-0fec3d19d7','adm-cm',10,'Si no se designa suplente para un órgano vacante, ¿quién ejerce su competencia?','["Nadie hasta el nombramiento del nuevo titular", "Quien designe el órgano inmediato superior", "El órgano delegado más reciente", "El funcionario de mayor antigüedad del órgano"]'::jsonb,1,'Art. 13.1 Ley 40/2015','Si no se designa suplente, la competencia se ejerce por quien designe el órgano administrativo inmediato superior.',null),
('adm-cm:10-9788a287f4','adm-cm',10,'¿Entre qué órganos pueden suscitarse conflictos de atribuciones según la Ley 40/2015?','["Entre órganos de una misma Administración no relacionados jerárquicamente", "Entre órganos de distintas Administraciones", "Entre un órgano y su superior jerárquico, cuando discrepen sobre la competencia para resolver", "Entre cualquier órgano y otro de la misma o distinta Administración, una vez finalizado el procedimiento"]'::jsonb,0,'Art. 14.3 Ley 40/2015','Los conflictos de atribuciones solo pueden suscitarse entre órganos de una misma Administración no relacionados jerárquicamente y en procedimientos no finalizados.',null),
('adm-cm:10-a0fe791c15','adm-cm',10,'¿Qué debe hacer el órgano que se estime incompetente para resolver un asunto?','["Solicitar informe al Consejo Consultivo", "Archivar el expediente y notificar a los interesados que deben presentar nueva solicitud ante otro órgano", "Remitir directamente las actuaciones al competente y notificarlo a los interesados", "Devolver la solicitud al interesado para que la presente ante el órgano que considere competente"]'::jsonb,2,'Art. 14.1 Ley 40/2015','Remitirá directamente las actuaciones al órgano que considere competente, notificándolo a los interesados.',null),
('adm-cm:10-44d19492f6','adm-cm',10,'Según la Ley 40/2015, ¿qué unidades administrativas tienen la consideración de órganos administrativos?','["Las creadas por ley, con independencia de sus funciones y de sus efectos", "Las que dirijan un funcionario de carrera del subgrupo A1 con nivel 30", "Las que tengan atribuidas funciones con efectos jurídicos frente a terceros o cuya actuación tenga carácter preceptivo", "Todas las que figuren en la relación de puestos de trabajo del departamento, con independencia de sus funciones y efectos"]'::jsonb,2,'Art. 5.1 Ley 40/2015','El art. 5.1 considera órganos administrativos las unidades con funciones que tengan efectos jurídicos frente a terceros o cuya actuación tenga carácter preceptivo.',null),
('adm-cm:10-04f7967292','adm-cm',10,'¿Cuál de estos requisitos exige como mínimo la Ley 40/2015 para crear un órgano administrativo?','["Su aprobación por ley del Parlamento", "La previa supresión de otro órgano de igual rango", "La dotación de los créditos necesarios para su puesta en marcha y funcionamiento", "El informe favorable del Consejo de Estado"]'::jsonb,2,'Art. 5.3 Ley 40/2015','Se exige determinar su integración y dependencia jerárquica, delimitar sus funciones y competencias y dotar los créditos necesarios.',null),
('adm-cm:10-01096f3f5a','adm-cm',10,'¿Pueden crearse órganos que dupliquen otros ya existentes según la Ley 40/2015?','["No, en ningún caso, aunque se suprima o restrinja debidamente la competencia del órgano existente", "Sí, si actúan sobre distinto colectivo de la misma población", "Solo si al mismo tiempo se suprime o restringe debidamente la competencia de estos", "Sí, siempre que lo autorice el titular del departamento"]'::jsonb,2,'Art. 5.4 Ley 40/2015','El art. 5.4 prohíbe crear órganos que dupliquen otros si al mismo tiempo no se suprime o restringe debidamente la competencia de estos.',null),
('adm-cm:10-a366e2d1a5','adm-cm',10,'¿Quién puede ser secretario de un órgano colegiado según la Ley 40/2015?','["Solo un funcionario de carrera del subgrupo A1 que no sea miembro del órgano ni tenga derecho a voto", "El miembro de menor antigüedad del órgano", "Un letrado de los servicios jurídicos, en todo caso", "Un miembro del propio órgano o una persona al servicio de la Administración correspondiente"]'::jsonb,3,'Art. 16.1 Ley 40/2015','El art. 16.1 permite que el secretario sea miembro del órgano o una persona al servicio de la Administración.',null),
('adm-cm:10-83bd0ba71c','adm-cm',10,'¿Qué asistencia exige la Ley 40/2015 para la válida constitución de un órgano colegiado?','["El presidente y un tercio de sus miembros", "La mayoría absoluta de sus miembros, sin necesidad de la asistencia del secretario ni de su suplente", "Presidente y secretario, o quienes les suplan, y la mitad, al menos, de sus miembros", "Dos tercios de sus miembros, entre ellos el presidente"]'::jsonb,2,'Art. 17.2 Ley 40/2015','Se requiere la asistencia, presencial o a distancia, del presidente y del secretario o de quienes les suplan, y la de la mitad, al menos, de sus miembros.',null),
('adm-cm:10-65bb325914','adm-cm',10,'¿Puede un órgano colegiado reunirse sin convocatoria previa según la Ley 40/2015?','["Solo en segunda convocatoria", "No, la convocatoria es siempre obligatoria", "Sí, si lo decide el presidente por razones de urgencia, con la mayoría de los miembros presentes", "Sí, si están reunidos el secretario y todos los miembros y así lo deciden todos"]'::jsonb,3,'Art. 17.2 Ley 40/2015','Cuando estén reunidos el secretario y todos los miembros, pueden constituirse sin convocatoria previa si así lo deciden todos.',null),
('adm-cm:10-64697238e7','adm-cm',10,'¿Puede deliberarse en un órgano colegiado sobre un asunto que no figure en el orden del día?','["Sí, si lo solicita al menos un tercio de los miembros presentes en la sesión", "Sí, si lo propone el presidente al inicio de la sesión", "Solo si asisten todos los miembros y se declara la urgencia por mayoría", "No, en ningún caso"]'::jsonb,2,'Art. 17.4 Ley 40/2015','No puede tratarse ningún asunto fuera del orden del día salvo que asistan todos los miembros y se declare la urgencia por el voto favorable de la mayoría.',null),
('adm-cm:10-b3e3e6c078','adm-cm',10,'Según la Ley 40/2015, ¿cómo se adoptan los acuerdos de los órganos colegiados?','["Por unanimidad de los presentes", "Por mayoría de dos tercios de los presentes", "Por mayoría absoluta de los miembros", "Por mayoría de votos"]'::jsonb,3,'Art. 17.5 Ley 40/2015','El art. 17.5 dispone que los acuerdos serán adoptados por mayoría de votos.',null),
('adm-cm:10-a7046cff84','adm-cm',10,'Cuando un órgano colegiado se reúne a distancia, ¿dónde se entienden adoptados los acuerdos?','["En la capital de la comunidad autónoma", "Donde se encuentre físicamente la mayoría de los miembros que votaron a favor del acuerdo", "Donde se encuentre el secretario que levanta el acta", "En el lugar donde tenga la sede el órgano y, en su defecto, donde esté la presidencia"]'::jsonb,3,'Art. 17.5 Ley 40/2015','Se entienden adoptados donde tenga la sede el órgano colegiado y, en su defecto, donde esté ubicada la presidencia.',null),
('adm-cm:10-b7334d5e6e','adm-cm',10,'¿Qué efecto tiene que un miembro de un órgano colegiado vote en contra o se abstenga?','["Debe formular voto particular en el plazo de diez días", "Su voto no se computa a efectos de quórum", "Queda exento de la responsabilidad que pueda derivarse de los acuerdos", "Pierde el derecho a pedir certificación del acuerdo"]'::jsonb,2,'Art. 17.6 Ley 40/2015','Quienes voten en contra o se abstengan quedan exentos de la responsabilidad que pueda derivarse de los acuerdos.',null),
('adm-cm:10-d8b7600f26','adm-cm',10,'¿Cuándo puede aprobarse el acta de una sesión de un órgano colegiado según la Ley 40/2015?','["En el plazo de un mes desde la sesión", "Solo en la sesión inmediata siguiente", "Cuando la firmen todos los asistentes, sin plazo", "En la misma reunión o en la inmediata siguiente"]'::jsonb,3,'Art. 18.2 Ley 40/2015','El acta puede aprobarse en la misma reunión o en la inmediata siguiente.',null),
('adm-cm:10-d3b2d131b9','adm-cm',10,'En los órganos colegiados de la Administración General del Estado, ¿quién dirime con su voto los empates?','["El miembro de mayor antigüedad", "El vicepresidente", "El presidente", "El secretario"]'::jsonb,2,'Art. 19.2 Ley 40/2015','Corresponde al presidente dirimir con su voto los empates, salvo en los órganos del art. 15.2, donde depende de sus normas.',null),
('adm-cm:10-495bbcb2ff','adm-cm',10,'¿Con qué antelación mínima deben recibir la convocatoria los miembros de un órgano colegiado de la AGE?','["Tres días hábiles", "Cinco días", "Dos días", "Veinticuatro horas"]'::jsonb,2,'Art. 19.3 Ley 40/2015','Los miembros deben recibir la convocatoria con una antelación mínima de dos días.',null),
('adm-cm:10-320b7d05be','adm-cm',10,'¿Pueden abstenerse en las votaciones los miembros natos de un órgano colegiado que son autoridades o personal público?','["Sí, si lo autoriza el presidente", "Solo en las votaciones sobre asuntos urgentes", "Sí, siempre que lo motiven en el acta", "No, quienes lo son por razón del cargo no pueden abstenerse"]'::jsonb,3,'Art. 19.3 Ley 40/2015','No podrán abstenerse quienes, por su cualidad de autoridades o personal al servicio de las Administraciones, sean miembros natos en virtud del cargo.',null),
('adm-cm:10-08120f52f7','adm-cm',10,'¿En qué plazo pueden formular voto particular por escrito los miembros que discrepen del acuerdo mayoritario?','["Dos días", "Un mes", "Diez días", "Cinco días"]'::jsonb,0,'Art. 19.5 Ley 40/2015','Pueden formular voto particular por escrito en el plazo de dos días, que se incorporará al texto aprobado.',null),
('adm-cm:10-19704855d2','adm-cm',10,'Según la Ley 40/2015, ¿cuántas personas, como mínimo, integran un órgano colegiado de la AGE?','["Cinco", "Siete", "Dos", "Tres"]'::jsonb,3,'Art. 20.1 Ley 40/2015','Son órganos colegiados los que se creen formalmente y estén integrados por tres o más personas.',null),
('adm-cm:10-5b971f8050','adm-cm',10,'¿Qué es un órgano colegiado interministerial según la Ley 40/2015?','["El que tiene miembros procedentes de diferentes ministerios", "El que integra representantes del Estado y de las comunidades autónomas", "El que preside un ministro y asesora a varios departamentos", "El que depende directamente del Consejo de Ministros"]'::jsonb,0,'Art. 21.1 Ley 40/2015','Son interministeriales si sus miembros proceden de diferentes ministerios y ministeriales si proceden de uno solo.',null),
('adm-cm:10-0591b380d6','adm-cm',10,'¿Cuál de estos es un motivo de abstención según la Ley 40/2015?','["Pertenecer al mismo partido político que un interesado", "Haber coincidido con un interesado en el mismo centro de estudios", "Tener parentesco de consanguinidad dentro del cuarto grado con un interesado", "Tener parentesco de afinidad dentro del cuarto grado con cualquiera de los interesados"]'::jsonb,2,'Art. 23.2 Ley 40/2015','Es motivo el parentesco de consanguinidad dentro del cuarto grado o de afinidad dentro del segundo con cualquiera de los interesados.',null),
('adm-cm:10-688a5aadf0','adm-cm',10,'Según la Ley 40/2015, ¿durante cuánto tiempo haber prestado servicios profesionales a un interesado es motivo de abstención?','["En los cinco últimos años", "En los cuatro últimos años", "En el último año", "En los dos últimos años"]'::jsonb,3,'Art. 23.2 Ley 40/2015','Es motivo de abstención haber prestado en los dos últimos años servicios profesionales de cualquier tipo a la persona interesada.',null),
('adm-cm:10-e50c4d91e1','adm-cm',10,'¿Qué efecto tiene sobre los actos la intervención de quien debió abstenerse?','["Son anulables en todo caso", "Son nulos de pleno derecho en todo caso", "No implica necesariamente y en todo caso su invalidez", "Son inexistentes"]'::jsonb,2,'Art. 23.4 Ley 40/2015','La actuación de quien incurre en motivo de abstención no implica, necesariamente y en todo caso, la invalidez de los actos.',null),
('adm-cm:10-9208194a02','adm-cm',10,'Si el recusado niega la causa de recusación, ¿en qué plazo resuelve el superior?','["Tres días", "Un día", "Diez días", "Cinco días"]'::jsonb,0,'Art. 24.4 Ley 40/2015','El superior resolverá en el plazo de tres días, previos los informes y comprobaciones que considere oportunos.',null),
('adm-cm:10-292a968964','adm-cm',10,'¿Cabe recurso contra la resolución que decide sobre una recusación?','["Sí, recurso potestativo de reposición", "Sí, recurso de alzada ante el superior jerárquico del órgano que resolvió la recusación", "No, aunque puede alegarse al recurrir el acto que ponga fin al procedimiento", "Solo recurso contencioso-administrativo directo"]'::jsonb,2,'Art. 24.5 Ley 40/2015','No cabe recurso, sin perjuicio de alegar la recusación al recurrir el acto que ponga fin al procedimiento.',null),
('adm-cm:11-490f7a6c1b','adm-cm',11,'¿Cuál es el plazo máximo para resolver que puede fijar una norma reguladora de un procedimiento?','["3 meses, salvo que una norma con rango de ley establezca uno mayor", "6 meses, salvo que una norma con rango de ley establezca uno mayor o lo prevea el Derecho de la UE", "1 año, salvo que una norma con rango de ley o el Derecho de la Unión Europea establezcan uno menor", "6 meses, sin excepción, cualquiera que sea el rango de la norma reguladora"]'::jsonb,1,'Art. 21.2 Ley 39/2015','El plazo no puede exceder de seis meses, salvo que una norma con rango de ley establezca uno mayor o lo prevea el Derecho de la UE.',null),
('adm-cm:11-42a696cc2f','adm-cm',11,'Si la norma reguladora de un procedimiento no fija plazo máximo para resolver, este será de:','["1 mes", "6 meses", "3 meses", "10 días"]'::jsonb,2,'Art. 21.3 Ley 39/2015','Cuando las normas no fijen el plazo máximo, será de tres meses.',null),
('adm-cm:11-11e34514df','adm-cm',11,'En los procedimientos iniciados a solicitud del interesado, el silencio administrativo es, como regla general:','["Desestimatorio, salvo las excepciones legales", "Causa de caducidad del procedimiento", "Desestimatorio, sin excepción", "Estimatorio, salvo las excepciones legales"]'::jsonb,3,'Art. 24.1 Ley 39/2015','El vencimiento del plazo sin resolución expresa legitima al interesado para entender estimada su solicitud, salvo las excepciones previstas.',null),
('adm-cm:11-e6d15ea44b','adm-cm',11,'En los procedimientos iniciados de oficio en los que la Administración ejerce potestades sancionadoras o de intervención, el vencimiento del plazo sin resolución produce:','["La caducidad", "La estimación por silencio", "La desestimación por silencio", "La prórroga automática del plazo"]'::jsonb,0,'Art. 25.1 b) Ley 39/2015','En esos procedimientos se produce la caducidad.',null),
('adm-cm:11-9cb032bbc9','adm-cm',11,'Cuando los plazos se señalan por días, se entiende que son:','["Naturales, salvo que una ley disponga otro cómputo", "Hábiles, excluyéndose los sábados, los domingos y los festivos", "Hábiles, excluyéndose solo los domingos y los declarados festivos", "Naturales, salvo en el mes de agosto, en que son hábiles"]'::jsonb,1,'Art. 30.2 Ley 39/2015','Los plazos por días son hábiles y se excluyen sábados, domingos y festivos.',null),
('adm-cm:11-8607f1a7e2','adm-cm',11,'Los plazos señalados por horas no pueden tener una duración superior a:','["12 horas", "48 horas", "24 horas", "72 horas"]'::jsonb,2,'Art. 30.1 Ley 39/2015','Son hábiles todas las horas de un día hábil y no pueden superar 24 horas; si no, se expresan en días.',null),
('adm-cm:11-4e2b6783c7','adm-cm',11,'Los plazos fijados en meses o años se computan:','["Por días hábiles, a partir del día siguiente a la notificación o publicación", "Por días naturales, desde el mismo día de la notificación o publicación", "Desde el mismo día de la notificación o publicación del acto", "A partir del día siguiente a la notificación o publicación del acto"]'::jsonb,3,'Art. 30.4 Ley 39/2015','Se computan a partir del día siguiente a la notificación o publicación, de fecha a fecha.',null),
('adm-cm:11-1e76ccc8dc','adm-cm',11,'La ampliación de los plazos establecidos no puede exceder de:','["La mitad de los mismos", "El doble de los mismos", "Un mes en todo caso", "Tres meses"]'::jsonb,0,'Art. 32.1 Ley 39/2015','La ampliación no puede exceder de la mitad del plazo.',null),
('adm-cm:11-33a60e74ab','adm-cm',11,'Cuando en una solicitud figuren varios interesados, las actuaciones se efectuarán:','["Con el que elija la Administración en cada trámite, notificando a los demás", "Con todos a la vez, de forma obligatoria y en igualdad de condiciones, salvo renuncia expresa de alguno de ellos por escrito", "Con el de mayor edad, salvo que todos hayan señalado expresamente a otro, y en su defecto con todos los interesados a la vez", "Con el representante o interesado que expresamente hayan señalado y, en su defecto, con el que figure en primer término"]'::jsonb,3,'Art. 7 Ley 39/2015','En defecto de designación, con el que figure en primer término.',null),
('adm-cm:11-7854bae8a0','adm-cm',11,'La estimación por silencio administrativo tiene a todos los efectos la consideración de:','["Acto administrativo finalizador del procedimiento", "Acto de trámite cualificado, recurrible en alzada", "Propuesta de resolución vinculante para el órgano competente", "Mera ficción sin efectos hasta que se dicte resolución expresa"]'::jsonb,0,'Art. 24.2 Ley 39/2015','La desestimación por silencio solo permite interponer el recurso que proceda.',null),
('adm-cm:11-55f8e5127a','adm-cm',11,'Los titulares de las unidades administrativas que tengan a su cargo la resolución o despacho de los asuntos:','["Serán responsables directos de su tramitación y adoptarán las medidas para remover los obstáculos que retrasen el ejercicio de los derechos de los interesados", "No tienen responsabilidad directa sobre la tramitación, que corresponde en exclusiva al titular del órgano superior jerárquico del que dependan", "Responden solo ante los tribunales penales", "Solo son responsables si lo solicita el interesado"]'::jsonb,0,'Art. 20.1 Ley 39/2015','Son responsables directos de la tramitación.',null),
('adm-cm:11-17008a6366','adm-cm',11,'La Administración instructora deberá traducir al castellano:','["Los documentos que deban surtir efecto fuera del territorio de la Comunidad y los dirigidos a interesados que lo soliciten expresamente", "Todos los documentos redactados en lengua cooficial, sin excepción", "Solo los documentos dirigidos a interesados que residan fuera de la Comunidad Autónoma", "Los documentos que deban surtir efecto en la Comunidad, y los dirigidos a interesados que no conozcan la lengua cooficial aunque no lo pidan"]'::jsonb,0,'Art. 15.3 Ley 39/2015','Se traducen los que deban surtir efecto fuera de la Comunidad y los que pidan los interesados.',null),
('adm-cm:11-70d7fa5e55','adm-cm',11,'Tienen la consideración de Administraciones Públicas según el art. 2.3:','["La AGE, las Administraciones de las CCAA, las Entidades de la Administración Local y los organismos públicos y entidades de derecho público del art. 2.2 a)", "La AGE, las Administraciones de las CCAA y las Entidades Locales, pero no los organismos públicos vinculados o dependientes", "La AGE, las Administraciones de las CCAA, las Entidades de la Administración Local, las universidades privadas, los colegios profesionales y todas las empresas con capital público", "Los colegios profesionales en todo caso"]'::jsonb,0,'Art. 2.3 Ley 39/2015','Son AAPP la AGE, las CCAA, las Entidades Locales y los organismos y entidades de derecho público vinculados o dependientes.',null),
('adm-cm:11-6d26686900','adm-cm',11,'Según su art. 1.1, la Ley 39/2015 regula, entre otros aspectos:','["El régimen jurídico de los funcionarios y del personal laboral al servicio de las Administraciones", "La jurisdicción contencioso-administrativa y sus procedimientos, así como el régimen de los recursos judiciales contra los actos de las Administraciones", "Los requisitos de validez y eficacia de los actos administrativos y el procedimiento administrativo común a todas las Administraciones", "La organización interna de la AGE y de su sector público institucional, y el régimen de los órganos colegiados de todas las Administraciones"]'::jsonb,2,'Art. 1.1 Ley 39/2015','Incluye el procedimiento sancionador, el de responsabilidad patrimonial y los principios de iniciativa legislativa y potestad reglamentaria.',null),
('adm-cm:11-efa4130595','adm-cm',11,'La comparecencia de las personas ante las oficinas públicas solo será obligatoria cuando:','["El interesado tenga más de 65 años", "Lo establezca una circular o instrucción interna del órgano", "Lo decida motivadamente el instructor del procedimiento", "Así esté previsto en una norma con rango de ley"]'::jsonb,3,'Art. 19.1 Ley 39/2015','Solo es obligatoria si una norma con rango de ley lo prevé.',null),
('adm-cm:11-7444af7916','adm-cm',11,'¿Quién determina los órganos que tienen atribuidas las competencias de expedición de copias auténticas?','["Cada Administración Pública", "El Consejo de Estado", "El Ministerio de Justicia para todas", "Los notarios"]'::jsonb,0,'Art. 27.1 Ley 39/2015','Cada Administración determina los órganos competentes para expedir copias auténticas.',null),
('adm-cm:11-9527d5d0fb','adm-cm',11,'El registro electrónico de cada Administración permitirá la presentación de documentos:','["Solo en horario de oficina de cada órgano", "Solo de lunes a viernes, a cualquier hora", "Solo en días hábiles, durante las veinticuatro horas", "Todos los días del año durante las veinticuatro horas"]'::jsonb,3,'Art. 31.2 Ley 39/2015','El registro electrónico funciona 24 horas los 365 días.',null),
('adm-cm:11-ccf7e778fa','adm-cm',11,'El silencio será desestimatorio, entre otros, en los procedimientos relativos a:','["Licencias de obra menor", "Inscripción en registros públicos", "Las solicitudes de subvenciones de concurrencia competitiva, sin excepción", "El ejercicio del derecho de petición del art. 29 de la Constitución"]'::jsonb,3,'Art. 24.1 Ley 39/2015','También en los de dominio o servicio público, medio ambiente, responsabilidad patrimonial, impugnación de actos y revisión de oficio a solicitud.',null),
('adm-cm:11-d49bf8ed88','adm-cm',11,'La representación podrá acreditarse mediante:','["Únicamente escritura notarial de apoderamiento, que deberá presentarse en papel en el registro del órgano competente en cada uno de los procedimientos en que se actúe", "Únicamente comparecencia personal ante el órgano competente", "Cualquier medio válido en Derecho que deje constancia fidedigna, comparecencia personal o electrónica, o inscripción en el registro de apoderamientos", "Cualquier medio, incluida una llamada telefónica o un correo electrónico sin firma, siempre que el funcionario que lo recibe deje constancia escrita en el expediente"]'::jsonb,2,'Art. 5.4 Ley 39/2015','Se admite cualquier medio válido en Derecho que deje constancia fidedigna.',null),
('adm-cm:11-e07e5598c0','adm-cm',11,'Los interesados podrán firmar a través de cualquier medio que permita acreditar:','["La fecha del documento y su número de registro", "Su identidad, pero no la integridad del documento", "La autenticidad de la expresión de su voluntad y consentimiento, pero no la integridad del documento", "La autenticidad de la expresión de su voluntad y consentimiento, y la integridad e inalterabilidad del documento"]'::jsonb,3,'Art. 10.1 Ley 39/2015','La firma debe acreditar autenticidad de la voluntad y la integridad del documento.',null),
('adm-cm:11-c56cb25171','adm-cm',11,'Si el interesado actúa por medio de representante:','["Se requiere poder notarial en todo caso", "Las actuaciones se entienden siempre con el interesado, y solo se comunican al representante a título informativo", "Solo puede actuar como representante un abogado colegiado", "Las actuaciones se entenderán con el representante, salvo manifestación expresa en contrario del interesado"]'::jsonb,3,'Art. 5.1 Ley 39/2015','Se entienden con el representante salvo manifestación expresa en contrario.',null),
('adm-cm:11-e1f6832fe5','adm-cm',11,'En los procedimientos iniciados de oficio, si el procedimiento se paraliza por causa imputable al interesado:','["Se produce la caducidad inmediata del procedimiento", "Se interrumpirá el cómputo del plazo para resolver y notificar la resolución", "Se suspenderá el cómputo del plazo, pero solo si así lo acuerda el órgano por resolución motivada notificada al interesado", "Se archiva sin más trámite y se declara la caducidad del procedimiento de forma automática"]'::jsonb,1,'Art. 25.2 Ley 39/2015','La paralización imputable al interesado interrumpe el cómputo del plazo.',null),
('adm-cm:11-258ff4963a','adm-cm',11,'Cuando el último día del plazo sea inhábil:','["Se entenderá vencido el último día hábil anterior", "Se entenderá prorrogado al primer día hábil siguiente", "Se entenderá prorrogado al tercer día hábil siguiente", "El plazo vence ese mismo día"]'::jsonb,1,'Art. 30.5 Ley 39/2015','Se prorroga al primer día hábil siguiente.',null),
('adm-cm:11-814359477b','adm-cm',11,'Cuando la condición de interesado deriva de una relación jurídica transmisible, el derecho-habiente:','["No sucede, debiendo iniciar un nuevo procedimiento en el plazo de diez días", "Solo sucede si todavía no se ha abierto la fase de instrucción", "Sucederá en tal condición cualquiera que sea el estado del procedimiento", "Sucederá en tal condición solo si el procedimiento no ha concluido la fase de audiencia a los interesados"]'::jsonb,2,'Art. 4.3 Ley 39/2015','Sucede en la condición de interesado en cualquier estado del procedimiento.',null),
('adm-cm:11-1dffb9d51e','adm-cm',11,'Las asociaciones y organizaciones representativas de intereses económicos y sociales son titulares de:','["Intereses individuales de cada uno de sus asociados", "Intereses legítimos colectivos en los términos que la ley reconozca", "Derechos fundamentales propios en todo procedimiento administrativo que afecte a sus asociados o al sector", "Ningún interés"]'::jsonb,1,'Art. 4.2 Ley 39/2015','Son titulares de intereses legítimos colectivos.',null),
('adm-cm:11-524eed8239','adm-cm',11,'Los documentos presentados de manera presencial ante las Administraciones deberán ser:','["Archivados en papel sin digitalizar en la oficina que los recibió", "Digitalizados por la oficina de registro, conservándose los originales en el expediente", "Enviados por correo postal al órgano competente para su digitalización en destino, junto con el resto del expediente", "Digitalizados por la oficina de asistencia en materia de registros, devolviéndose los originales al interesado"]'::jsonb,3,'Art. 16.5 Ley 39/2015','Se digitalizan y se devuelven los originales, salvo que la norma determine la custodia obligatoria.','abr. 2026 · 1.er ejercicio'),
('adm-cm:11-d97142a0cc','adm-cm',11,'La AGE, las CCAA y las Entidades Locales dispondrán de:','["Un registro electrónico general de apoderamientos", "Un registro de representantes en papel", "Un registro notarial propio", "Un registro único estatal compartido obligatoriamente"]'::jsonb,0,'Art. 6.1 Ley 39/2015','Cada una dispone de un registro electrónico general de apoderamientos.',null),
('adm-cm:11-a0f9ff7a55','adm-cm',11,'En los casos de estimación por silencio, la resolución expresa posterior:','["Podrá ser desestimatoria si así lo aconseja el interés público", "Deberá someterse a dictamen previo del Consejo de Estado", "Solo podrá dictarse de ser confirmatoria del mismo", "Podrá ser confirmatoria o desestimatoria, según el resultado de la instrucción y las alegaciones de los interesados"]'::jsonb,2,'Art. 24.3 a) Ley 39/2015','La resolución expresa posterior a la estimación por silencio solo puede confirmarla.',null),
('adm-cm:11-8a48889ffb','adm-cm',11,'Son interesados en el procedimiento, según el art. 4.1 a):','["Cualquier ciudadano, sin necesidad de acreditar interés alguno", "Quienes lo promuevan como titulares de derechos subjetivos, pero no de intereses legítimos colectivos", "Quienes tengan derechos que puedan resultar afectados por la decisión, aunque no se hayan personado", "Quienes lo promuevan como titulares de derechos o intereses legítimos individuales o colectivos"]'::jsonb,3,'Art. 4.1 a) Ley 39/2015','También los que tengan derechos que puedan resultar afectados y los titulares de intereses legítimos que se personen antes de la resolución definitiva.',null),
('adm-cm:11-ebeef3fd90','adm-cm',11,'Contra el acuerdo que resuelva sobre la ampliación del plazo máximo de resolución:','["Cabe recurso de reposición", "Cabe recurso extraordinario de revisión", "No cabrá recurso alguno", "Cabe recurso de alzada"]'::jsonb,2,'Art. 23.2 Ley 39/2015','Ese acuerdo no es recurrible.',null),
('adm-cm:11-39cf04c463','adm-cm',11,'La ampliación excepcional del plazo máximo de resolución no podrá ser superior:','["A la mitad del plazo establecido para la tramitación del procedimiento", "Al plazo establecido para la tramitación del procedimiento", "A diez días hábiles", "A un año, cualquiera que sea el plazo inicial"]'::jsonb,1,'Art. 23.1 Ley 39/2015','Contra el acuerdo de ampliación no cabe recurso.',null),
('adm-cm:11-28e6b5f950','adm-cm',11,'Si concurren varios interesados en un procedimiento de la AGE y existe discrepancia en cuanto a la lengua:','["Se tramitará en la lengua cooficial", "Lo decide el interesado que figure en primer lugar", "Se tramitará en ambas lenguas", "El procedimiento se tramitará en castellano"]'::jsonb,3,'Art. 15.1 Ley 39/2015','En caso de discrepancia, se tramita en castellano.',null),
('adm-cm:11-3dbceb1190','adm-cm',11,'La ampliación de un plazo y su solicitud deberán producirse:','["Solo el último día del plazo de que se trate", "En todo caso antes del vencimiento del plazo de que se trate", "Hasta diez días después del vencimiento del plazo, si se justifica la causa", "En cualquier momento"]'::jsonb,1,'Art. 32.3 Ley 39/2015','En ningún caso podrá ampliarse un plazo ya vencido.',null),
('adm-cm:11-e789ebf885','adm-cm',11,'Cuando razones de interés público lo aconsejen, podrá acordarse la tramitación de urgencia, que supone:','["Reducir todos los plazos a cinco días, incluidos los de recursos", "Suprimir los recursos administrativos", "Reducir a la mitad todos los plazos del procedimiento, incluidos los de presentación de solicitudes y recursos", "Reducir a la mitad los plazos del procedimiento ordinario, salvo los relativos a la presentación de solicitudes y recursos"]'::jsonb,3,'Art. 33.1 Ley 39/2015','Se reducen los plazos a la mitad, salvo los de solicitudes y recursos.',null),
('adm-cm:11-e6fb454cf4','adm-cm',11,'Solicitado el certificado acreditativo del silencio, este deberá emitirse en el plazo máximo de:','["Tres meses", "Diez días", "Un mes", "Quince días"]'::jsonb,3,'Art. 24.4 Ley 39/2015','El certificado del silencio se emite en un máximo de quince días.',null),
('adm-cm:11-a23c8604f1','adm-cm',11,'Si un plazo fijado en meses vence en un mes en el que no hay día equivalente al de la notificación:','["El plazo expira el último día del mes", "El plazo se amplía 10 días", "El plazo expira el primer día del mes siguiente", "El plazo se considera vencido el día 28"]'::jsonb,0,'Art. 30.4 Ley 39/2015','Si no hay día equivalente, el plazo expira el último día del mes.',null),
('adm-cm:11-eedec97538','adm-cm',11,'Si durante la instrucción de un procedimiento no publicado se advierte la existencia de personas titulares de derechos o intereses legítimos que puedan resultar afectados:','["Se comunicará a dichas personas la tramitación del procedimiento", "No se les comunica nada hasta la resolución, que se les notifica", "Se suspenderá el procedimiento hasta que soliciten personarse", "Se archivará el procedimiento"]'::jsonb,0,'Art. 8 Ley 39/2015','Se les comunica la tramitación.',null),
('adm-cm:11-1a4ce89ef3','adm-cm',11,'La Administración está obligada a dictar resolución expresa y a notificarla:','["Solo en los procedimientos sancionadores", "En todos los procedimientos, cualquiera que sea su forma de iniciación", "Solo en los procedimientos iniciados a solicitud del interesado", "En todos los procedimientos, salvo en los iniciados de oficio, en que basta la caducidad"]'::jsonb,1,'Art. 21.1 Ley 39/2015','La obligación de resolver alcanza a todos los procedimientos, salvo las excepciones legales.',null),
('adm-cm:11-6a8a48a637','adm-cm',11,'Si un día es hábil en el municipio del interesado e inhábil en la sede del órgano administrativo, o a la inversa:','["Se aplica el calendario del órgano", "Se aplica el calendario del interesado", "Se considerará inhábil en todo caso", "Se considerará hábil en todo caso"]'::jsonb,2,'Art. 30.6 Ley 39/2015','En caso de discrepancia, se considera inhábil.',null),
('adm-cm:11-d5e82f6028','adm-cm',11,'La falta o insuficiente acreditación de la representación no impedirá que se tenga por realizado el acto, siempre que se aporte o subsane en el plazo de:','["Cinco días improrrogables desde el requerimiento, sin que el órgano pueda establecer otro plazo", "Quince días hábiles", "Un mes desde el requerimiento", "Diez días, o el plazo superior que establezca el órgano cuando las circunstancias lo requieran"]'::jsonb,3,'Art. 5.6 Ley 39/2015','El plazo para subsanar es de diez días.',null),
('adm-cm:11-fdce79aff2','adm-cm',11,'Los interesados que conozcan datos que permitan identificar a otros interesados que no hayan comparecido en el procedimiento:','["Tienen prohibido comunicarlos por razones de protección de datos", "Pueden comunicarlos voluntariamente, sin estar obligados a ello", "Tienen el deber de proporcionárselos a la Administración actuante", "Solo deben comunicarlos ante un juez"]'::jsonb,2,'Art. 18.2 Ley 39/2015','Existe el deber de proporcionar esos datos a la Administración.',null),
('adm-cm:11-2fd8dcaeca','adm-cm',11,'Las Administraciones están obligadas a verificar la identidad de los interesados mediante la comprobación de:','["Su huella dactilar o cualquier otro dato biométrico que conste en el DNI o en el documento identificativo equivalente", "Su nombre y apellidos o denominación o razón social, que consten en el DNI o documento identificativo equivalente", "Su dirección de correo electrónico", "Su número de teléfono móvil"]'::jsonb,1,'Art. 9.1 Ley 39/2015','Se verifica con el nombre y apellidos o razón social del DNI o documento equivalente.',null),
('adm-cm:11-f6e1b9738e','adm-cm',11,'El incumplimiento de la obligación de dictar resolución expresa en plazo dará lugar a:','["La nulidad de pleno derecho del procedimiento", "Una sanción al interesado", "La estimación automática de la solicitud en todo caso, sin ninguna otra consecuencia para el órgano o para el personal responsable", "La exigencia de responsabilidad disciplinaria, sin perjuicio de la que hubiere lugar de acuerdo con la normativa aplicable"]'::jsonb,3,'Art. 21.6 Ley 39/2015','El personal y los titulares de órganos son responsables directos y responden disciplinariamente.',null),
('adm-cm:11-8b76d2a98d','adm-cm',11,'Deberá acreditarse la representación para:','["Formular solicitudes, presentar declaraciones responsables o comunicaciones, interponer recursos, desistir y renunciar a derechos", "Pedir información general sobre los procedimientos", "Consultar el estado del expediente", "Cualquier acto de mero trámite, incluida la consulta del expediente, la obtención de copias y la petición de información general"]'::jsonb,0,'Art. 5.3 Ley 39/2015','Para los actos de mero trámite la representación se presume.',null),
('adm-cm:11-b171e10abb','adm-cm',11,'Las copias auténticas de documentos realizadas por los órganos competentes:','["Solo tienen validez dentro del mismo procedimiento en el que se expidieron", "Caducan a los seis meses de su expedición", "Tienen menos valor probatorio que el original, salvo que se compulsen ante notario", "Tendrán la misma validez y eficacia que los documentos originales"]'::jsonb,3,'Art. 27.2 Ley 39/2015','Las copias auténticas tienen la misma validez y eficacia que los originales.',null),
('adm-cm:11-e58deef229','adm-cm',11,'¿Cuál de los siguientes es un sistema de identificación electrónica previsto en el art. 9.2?','["Un mensaje desde un número de teléfono previamente comunicado", "El envío de una fotocopia escaneada del DNI por correo electrónico, junto con la solicitud firmada a mano", "Los sistemas basados en certificados electrónicos cualificados de firma electrónica", "Una llamada telefónica grabada"]'::jsonb,2,'Art. 9.2 Ley 39/2015','También los certificados cualificados de sello electrónico y otros sistemas que las AAPP consideren válidos.','oct. 2026 · 1.er ejercicio'),
('adm-cm:11-13127ddd7f','adm-cm',11,'¿Cuál de las siguientes es una tipología de apoderamiento inscribible en el registro electrónico de apoderamientos?','["Un poder otorgado verbalmente ante el funcionario", "Un poder general para que el apoderado actúe en nombre del poderdante en cualquier actuación ante cualquier Administración", "Un poder especial para actuar ante los juzgados y tribunales penales en nombre del poderdante, en cualquier procedimiento", "Un poder sin identificar al apoderado"]'::jsonb,1,'Art. 6 Ley 39/2015','Las tipologías son: poder general, poder ante una Administración u Organismo concreto y poder para trámites específicos.',null),
('adm-cm:11-389efbcc77','adm-cm',11,'Se entiende por documentos públicos administrativos:','["Los documentos privados presentados en un registro público", "Los documentos autorizados por notario, exclusivamente", "Los válidamente emitidos por los órganos de las Administraciones Públicas", "Cualquier documento firmado electrónicamente por un ciudadano y presentado en la sede electrónica de una Administración"]'::jsonb,2,'Art. 26.1 Ley 39/2015','Se emiten por escrito a través de medios electrónicos, salvo que su naturaleza exija otra forma.',null),
('adm-cm:11-cf0fc0b91a','adm-cm',11,'La ampliación de plazos por el tiempo máximo permitido se aplicará en todo caso a los procedimientos tramitados por:','["Las Comunidades Autónomas cuando afecten a varias provincias", "Los órganos colegiados de cualquier Administración, y los que exijan algún trámite en otra Comunidad Autónoma", "Las misiones diplomáticas y oficinas consulares, y los que exijan algún trámite en el extranjero", "Los Ayuntamientos de municipios de gran población, y los que exijan algún trámite en otra Comunidad Autónoma"]'::jsonb,2,'Art. 32.2 Ley 39/2015','Se aplica a misiones diplomáticas, oficinas consulares y trámites en el extranjero o con interesados residentes fuera de España.',null),
('adm-cm:11-0cd125f15b','adm-cm',11,'Las Administraciones no exigirán a los interesados la presentación de documentos originales:','["Salvo en los procedimientos iniciados de oficio", "Salvo que, con carácter excepcional, la normativa reguladora aplicable establezca lo contrario", "En ningún caso, sin excepciones", "Salvo que el funcionario que tramite el procedimiento lo considere oportuno para comprobar su autenticidad"]'::jsonb,1,'Art. 28.3 Ley 39/2015','La regla es no exigir originales; solo excepcionalmente por normativa.',null),
('adm-cm:11-418e0c6d34','adm-cm',11,'Cuando se soliciten informes preceptivos a un órgano, el plazo máximo para resolver puede suspenderse por el tiempo que medie entre la petición y la recepción del informe, sin que pueda exceder de:','["Tres meses", "Seis meses", "Un mes", "Diez días"]'::jsonb,0,'Art. 22.1 d) Ley 39/2015','Esta suspensión no puede exceder en ningún caso de tres meses.',null),
('adm-cm:11-6740c00d43','adm-cm',11,'Los titulares de intereses legítimos que puedan resultar afectados por la resolución son interesados si:','["Se personan en el procedimiento en tanto no haya recaído resolución definitiva", "Lo solicitan antes del inicio del procedimiento", "Se personan en cualquier momento, incluso después de la resolución definitiva", "Lo autoriza el instructor"]'::jsonb,0,'Art. 4.1 c) Ley 39/2015','Deben personarse antes de la resolución definitiva.',null),
('adm-cm:11-6a151cbdeb','adm-cm',11,'En caso de desestimación por silencio, la resolución expresa posterior:','["No puede dictarse", "Se adoptará por la Administración sin vinculación alguna al sentido del silencio", "Debe ser necesariamente desestimatoria, en coherencia con el sentido del silencio producido", "Solo puede ser confirmatoria"]'::jsonb,1,'Art. 24.3 b) Ley 39/2015','En la estimación por silencio, en cambio, la resolución posterior solo puede ser confirmatoria.',null),
('adm-cm:11-aa11600fc4','adm-cm',11,'Tienen capacidad de obrar ante las Administraciones Públicas:','["Solo los españoles mayores de edad", "Las personas físicas o jurídicas que la ostenten con arreglo a las normas civiles", "Solo los mayores de 21 años y las personas jurídicas inscritas en un registro público", "Las personas físicas o jurídicas con certificado digital, aunque no tengan capacidad conforme a las normas civiles"]'::jsonb,1,'Art. 3 a) Ley 39/2015','Tienen capacidad las personas que la tengan según las normas civiles.',null),
('adm-cm:11-7718cb75da','adm-cm',11,'En los procedimientos iniciados de oficio de los que pudiera derivarse el reconocimiento de derechos o situaciones favorables, el vencimiento del plazo sin resolución permite a los interesados:','["Entender desestimadas sus pretensiones por silencio administrativo", "Entender estimadas sus pretensiones por silencio administrativo positivo", "Solicitar que se declare la caducidad del procedimiento", "Exigir una indemnización automática"]'::jsonb,0,'Art. 25.1 a) Ley 39/2015','En estos procedimientos el silencio es desestimatorio.',null),
('adm-cm:11-9e58acbb11','adm-cm',11,'Según el art. 3 c), los grupos de afectados y las entidades sin personalidad jurídica tienen capacidad de obrar:','["Siempre, cualquiera que sea su número de miembros", "Cuando tengan más de 20 miembros", "Cuando la ley así lo declare expresamente", "Cuando se inscriban en el registro correspondiente de la Administración ante la que actúen"]'::jsonb,2,'Art. 3 c) Ley 39/2015','Grupos de afectados, uniones y entidades sin personalidad y patrimonios independientes tienen capacidad cuando la ley lo declare expresamente.',null),
('adm-cm:11-7e48c4e301','adm-cm',11,'En el asiento de registro debe constar, entre otros datos:','["La firma del superior jerárquico del órgano destinatario y el sello de la oficina que lo recibe", "Un número, epígrafe expresivo de su naturaleza, fecha y hora de presentación, identificación del interesado y referencia al contenido", "Un número, fecha de presentación, identificación del interesado y del órgano destinatario, pero no la hora de presentación ni ninguna referencia a su contenido", "El sentido previsible de la resolución"]'::jsonb,1,'Art. 16.2 Ley 39/2015','Se emite recibo con copia autenticada del documento, fecha y hora de presentación y número de entrada.','oct. 2026 · 1.er ejercicio'),
('adm-cm:11-66059ae862','adm-cm',11,'Es un derecho de las personas en sus relaciones con las AAPP según el art. 13:','["Elegir al funcionario que tramite su expediente", "Obtener una resolución favorable si la Administración incumple el plazo máximo para resolver", "Ser tratados con respeto y deferencia por las autoridades y empleados públicos", "Ser atendidos en la lengua que elijan, cualquiera que sea la Administración"]'::jsonb,2,'Art. 13 e) Ley 39/2015','Otros: comunicarse por el Punto de Acceso General electrónico, ser asistidos en el uso de medios electrónicos, usar lenguas cooficiales, acceso a información pública…',null),
('adm-cm:11-4db426406c','adm-cm',11,'Los términos y plazos establecidos en las leyes obligan:','["Solo a la Administración, que debe resolver en el plazo máximo", "Solo a los interesados, que pierden su derecho si no los cumplen", "A las autoridades y personal al servicio de las Administraciones competentes para la tramitación, así como a los interesados", "A las autoridades y personal de la Administración, pero no a los interesados, que pueden cumplir los trámites en cualquier momento"]'::jsonb,2,'Art. 29 Ley 39/2015','Los plazos obligan tanto a la Administración como a los interesados.',null),
('adm-cm:11-7408b19aa2','adm-cm',11,'No se tendrán por presentados en el registro:','["Aquellos documentos e información cuyo régimen especial establezca otra forma de presentación", "Los presentados por un representante cuya representación no esté inscrita", "Los presentados en día inhábil, que se tendrán por no presentados hasta el siguiente hábil", "Los presentados en las oficinas de Correos sin sello de fechas"]'::jsonb,0,'Art. 16.8 Ley 39/2015','No se tienen por presentados los que tengan un régimen especial con otra forma de presentación.',null),
('adm-cm:11-4ed8d60358','adm-cm',11,'Los plazos expresados en días se contarán:','["Desde que el interesado tenga conocimiento efectivo del acto", "Desde el mismo día de la notificación o publicación del acto", "Desde el día en que se dictó el acto, aunque se notifique o publique con posterioridad a esa fecha", "A partir del día siguiente a aquel en que tenga lugar la notificación o publicación del acto"]'::jsonb,3,'Art. 30.3 Ley 39/2015','Se cuentan desde el día siguiente a la notificación o publicación.',null),
('adm-cm:11-6700b16249','adm-cm',11,'En los procedimientos tramitados por la AGE, la lengua será:','["Siempre la lengua cooficial del territorio donde tenga su sede el órgano", "El castellano, sin que los interesados puedan utilizar ninguna otra lengua, aunque se dirijan a órganos con sede en una Comunidad Autónoma con lengua cooficial", "El castellano, aunque los interesados que se dirijan a órganos con sede en una Comunidad con lengua cooficial podrán utilizar también esta", "La que elija el funcionario que tramite el procedimiento, castellano o lengua cooficial, sin que el interesado pueda solicitar que se utilice otra"]'::jsonb,2,'Art. 15.1 Ley 39/2015','La lengua de la AGE es el castellano, con posibilidad de usar la cooficial ante órganos con sede en esa Comunidad.',null),
('adm-cm:11-b8e65ba5c7','adm-cm',11,'Los poderes inscritos en el registro electrónico de apoderamientos tendrán una validez máxima de:','["Diez años a contar desde la fecha de inscripción", "Un año, renovable por periodos iguales", "Cinco años a contar desde la fecha de inscripción", "Indefinida, hasta su revocación"]'::jsonb,2,'Art. 6.6 Ley 39/2015','Validez máxima de cinco años; pueden revocarse o prorrogarse, la prórroga por un máximo de cinco años.',null),
('adm-cm:11-ee9122fbdc','adm-cm',11,'Contra el acuerdo que declare la tramitación de urgencia:','["No cabrá recurso alguno, sin perjuicio del procedente contra la resolución que ponga fin al procedimiento", "Cabe recurso contencioso-administrativo inmediato", "Cabe recurso de alzada", "Cabe recurso potestativo de reposición en el plazo de un mes desde su notificación, que no suspende la tramitación"]'::jsonb,0,'Art. 33.2 Ley 39/2015','El acuerdo de urgencia no es recurrible.',null),
('adm-cm:11-a0156a3a75','adm-cm',11,'Las Administraciones deben publicar y mantener actualizadas en el portal web:','["Las nóminas de todos sus empleados", "Las resoluciones judiciales que les afecten", "Las relaciones de procedimientos de su competencia, con indicación de los plazos máximos de duración y de los efectos del silencio administrativo", "Las relaciones de procedimientos de su competencia, con los datos de los interesados y el estado de tramitación de cada expediente"]'::jsonb,2,'Art. 21.4 Ley 39/2015','Deben publicar los procedimientos, sus plazos máximos y los efectos del silencio.',null),
('adm-cm:11-1df6567243','adm-cm',11,'Según el art. 1.2, solo podrán incluirse trámites adicionales o distintos de los de la Ley 39/2015:','["Mediante circular o instrucción interna", "Por decisión del órgano instructor", "Mediante reglamento, cuando resulte eficaz, proporcionado y necesario para la consecución de los fines del procedimiento", "Mediante ley, cuando resulte eficaz, proporcionado y necesario para la consecución de los fines del procedimiento"]'::jsonb,3,'Art. 1.2 Ley 39/2015','Solo mediante ley y de forma motivada.',null),
('adm-cm:11-b7bb9ce1b4','adm-cm',11,'Para los actos y gestiones de mero trámite, la representación:','["No está permitida", "Se presumirá", "Debe acreditarse ante notario", "Debe inscribirse en el registro de apoderamientos"]'::jsonb,1,'Art. 5.3 Ley 39/2015','En los actos de mero trámite se presume la representación.',null),
('adm-cm:11-6c1c36d0f9','adm-cm',11,'Según el artículo 13 de la Ley 39/2015, es un derecho de las personas en sus relaciones con las Administraciones Públicas:','["Obtener siempre una resolución favorable cuando cumplan los requisitos formales", "Exigir que se les atienda fuera del horario de atención al público", "Elegir al funcionario que tramitará su procedimiento", "Ser tratadas con respeto y deferencia por las autoridades y empleados públicos, que habrán de facilitarles el ejercicio de sus derechos"]'::jsonb,3,'Art. 13 e) Ley 39/2015','El artículo 13 recoge también, entre otros, el derecho a ser asistidas en el uso de medios electrónicos.',null),
('adm-cm:12-f71521d35b','adm-cm',12,'Los actos administrativos producen efectos:','["Desde su publicación en el boletín oficial, salvo que en ellos se disponga otra cosa", "Desde que son firmes en vía administrativa, salvo que se disponga otra cosa", "Desde la fecha en que se dicten, salvo que en ellos se disponga otra cosa", "Desde su notificación, sin que puedan disponer otra cosa"]'::jsonb,2,'Art. 39.1 Ley 39/2015','Se presumen válidos y producen efectos desde la fecha en que se dicten, salvo que en ellos se disponga otra cosa.','abr. 2026 · 1.er ejercicio'),
('adm-cm:12-7a2996aaae','adm-cm',12,'¿En qué plazo debe cursarse la notificación de un acto administrativo?','["5 días desde que el acto se dictó", "15 días hábiles desde que el acto se dictó o se firmó", "1 mes desde que el acto se dictó", "10 días desde que el acto se dictó"]'::jsonb,3,'Art. 40.2 Ley 39/2015','La notificación debe cursarse dentro de los diez días siguientes a la fecha en que el acto se dictó.',null),
('adm-cm:12-3d2f360b56','adm-cm',12,'Una notificación electrónica se entiende rechazada cuando pasan sin que se acceda a su contenido:','["10 días naturales desde su puesta a disposición", "10 días hábiles desde su puesta a disposición en la sede electrónica", "15 días naturales desde su puesta a disposición", "5 días hábiles desde su puesta a disposición"]'::jsonb,0,'Art. 43.2 Ley 39/2015','Se entiende rechazada cuando han pasado diez días naturales desde su puesta a disposición sin acceder a su contenido.','abr. 2026 · 1.er ejercicio'),
('adm-cm:12-90bd760ddd','adm-cm',12,'Cuando la notificación ha resultado infructuosa, se hace por medio de un anuncio en:','["El tablón de la sede del órgano", "El Boletín Oficial del Estado", "El boletín oficial de la provincia", "Un periódico de tirada nacional"]'::jsonb,1,'Art. 44 Ley 39/2015','La notificación se hace por medio de un anuncio publicado en el BOE.',null),
('adm-cm:12-bdc24d1629','adm-cm',12,'¿Cuál de estos actos es nulo de pleno derecho?','["El que tiene un defecto de forma que no causa indefensión al interesado ni impide que el acto alcance su fin", "El dictado fuera del plazo establecido, cuando el término no sea esencial", "El dictado por un órgano manifiestamente incompetente por razón de la materia o del territorio", "El que incurre en desviación de poder o en cualquier otra infracción del ordenamiento jurídico aplicable"]'::jsonb,2,'Art. 47.1 b) Ley 39/2015','La incompetencia manifiesta por razón de la materia o del territorio es causa de nulidad de pleno derecho. Las otras opciones son, como mucho, causas de anulabilidad.','abr. 2026 · 1.er ejercicio'),
('adm-cm:12-e4ec133b31','adm-cm',12,'Un acto dictado prescindiendo total y absolutamente del procedimiento legalmente establecido es:','["Anulable", "Válido si se convalida", "Una irregularidad no invalidante", "Nulo de pleno derecho"]'::jsonb,3,'Art. 47.1 e) Ley 39/2015','Es una de las causas de nulidad de pleno derecho.',null),
('adm-cm:12-ea51344225','adm-cm',12,'Los actos que incurren en desviación de poder son:','["Anulables", "Nulos de pleno derecho", "Válidos", "Inexistentes"]'::jsonb,0,'Art. 48.1 Ley 39/2015','Son anulables los actos que incurren en cualquier infracción del ordenamiento, incluso la desviación de poder.',null),
('adm-cm:12-2d97db4297','adm-cm',12,'El defecto de forma determina la anulabilidad del acto:','["Siempre, aunque el acto alcance su fin, reúna los requisitos formales indispensables y no cause indefensión", "Solo cuando el acto carece de los requisitos formales indispensables o da lugar a indefensión", "Nunca, porque el defecto de forma solo genera irregularidades no invalidantes", "Solo cuando el defecto de forma afecta a la motivación del acto, aunque no se haya producido indefensión"]'::jsonb,1,'Art. 48.2 Ley 39/2015','Solo cuando el acto carece de los requisitos formales indispensables para alcanzar su fin o da lugar a indefensión.',null),
('adm-cm:12-e3acded0fd','adm-cm',12,'La realización de actuaciones fuera del tiempo establecido implica la anulabilidad del acto:','["Siempre, cualquiera que sea la naturaleza del término o plazo", "Nunca, ya que la actuación tardía es una mera irregularidad no invalidante", "Solo cuando lo imponga la naturaleza del término o plazo", "Solo si el retraso supera el doble del plazo establecido para la actuación"]'::jsonb,2,'Art. 48.3 Ley 39/2015','Solo implica anulabilidad cuando así lo imponga la naturaleza del término o plazo.',null),
('adm-cm:12-9fd1b3a190','adm-cm',12,'¿Qué actos puede convalidar la Administración subsanando los vicios de que adolezcan?','["Los nulos de pleno derecho", "Los inexistentes", "Cualquier acto", "Los anulables"]'::jsonb,3,'Art. 52.1 Ley 39/2015','La Administración puede convalidar los actos anulables, subsanando los vicios de que adolezcan.',null),
('adm-cm:12-e80036fafa','adm-cm',12,'La revisión de oficio de los actos nulos de pleno derecho requiere:','["Dictamen favorable previo del Consejo de Estado u órgano consultivo equivalente de la Comunidad Autónoma", "Dictamen previo, preceptivo pero no vinculante, del Consejo de Estado u órgano consultivo equivalente autonómico", "Sentencia judicial previa que declare la nulidad, a instancia de la Administración", "Informe favorable del servicio jurídico y audiencia previa de todos los interesados"]'::jsonb,0,'Art. 106.1 Ley 39/2015','Requiere dictamen favorable previo del Consejo de Estado u órgano consultivo equivalente de la Comunidad Autónoma, si lo hubiere.',null),
('adm-cm:12-6b54000b62','adm-cm',12,'La declaración de lesividad de un acto favorable anulable no puede adoptarse una vez transcurridos desde que se dictó:','["2 años", "4 años", "6 meses", "1 año"]'::jsonb,1,'Art. 107.2 Ley 39/2015','No puede adoptarse una vez transcurridos cuatro años desde que se dictó el acto.',null),
('adm-cm:12-c4ed0c47fd','adm-cm',12,'¿Qué actos pueden revocar las Administraciones mientras no haya transcurrido el plazo de prescripción?','["Los actos favorables", "Los actos firmes de cualquier tipo", "Los actos de gravamen o desfavorables", "Las disposiciones generales"]'::jsonb,2,'Art. 109.1 Ley 39/2015','Pueden revocar sus actos de gravamen o desfavorables mientras no haya transcurrido el plazo de prescripción.',null),
('adm-cm:12-10a1776e5b','adm-cm',12,'Los errores materiales, de hecho o aritméticos de los actos pueden rectificarse:','["En el plazo de un mes desde la notificación, de oficio o a instancia de los interesados", "Solo a instancia de los interesados, mediante el correspondiente recurso de reposición", "Solo antes de la notificación del acto, de oficio por el mismo órgano que lo dictó", "En cualquier momento, de oficio o a instancia de los interesados"]'::jsonb,3,'Art. 109.2 Ley 39/2015','Pueden rectificarse en cualquier momento, de oficio o a instancia de los interesados.',null),
('adm-cm:12-1cdeb8b5bd','adm-cm',12,'¿Pueden revisarse de oficio las disposiciones administrativas nulas del art. 47.2?','["Sí, en cualquier momento y sin necesidad de dictamen del órgano consultivo", "No, la revisión de oficio solo alcanza a los actos, no a las disposiciones", "Sí, previo dictamen favorable del Consejo de Estado u órgano consultivo autonómico equivalente", "Sí, previo dictamen no vinculante del Consejo de Estado u órgano consultivo equivalente, y a instancia del interesado"]'::jsonb,2,'Art. 106.2 Ley 39/2015','Las Administraciones pueden declarar de oficio la nulidad de disposiciones del art. 47.2 previo dictamen favorable.',null),
('adm-cm:12-9c32a71019','adm-cm',12,'Son nulas de pleno derecho las disposiciones administrativas que:','["Establezcan la retroactividad de disposiciones sancionadoras no favorables o restrictivas de derechos individuales", "Establezcan la retroactividad de disposiciones favorables o ampliatorias de derechos individuales", "Tengan carácter organizativo y no se hayan sometido previamente al trámite de información pública ni a consulta de los interesados afectados", "Se aprueben por el Consejo de Ministros"]'::jsonb,0,'Art. 47.2 Ley 39/2015','También las que vulneren la Constitución, las leyes o disposiciones de rango superior o regulen materias reservadas a la ley.',null),
('adm-cm:12-0493008fd5','adm-cm',12,'En la AGE, son competentes para la revisión de oficio de sus propios actos y de los dictados por los Ministros:','["El Consejo de Estado", "Los Subsecretarios", "El Presidente del Gobierno en solitario", "El Consejo de Ministros"]'::jsonb,3,'Art. 111 a) Ley 39/2015','El Consejo de Ministros revisa sus propios actos y disposiciones y los de los Ministros.',null),
('adm-cm:12-e271f1f516','adm-cm',12,'Una notificación que contenga el texto íntegro del acto pero omita otro requisito surte efecto:','["A los seis meses de su práctica, si el interesado no ha reclamado", "Desde que el interesado realice actuaciones que supongan el conocimiento del contenido o interponga el recurso procedente", "Inmediatamente desde su envío, aunque el interesado no haya realizado ninguna actuación ni interpuesto recurso", "Nunca"]'::jsonb,1,'Art. 40.3 Ley 39/2015','Surte efecto desde que el interesado realiza actuaciones que suponen conocer su contenido e alcance o interpone recurso.',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('adm-cm:12-00cca45d97','adm-cm',12,'Los actos administrativos serán objeto de publicación cuando:','["Lo pida cualquier ciudadano interesado en conocerlos", "Lo establezcan las normas reguladoras de cada procedimiento o lo aconsejen razones de interés público", "Sean desfavorables para el interesado, aunque la norma reguladora no lo prevea", "Lo establezcan las normas reguladoras de cada procedimiento, pero nunca por razones de interés público apreciadas por el órgano"]'::jsonb,1,'Art. 45.1 Ley 39/2015','Se publican cuando lo establezcan sus normas reguladoras o lo aconsejen razones de interés público apreciadas por el órgano competente.',null),
('adm-cm:12-d125337989','adm-cm',12,'Si el procedimiento de revisión de oficio se inició de oficio y transcurren seis meses sin resolución, se produce:','["La estimación por silencio", "La caducidad del mismo", "La prórroga automática del plazo", "La nulidad automática del acto"]'::jsonb,1,'Art. 106.5 Ley 39/2015','Iniciado de oficio: caducidad. Iniciado a solicitud: se podrá entender desestimada.',null),
('adm-cm:12-99c9a4f598','adm-cm',12,'Las notificaciones se practicarán preferentemente:','["Mediante anuncio en el BOE, salvo que el interesado señale un domicilio", "En papel en el domicilio del interesado, salvo que este solicite la notificación electrónica", "Por medios electrónicos o en papel, a elección del órgano que dicte el acto", "Por medios electrónicos y, en todo caso, cuando el interesado esté obligado a recibirlas por esta vía"]'::jsonb,3,'Art. 41.1 Ley 39/2015','Se practicarán preferentemente por medios electrónicos.',null),
('adm-cm:12-095e248e1d','adm-cm',12,'Transcurrido el plazo de seis meses desde la iniciación del procedimiento de lesividad sin que se haya declarado, se produce:','["La declaración automática de lesividad", "La nulidad del acto", "La estimación del interesado por silencio", "La caducidad del procedimiento"]'::jsonb,3,'Art. 107.3 Ley 39/2015','Pasados seis meses sin declaración de lesividad, el procedimiento caduca.',null),
('adm-cm:12-860c3da083','adm-cm',12,'Iniciado un procedimiento de revisión de oficio o de lesividad, el órgano competente podrá suspender la ejecución del acto cuando:','["El acto sea favorable al interesado y este lo solicite antes de que se dicte la resolución", "Esta pudiera causar perjuicios de imposible o difícil reparación", "Lo solicite cualquier tercero, aunque no acredite la condición de interesado ni perjuicio alguno", "Hayan transcurrido seis meses desde que se dictó el acto"]'::jsonb,1,'Art. 108 Ley 39/2015','Puede suspenderse si la ejecución causaría perjuicios de imposible o difícil reparación.','oct. 2026 · 1.er ejercicio'),
('adm-cm:12-f174bdc1d0','adm-cm',12,'A efectos de entender cumplida la obligación de notificar dentro del plazo máximo, basta:','["Con firmar la resolución dentro del plazo máximo, aunque su notificación se intente después de vencido ese plazo legal", "Con remitir un aviso por SMS o correo electrónico", "La notificación que contenga el texto íntegro de la resolución y el intento de notificación debidamente acreditado", "Con publicar un anuncio en el tablón de edictos de la sede electrónica, aunque no se haya intentado la notificación personal"]'::jsonb,2,'Art. 40.4 Ley 39/2015','Es suficiente la notificación con el texto íntegro y el intento de notificación debidamente acreditado.',null),
('adm-cm:12-9eaf9fe87b','adm-cm',12,'Según el art. 35.1 i), deben motivarse también:','["Las comunicaciones internas entre órganos", "Los actos reglados, sin excepción, aunque no limiten derechos ni intereses", "Los actos que se dicten en el ejercicio de potestades discrecionales", "Los actos de trámite que no decidan el fondo ni produzcan indefensión"]'::jsonb,2,'Art. 35.1 i) Ley 39/2015','Se motivan los actos dictados en ejercicio de potestades discrecionales y los que deban serlo por disposición legal.',null),
('adm-cm:12-07ff20492a','adm-cm',12,'En las Entidades Locales, la declaración de lesividad corresponde a:','["El Pleno de la Corporación o, en su defecto, el órgano colegiado superior de la entidad", "La Junta de Gobierno Local en todo caso, previo dictamen del órgano consultivo autonómico", "El Alcalde, dando cuenta al Pleno", "El Alcalde o, en su defecto, el Secretario municipal, previo informe preceptivo del Interventor"]'::jsonb,0,'Art. 107.5 Ley 39/2015','La adopta el Pleno o, en su defecto, el órgano colegiado superior.',null),
('adm-cm:12-85410a573c','adm-cm',12,'El órgano que declare la nulidad o anule las actuaciones dispondrá siempre la conservación de:','["Aquellos actos y trámites cuyo contenido se hubiera mantenido igual de no haberse cometido la infracción", "Ningún acto del procedimiento", "Los actos de trámite anteriores a la infracción, aunque su contenido hubiera variado de no cometerse esta", "Solo la resolución final y los actos de trámite posteriores a la infracción, aunque su contenido hubiera variado"]'::jsonb,0,'Art. 51 Ley 39/2015','Es el principio de conservación de actos y trámites.',null),
('adm-cm:12-ea5a8a022f','adm-cm',12,'La publicación sustituye a la notificación, entre otros casos, cuando el acto:','["Se dicte en un procedimiento iniciado de oficio que afecte a varios interesados identificados", "Afecte a un único interesado identificado", "Tenga por destinatario a una pluralidad indeterminada de personas", "Sea una sanción leve impuesta a un interesado identificado y con domicilio conocido"]'::jsonb,2,'Art. 45.1 a) Ley 39/2015','También en los actos de procedimientos selectivos o de concurrencia competitiva.',null),
('adm-cm:12-a2ea5716c1','adm-cm',12,'Si nadie se hace cargo de la notificación en papel en el domicilio, se repetirá:','["Dos veces en la misma semana, en horas distintas", "No se repite, y se publica directamente en el BOE", "Una sola vez y en una hora distinta dentro de los tres días siguientes", "Una sola vez y en la misma hora dentro de los cinco días siguientes"]'::jsonb,2,'Art. 42.2 Ley 39/2015','Se repite por una sola vez y en hora distinta dentro de los tres días siguientes.',null),
('adm-cm:12-de6b14bcb2','adm-cm',12,'Deben ser motivados, con sucinta referencia de hechos y fundamentos de derecho:','["Solo las disposiciones de carácter general y los actos que pongan fin a la vía administrativa", "Los actos que limiten derechos subjetivos o intereses legítimos", "Solo los actos favorables al interesado", "Todos los actos de trámite, aunque no limiten derechos ni decidan el fondo"]'::jsonb,1,'Art. 35.1 a) Ley 39/2015','El art. 35.1 a) exige motivar los actos que limiten derechos subjetivos o intereses legítimos.',null),
('adm-cm:12-a6bad7a3b8','adm-cm',12,'Según el art. 38, los actos de las Administraciones sujetos al Derecho Administrativo son:','["Ejecutivos solo tras su confirmación judicial", "Ejecutivos con arreglo a lo dispuesto en la Ley", "Ejecutivos solo cuando sean firmes en vía administrativa y no se haya interpuesto recurso contencioso-administrativo", "Meramente declarativos hasta que se confirmen judicialmente"]'::jsonb,1,'Art. 38 Ley 39/2015','Los actos sujetos al Derecho Administrativo serán ejecutivos con arreglo a lo dispuesto en la Ley.',null),
('adm-cm:12-697ba457d2','adm-cm',12,'Al declarar la nulidad de una disposición o acto, las Administraciones podrán:','["Establecer en la misma resolución las indemnizaciones que proceda reconocer a los interesados", "Exigir a los interesados el reintegro de lo percibido sin necesidad de procedimiento ni audiencia previa", "Imponer sanciones a los interesados que se beneficiaron del acto nulo, sin necesidad de procedimiento", "Dejar sin efecto las sentencias dictadas sobre el acto"]'::jsonb,0,'Art. 106.4 Ley 39/2015','Pueden fijar indemnizaciones si concurren los requisitos de responsabilidad patrimonial.',null),
('adm-cm:12-ac11af11da','adm-cm',12,'Excepcionalmente, se podrá otorgar eficacia retroactiva a los actos cuando:','["Sean sanciones más favorables que las anteriores", "Se trate de actos de gravamen que restrinjan derechos individuales y así lo prevea expresamente una norma reglamentaria", "Lo solicite cualquier tercero afectado y el acto restrinja derechos individuales del destinatario", "Se dicten en sustitución de actos anulados o produzcan efectos favorables al interesado"]'::jsonb,3,'Art. 39.3 Ley 39/2015','Cabe retroactividad cuando se dicten en sustitución de actos anulados o produzcan efectos favorables, si los supuestos de hecho existían y no se lesionan derechos de terceros.',null),
('adm-cm:12-40622a6215','adm-cm',12,'La nulidad o anulabilidad de un acto:','["Implica siempre la nulidad de todo el procedimiento", "No implica la de los sucesivos en el procedimiento que sean independientes del primero", "Implica la de todos los actos posteriores del procedimiento, aunque sean independientes del primero", "Solo afecta a actos favorables"]'::jsonb,1,'Art. 49.1 Ley 39/2015','No se extiende a los actos sucesivos que sean independientes del primero.',null),
('adm-cm:12-b927c9e865','adm-cm',12,'Si el vicio de un acto consiste en incompetencia no determinante de nulidad, la convalidación podrá realizarse por:','["El interesado afectado, mediante escrito en el que manifieste su conformidad con el acto viciado", "El órgano competente, cuando sea superior jerárquico del que dictó el acto viciado", "El propio órgano que dictó el acto, mediante una resolución posterior que subsane el vicio de incompetencia", "El Defensor del Pueblo"]'::jsonb,1,'Art. 52.3 Ley 39/2015','La incompetencia no determinante de nulidad se convalida por el órgano competente superior jerárquico.',null),
('adm-cm:12-c140151527','adm-cm',12,'Las Administraciones podrán practicar notificaciones por medios no electrónicos cuando:','["Para asegurar la eficacia de la actuación sea necesario practicarla por entrega directa de un empleado público", "Sea fin de semana", "La notificación sea favorable al interesado", "El interesado esté obligado a relacionarse electrónicamente con la Administración y no haya accedido a la notificación"]'::jsonb,0,'Art. 41.2 b) Ley 39/2015','También cuando el interesado comparezca espontáneamente en una oficina de asistencia y solicite la comunicación personal.',null),
('adm-cm:12-7d7636dbf4','adm-cm',12,'Si el órgano aprecia que la publicación íntegra de un acto lesiona derechos o intereses legítimos:','["Se publicará íntegramente igualmente, sin perjuicio de la responsabilidad patrimonial que proceda por los daños causados a los interesados afectados", "No se publicará ni notificará el acto, y el órgano se limitará a comunicar a los interesados que existe una resolución que les afecta", "Se enviará al Defensor del Pueblo", "Se limitará a publicar una somera indicación del contenido y del lugar donde los interesados pueden comparecer para conocerlo"]'::jsonb,3,'Art. 46 Ley 39/2015','Se publica una somera indicación del contenido y del lugar donde comparecer en el plazo que se establezca.',null),
('adm-cm:12-860c10d63d','adm-cm',12,'Las notificaciones por medios electrónicos se entienden practicadas:','["Al día siguiente de su emisión", "Cuando el interesado contesta", "Cuando se envía al interesado el aviso de puesta a disposición por correo electrónico o SMS", "En el momento en que se produzca el acceso a su contenido"]'::jsonb,3,'Art. 43.2 Ley 39/2015','Se entienden practicadas en el momento del acceso a su contenido.',null),
('adm-cm:12-a15335bd6c','adm-cm',12,'La eficacia de un acto quedará demorada cuando:','["Se haya dictado en el mes de agosto o en un periodo vacacional, salvo que el interesado solicite su eficacia inmediata", "El interesado lo solicite verbalmente", "Así lo exija su contenido o esté supeditada a su notificación, publicación o aprobación superior", "Así lo decida el funcionario instructor, aunque su contenido no lo exija ni dependa de notificación o aprobación"]'::jsonb,2,'Art. 39.2 Ley 39/2015','La eficacia se demora cuando lo exija el contenido del acto o esté supeditada a notificación, publicación o aprobación superior.',null),
('adm-cm:12-97ccb434a4','adm-cm',12,'Como regla general, los actos administrativos se producirán:','["En papel con firma manuscrita del titular del órgano", "De la forma que elija el interesado en su solicitud, por escrito o verbalmente, en papel o electrónicamente", "Por escrito en papel, salvo que el interesado esté obligado a relacionarse electrónicamente", "Por escrito a través de medios electrónicos, salvo que su naturaleza exija otra forma"]'::jsonb,3,'Art. 36.1 Ley 39/2015','Se producen por escrito a través de medios electrónicos, a menos que su naturaleza exija otra forma más adecuada.',null),
('adm-cm:12-86a59aea34','adm-cm',12,'Las resoluciones administrativas de carácter particular no podrán vulnerar una disposición de carácter general:','["Aunque procedan de un órgano de igual o superior jerarquía al que dictó la disposición", "Salvo que lo autorice expresamente el Consejo de Ministros", "Salvo que procedan de un órgano de jerarquía superior al que dictó la disposición", "Salvo que sean favorables al interesado"]'::jsonb,0,'Art. 37.1 Ley 39/2015','Es el principio de inderogabilidad singular de los reglamentos.',null),
('adm-cm:12-fd6407ed08','adm-cm',12,'Según el art. 34.1 de la Ley 39/2015, los actos administrativos se producirán:','["Por el órgano competente, ajustándose a los requisitos y al procedimiento establecido", "Por el funcionario que tramite el expediente, con el visto bueno del titular del órgano", "Por cualquier órgano de la misma Administración", "Por el órgano competente, aunque no se ajusten al procedimiento establecido si el contenido es conforme a Derecho"]'::jsonb,0,'Art. 34.1 Ley 39/2015','Los actos se producen por el órgano competente ajustándose a los requisitos y al procedimiento establecido.',null),
('adm-cm:12-7d449a6d51','adm-cm',12,'La obligación de notificar en plazo se entiende cumplida, en las notificaciones electrónicas, con:','["La puesta a disposición de la notificación en la sede electrónica o en la dirección electrónica habilitada única", "La publicación de un anuncio en el BOE", "El envío del aviso al correo electrónico del interesado, aunque no se ponga a disposición la notificación", "El acceso efectivo del interesado"]'::jsonb,0,'Art. 43.3 Ley 39/2015','Se entiende cumplida con la puesta a disposición en la sede electrónica o la dirección electrónica habilitada única.',null),
('adm-cm:12-075d61439f','adm-cm',12,'¿A quién debe notificar el órgano que dicte una resolución?','["A los interesados cuyos derechos e intereses sean afectados por ella", "A todos los vecinos del municipio afectado", "Solo al solicitante, aunque haya otros interesados afectados", "Al superior jerárquico, que da traslado a los interesados"]'::jsonb,0,'Art. 40.1 Ley 39/2015','Se notifica a los interesados cuyos derechos e intereses sean afectados por las resoluciones y actos.',null),
('adm-cm:12-0d16c4d64b','adm-cm',12,'La nulidad en parte de un acto no implica la de las partes independientes, salvo que:','["Se haya notificado conjuntamente y en un mismo documento a todos los interesados afectados", "Sea un acto favorable al interesado", "La parte viciada sea de tal importancia que sin ella el acto no se habría dictado", "Lo solicite el interesado en el recurso que interponga contra el acto, justificando su conexión"]'::jsonb,2,'Art. 49.2 Ley 39/2015','Las partes independientes se mantienen, salvo que la parte viciada fuera esencial.',null),
('adm-cm:12-fe8059eb5e','adm-cm',12,'Según el art. 47.1 f), son nulos los actos expresos o presuntos contrarios al ordenamiento por los que se adquieren facultades o derechos:','["Cuando no haya terceros afectados por la adquisición", "Cuando sean favorables al interesado y no haya terceros afectados por ellos", "Cuando se hayan publicado en el boletín oficial sin haberse notificado a los interesados", "Cuando se carezca de los requisitos esenciales para su adquisición"]'::jsonb,3,'Art. 47.1 f) Ley 39/2015','Son nulos si se adquieren facultades o derechos careciendo de los requisitos esenciales.',null),
('adm-cm:12-4bd7cbe1de','adm-cm',12,'Es nulo de pleno derecho el acto que:','["Lesione los derechos y libertades susceptibles de amparo constitucional", "Se dicte fuera del plazo establecido", "Tenga un defecto de forma que no produzca indefensión", "Incurra en desviación de poder o en cualquier otra infracción del ordenamiento"]'::jsonb,0,'Art. 47.1 a) Ley 39/2015','La lesión de derechos susceptibles de amparo es causa de nulidad de pleno derecho.',null),
('adm-cm:12-21672372dd','adm-cm',12,'El órgano competente podrá inadmitir sin dictamen las solicitudes de revisión de oficio formuladas por interesados cuando:','["Se refieran a actos favorables", "Sean formuladas por personas jurídicas", "Se presenten en papel", "Carezcan manifiestamente de fundamento"]'::jsonb,3,'Art. 106.3 Ley 39/2015','También cuando no se basen en causas de nulidad o se hayan desestimado en cuanto al fondo otras sustancialmente iguales.','nov. 2024 · 1.er ejercicio'),
('adm-cm:12-a2cb96c945','adm-cm',12,'Si en la notificación en papel en el domicilio el interesado no está presente, podrá hacerse cargo de ella:','["Solo un familiar mayor de 18 años", "Cualquier persona mayor de 14 años que se encuentre en el domicilio y haga constar su identidad", "Cualquier persona mayor de 16 años que se encuentre en el domicilio, sin necesidad de hacer constar su identidad", "Únicamente el interesado"]'::jsonb,1,'Art. 42.2 Ley 39/2015','Puede recogerla cualquier persona mayor de catorce años que esté en el domicilio y haga constar su identidad.',null),
('adm-cm:12-f0c9238f57','adm-cm',12,'Las facultades de revisión no podrán ejercerse cuando:','["Lo solicite el propio interesado", "El acto sea nulo de pleno derecho", "Por prescripción de acciones, tiempo transcurrido u otras circunstancias, su ejercicio resulte contrario a la equidad, la buena fe, el derecho de los particulares o las leyes", "Haya transcurrido un año desde la notificación del acto, cualquiera que sea el vicio que lo afecte y aunque su ejercicio no resulte contrario a la equidad, la buena fe ni el derecho de los particulares"]'::jsonb,2,'Art. 110 Ley 39/2015','Son los límites de la revisión.',null),
('adm-cm:12-c04b29521f','adm-cm',12,'Los actos nulos o anulables que contengan los elementos constitutivos de otro distinto producirán los efectos de este. Esto se denomina:','["Revocación", "Conservación de actos y trámites", "Convalidación", "Conversión de actos viciados"]'::jsonb,3,'Art. 50 Ley 39/2015','Es la conversión de actos viciados.','oct. 2026 · 1.er ejercicio'),
('adm-cm:12-b590f90f5b','adm-cm',12,'Es nulo de pleno derecho el acto:','["Que incurra en cualquier infracción del ordenamiento jurídico, incluida la desviación de poder", "Cuyo defecto de forma no produzca indefensión", "Que sea constitutivo de infracción penal o se dicte como consecuencia de esta", "Dictado un día inhábil"]'::jsonb,2,'Art. 47.1 d) Ley 39/2015','Los actos constitutivos de infracción penal o dictados como consecuencia de esta son nulos.',null),
('adm-cm:12-a8c18761eb','adm-cm',12,'La declaración de lesividad de los actos favorables anulables tiene como finalidad:','["Sancionar al interesado que se benefició del acto", "Convertirlos en actos nulos de pleno derecho para poder revisarlos de oficio en cualquier momento", "Su posterior impugnación ante el orden jurisdiccional contencioso-administrativo", "Anularlos directamente en vía administrativa"]'::jsonb,2,'Art. 107.1 Ley 39/2015','La Administración declara la lesividad para impugnarlos después ante la jurisdicción contencioso-administrativa.',null),
('adm-cm:12-1fbdaf4518','adm-cm',12,'Son nulos de pleno derecho los actos:','["Dictados por órgano jerárquicamente incompetente", "Que tengan un contenido imposible", "Que no indiquen los recursos", "Que tengan un error material"]'::jsonb,1,'Art. 47.1 c) Ley 39/2015','El contenido imposible es causa de nulidad (art. 47.1 c).',null),
('adm-cm:12-efb0e3caef','adm-cm',12,'Si la Administración no envía el aviso al dispositivo o correo electrónico del interesado de que tiene una notificación electrónica:','["La notificación es nula y debe practicarse de nuevo", "La notificación puede considerarse plenamente válida", "La notificación debe repetirse en papel en el domicilio", "El plazo para acceder a la notificación se amplía diez días"]'::jsonb,1,'Art. 41.6 Ley 39/2015','La falta de práctica del aviso no impide que la notificación sea considerada plenamente válida.',null),
('adm-cm:12-c48fbf78b9','adm-cm',12,'Según el artículo 43 de la Ley 39/2015, la notificación por medios electrónicos se entiende rechazada cuando:','["Han transcurrido cinco días hábiles desde su envío sin que el interesado haya contestado ni presentado alegaciones", "Han transcurrido diez días naturales desde su puesta a disposición sin que se acceda a su contenido", "Han transcurrido quince días hábiles desde que se dictó el acto", "El interesado no contesta en veinticuatro horas al aviso enviado a su dirección de correo electrónico o a su móvil"]'::jsonb,1,'Art. 43.2 Ley 39/2015','Se entiende practicada en el momento en que se produce el acceso a su contenido.',null),
('adm-cm:12-c1e11ec35a','adm-cm',12,'Según la Ley 39/2015, toda notificación debe cursarse dentro del plazo de:','["Tres días a partir de la fecha en que el acto haya adquirido firmeza", "Un mes a partir de la fecha en que el acto haya sido dictado y firmado", "Diez días a partir de la fecha en que el acto haya sido dictado", "Quince días a partir de la fecha en que el acto haya sido publicado"]'::jsonb,2,'Art. 40.2 Ley 39/2015','Debe contener el texto íntegro de la resolución, si pone fin o no a la vía administrativa y los recursos que procedan.',null),
('adm-cm:12-d8de2e1ace','adm-cm',12,'¿Qué es la Dirección Electrónica Habilitada única (DEHú)?','["La dirección postal que el interesado designa para recibir las notificaciones en papel cuando no está obligado a relacionarse electrónicamente", "El punto donde el interesado puede consultar las notificaciones electrónicas que le remitan las Administraciones", "La sede electrónica del Ministerio competente en materia de función pública", "El correo electrónico oficial que la Administración asigna a cada ciudadano y a cada empresa para recibir sus comunicaciones oficiales"]'::jsonb,1,'Art. 43 Ley 39/2015 y RD 203/2021','Las notificaciones pueden practicarse por comparecencia en la sede electrónica o a través de la DEHú.',null),
('adm-cm:13-f2e1dcfda5','adm-cm',13,'¿Cuál de las siguientes NO es una forma de iniciación de oficio del procedimiento?','["Propia iniciativa del órgano", "Orden superior", "Solicitud del interesado", "Petición razonada de otros órganos"]'::jsonb,2,'Art. 58 Ley 39/2015','De oficio se inicia por propia iniciativa, orden superior, petición razonada de otros órganos o denuncia. La solicitud del interesado es la otra vía de inicio.',null),
('adm-cm:13-fb0455c7b4','adm-cm',13,'Si la solicitud no reúne los requisitos exigidos, se requiere al interesado para que la subsane en el plazo de:','["5 días, con indicación de que si no lo hace se archivará sin más trámite", "10 días, con indicación de que si no lo hace se le tendrá por desistido", "15 días, con indicación de que si no lo hace se le tendrá por desistido", "10 días, con indicación de que si no lo hace se declarará la caducidad"]'::jsonb,1,'Art. 68.1 Ley 39/2015','Se le da un plazo de diez días, con apercibimiento de que, si no lo hace, se le tendrá por desistido.','oct. 2026 · 1.er ejercicio'),
('adm-cm:13-120cdd150d','adm-cm',13,'El periodo de prueba en el procedimiento administrativo tiene una duración:','["No superior a 15 días ni inferior a 5", "De 20 días exactos", "No superior a 30 días ni inferior a 10", "No superior a 2 meses"]'::jsonb,2,'Art. 77.2 Ley 39/2015','El periodo de prueba no puede ser superior a treinta días ni inferior a diez.','oct. 2026 · 1.er ejercicio'),
('adm-cm:13-511377ae2f','adm-cm',13,'Salvo disposición expresa en contrario, los informes son:','["Preceptivos y vinculantes", "Preceptivos y no vinculantes", "Facultativos y vinculantes", "Facultativos y no vinculantes"]'::jsonb,3,'Art. 80.1 Ley 39/2015','Salvo disposición expresa, los informes son facultativos y no vinculantes.',null),
('adm-cm:13-d825da30e0','adm-cm',13,'Salvo que se fije otro plazo, los informes deben emitirse en:','["10 días", "15 días", "1 mes", "3 días"]'::jsonb,0,'Art. 80.2 Ley 39/2015','Los informes se emiten en el plazo de diez días, salvo que una disposición o el cumplimiento del resto de plazos exija otro.',null),
('adm-cm:13-920dbb4e2b','adm-cm',13,'En el trámite de audiencia, los interesados disponen de un plazo:','["No inferior a 5 días ni superior a 10", "No inferior a 10 días ni superior a 15", "De 20 días", "No inferior a 15 días ni superior a 30"]'::jsonb,1,'Art. 82.2 Ley 39/2015','El plazo de audiencia no puede ser inferior a diez días ni superior a quince.',null),
('adm-cm:13-5b400da893','adm-cm',13,'El plazo del trámite de información pública no puede ser inferior a:','["10 días", "15 días", "20 días", "1 mes"]'::jsonb,2,'Art. 83.2 Ley 39/2015','El plazo de información pública no puede ser inferior a veinte días.','nov. 2024 · 1.er ejercicio'),
('adm-cm:13-5d3cd64bfa','adm-cm',13,'¿Cuál de las siguientes NO pone fin al procedimiento administrativo?','["La resolución", "El desistimiento", "La declaración de caducidad", "La interposición de un recurso"]'::jsonb,3,'Art. 84.1 Ley 39/2015','Ponen fin al procedimiento la resolución, el desistimiento, la renuncia y la caducidad, y también la imposibilidad material sobrevenida.','nov. 2024 · 1.er ejercicio'),
('adm-cm:13-6f769c6e21','adm-cm',13,'En un procedimiento iniciado a solicitud que se paraliza por causa del interesado, la Administración le advierte de que se producirá la caducidad pasados:','["3 meses", "1 mes", "6 meses", "10 días"]'::jsonb,0,'Art. 95.1 Ley 39/2015','Transcurridos tres meses tras la advertencia sin que el interesado actúe, se produce la caducidad.',null),
('adm-cm:13-4a26913d49','adm-cm',13,'¿Cuál de los siguientes NO es un medio de ejecución forzosa de los actos administrativos?','["El apremio sobre el patrimonio", "La revocación del acto", "La ejecución subsidiaria", "La multa coercitiva"]'::jsonb,1,'Art. 100.1 Ley 39/2015','Los medios son el apremio sobre el patrimonio, la ejecución subsidiaria, la multa coercitiva y la compulsión sobre las personas.',null),
('adm-cm:13-ef7422dad7','adm-cm',13,'Se podrá prescindir del trámite de audiencia cuando:','["Se trate de un procedimiento sancionador o de responsabilidad patrimonial", "El interesado sea una persona jurídica obligada a relacionarse electrónicamente", "No figuren ni sean tenidos en cuenta otros hechos, alegaciones o pruebas que los aducidos por el interesado", "Lo acuerde motivadamente el instructor por razones de urgencia, aunque se tengan en cuenta hechos nuevos no aportados por el interesado"]'::jsonb,2,'Art. 82.4 Ley 39/2015','Si solo se valora lo aportado por el interesado, la audiencia puede omitirse.',null),
('adm-cm:13-636e5e5ee7','adm-cm',13,'A los interesados que no cumplan lo dispuesto en un trámite:','["Se les tendrá por desistidos de su solicitud y se archivará el procedimiento sin más trámite", "Se les podrá declarar decaídos en su derecho al trámite correspondiente", "Se les impondrá una multa coercitiva", "Se declara la caducidad"]'::jsonb,1,'Art. 73.3 Ley 39/2015','Se admitirá su actuación si se produce antes o dentro del día en que se notifique la resolución que tenga por transcurrido el plazo.',null),
('adm-cm:13-1a28d12182','adm-cm',13,'Según el art. 98.1, tampoco son inmediatamente ejecutivos los actos:','["Que sean favorables al interesado", "Que necesiten aprobación o autorización superior", "Que pongan fin a la vía administrativa y no hayan sido recurridos", "Que hayan sido notificados con indicación de los recursos procedentes"]'::jsonb,1,'Art. 98.1 d) Ley 39/2015','Tampoco cuando se acuerde su suspensión o una disposición establezca lo contrario.',null),
('adm-cm:13-2e0cf6e286','adm-cm',13,'Es un derecho del interesado en el procedimiento:','["Obtener una resolución favorable si la Administración no resuelve en plazo", "Conocer en cualquier momento el estado de la tramitación de los procedimientos en los que sea interesado", "Elegir al instructor del procedimiento", "Conocer en cualquier momento el estado de tramitación de cualquier procedimiento de la Administración, aunque no tenga la condición de interesado"]'::jsonb,1,'Art. 53.1 a) Ley 39/2015','También el sentido del silencio, el órgano competente y obtener copia de los documentos.',null),
('adm-cm:13-6078d99158','adm-cm',13,'La declaración responsable es el documento por el que el interesado manifiesta, bajo su responsabilidad:','["Que acepta cualquier sanción que se derive de la falsedad de los datos aportados", "Que cumple los requisitos de la normativa vigente, dispone de la documentación que lo acredita y la pondrá a disposición de la Administración cuando se le requiera", "Que cumple los requisitos de la normativa vigente y aporta en ese momento toda la documentación que lo acredita, sin que la Administración pueda requerírsela después", "Que pone en conocimiento de la Administración sus datos identificativos"]'::jsonb,1,'Art. 69.1 Ley 39/2015','Definición legal de la declaración responsable.',null),
('adm-cm:13-afdda61927','adm-cm',13,'En ningún caso podrá imponerse a los administrados una obligación pecuniaria que:','["No se haya notificado con al menos quince días de antelación", "Supere los 3.000 euros sin autorización judicial previa y expresa", "No estuviese establecida con arreglo a una norma de rango legal", "No estuviese establecida en una norma de rango reglamentario aprobada por el Consejo de Gobierno o el Consejo de Ministros"]'::jsonb,2,'Art. 101.2 Ley 39/2015','Las obligaciones pecuniarias requieren base en una norma de rango legal.',null),
('adm-cm:13-0657a9cfbf','adm-cm',13,'La petición razonada de iniciación:','["No vincula al órgano competente, que deberá comunicar los motivos por los que, en su caso, no inicia", "Equivale a una denuncia y obliga a iniciar el procedimiento", "Solo puede formularla un ciudadano afectado", "Vincula al órgano competente para iniciar, que solo puede rechazarla si concurre una causa de inadmisión prevista en la ley"]'::jsonb,0,'Art. 61.2 Ley 39/2015','No es vinculante, pero hay que comunicar los motivos de no iniciar.',null),
('adm-cm:13-7e811a231d','adm-cm',13,'La multa coercitiva:','["Requiere autorización judicial previa en todo caso", "Es independiente de las sanciones que puedan imponerse y compatible con ellas", "Sustituye a la sanción que corresponda", "Es incompatible con las sanciones, de modo que si se impone una multa coercitiva no puede imponerse sanción por los mismos hechos"]'::jsonb,1,'Art. 103.2 Ley 39/2015','La multa coercitiva es independiente de las sanciones y compatible con ellas.',null),
('adm-cm:13-d9d6c1dfe8','adm-cm',13,'No podrá acordarse la caducidad del procedimiento por la simple inactividad del interesado en la cumplimentación de trámites:','["En ningún caso, cualquiera que sea el trámite omitido", "Siempre que no sean indispensables para dictar resolución", "Si el interesado es persona jurídica obligada a relacionarse electrónicamente", "Aunque sean indispensables para dictar resolución, si ha transcurrido el plazo"]'::jsonb,1,'Art. 95.2 Ley 39/2015','La inactividad en trámites no indispensables no da lugar a caducidad.',null),
('adm-cm:13-eb7180c55f','adm-cm',13,'En los procedimientos sancionadores, el presunto responsable tiene derecho, además:','["A elegir la sanción entre las previstas para la infracción", "A no declarar contra sí mismo, pero no a la presunción de inocencia, que es exclusiva del proceso penal", "A que se le notifique la sanción", "A la presunción de no existencia de responsabilidad administrativa mientras no se demuestre lo contrario"]'::jsonb,3,'Art. 53.2 b) Ley 39/2015','Es la presunción de inocencia en el ámbito sancionador.',null),
('adm-cm:13-5e8efdf600','adm-cm',13,'Las Administraciones pueden imponer multas coercitivas:','["Solo los Ayuntamientos, en el ejercicio de su potestad sancionadora", "Solo en materia tributaria", "Cuando así lo autoricen las leyes, y en la forma y cuantía que estas determinen", "Cuando lo autorice un reglamento, en la forma y cuantía que determine el órgano que ordena la ejecución"]'::jsonb,2,'Art. 103.1 Ley 39/2015','Requieren autorización legal y se reiteran por lapsos de tiempo suficientes para cumplir lo ordenado.',null),
('adm-cm:13-8105f06c2f','adm-cm',13,'La efectividad de las reducciones por reconocimiento o pago voluntario está condicionada a:','["El desistimiento o renuncia de cualquier acción o recurso en vía administrativa contra la sanción", "Que la sanción sea inferior a 300 euros", "El desistimiento o renuncia de cualquier acción o recurso, tanto en vía administrativa como contencioso-administrativa", "La conformidad de la víctima o del denunciante y la renuncia expresa a la vía contencioso-administrativa"]'::jsonb,0,'Art. 85.3 Ley 39/2015','El infractor debe desistir o renunciar a recursos administrativos.',null),
('adm-cm:13-143ab9bbdc','adm-cm',13,'Si para la ejecución forzosa fuese necesario entrar en el domicilio del afectado, se requiere:','["Su consentimiento o, en su defecto, la oportuna autorización judicial", "Basta la resolución administrativa que ordena la ejecución, notificada al afectado", "Autorización del Delegado del Gobierno o, en su defecto, del alcalde", "Su consentimiento o, en su defecto, autorización del órgano superior jerárquico del que ordenó la ejecución"]'::jsonb,0,'Art. 100.3 Ley 39/2015','Se necesita el consentimiento del afectado o autorización judicial.',null),
('adm-cm:13-15a7078dd8','adm-cm',13,'Los procedimientos caducados:','["Impiden iniciar uno nuevo", "Interrumpen la prescripción", "No interrumpirán el plazo de prescripción", "Producen por sí solos la prescripción de las acciones"]'::jsonb,2,'Art. 95.3 Ley 39/2015','La caducidad no produce por sí sola la prescripción, pero el procedimiento caducado no la interrumpe.',null),
('adm-cm:13-8a353dabf4','adm-cm',13,'En los procedimientos de responsabilidad patrimonial es preceptivo solicitar informe al servicio cuyo funcionamiento haya ocasionado la presunta lesión, que deberá emitirse en un plazo máximo de:','["Dos meses", "Quince días", "Un mes", "Diez días"]'::jsonb,3,'Art. 81.1 Ley 39/2015','El informe del servicio no puede exceder de diez días.',null),
('adm-cm:13-51ab4c2122','adm-cm',13,'En los procedimientos sancionadores, los hechos declarados probados por resoluciones judiciales penales firmes:','["No vinculan a la Administración, que debe valorarlos libremente", "Solo vinculan si el interesado lo solicita expresamente en sus alegaciones al acuerdo de iniciación", "Vincularán a las Administraciones Públicas en los procedimientos sancionadores que substancien", "Vincularán a las Administraciones solo si la sentencia penal es condenatoria y se dictó antes de iniciarse el procedimiento"]'::jsonb,2,'Art. 77.4 Ley 39/2015','Los hechos probados en sentencia penal firme vinculan a la Administración.',null),
('adm-cm:13-329b08a074','adm-cm',13,'La resolución del procedimiento se dictará:','["Por escrito en papel, firmado por el titular del órgano", "Electrónicamente, garantizando la identidad del órgano competente y la autenticidad e integridad del documento", "Electrónicamente o en papel, a elección del órgano, garantizando solo la identidad del firmante y no la integridad del documento", "Verbalmente, con constancia en acta"]'::jsonb,1,'Art. 88.4 Ley 39/2015','La resolución se dicta electrónicamente.',null),
('adm-cm:13-6942d13add','adm-cm',13,'¿Quién puede acordar un período de información pública?','["El órgano al que corresponda la resolución del procedimiento, cuando su naturaleza lo requiera", "El instructor del procedimiento, a petición de cualquier interesado y siempre que lo autorice el órgano superior jerárquico", "Cualquier interesado, comunicándolo al órgano instructor, siempre que lo considere útil para su defensa", "El órgano que inició el procedimiento, solo en los procedimientos sancionadores"]'::jsonb,0,'Art. 83.1 Ley 39/2015','Lo acuerda el órgano competente para resolver.',null),
('adm-cm:13-e601f97250','adm-cm',13,'Excepcionalmente, cuando al iniciar el procedimiento sancionador no existan elementos suficientes para la calificación inicial de los hechos, esta podrá realizarse en una fase posterior mediante:','["Una propuesta de resolución que deberá notificarse a los interesados", "La elaboración de un Pliego de cargos, que deberá ser notificado a los interesados", "La elaboración de un Pliego de cargos, que no se notifica a los interesados hasta la propuesta de resolución definitiva del instructor", "Un nuevo acuerdo de iniciación"]'::jsonb,1,'Art. 64.3 Ley 39/2015','Se elabora un Pliego de cargos que se notifica a los interesados.',null),
('adm-cm:13-8e0cf61dc0','adm-cm',13,'NO será inmediatamente ejecutiva la resolución:','["De un procedimiento sancionador contra la que quepa algún recurso en vía administrativa, incluido el potestativo de reposición", "De un procedimiento sancionador contra la que quepa recurso de alzada, pero no si solo cabe el potestativo de reposición", "De una solicitud de licencia que haya sido estimada", "De un recurso de alzada"]'::jsonb,0,'Art. 98.1 b) Ley 39/2015','Las sanciones no son ejecutivas mientras quepa recurso administrativo.',null),
('adm-cm:13-b45909a70b','adm-cm',13,'Iniciado un procedimiento sancionador, si el infractor reconoce su responsabilidad:','["Se reduce la sanción a la mitad de forma automática", "Se archiva el procedimiento sin imponer sanción, si el infractor paga voluntariamente", "Se podrá resolver el procedimiento con la imposición de la sanción que proceda", "Se podrá resolver el procedimiento sin imponer sanción, salvo que la infracción sea muy grave o el infractor sea reincidente"]'::jsonb,2,'Art. 85.1 Ley 39/2015','El reconocimiento permite resolver con la sanción procedente.',null),
('adm-cm:13-4eac878cd2','adm-cm',13,'La ejecución subsidiaria procede respecto de actos que:','["Impongan obligaciones de no hacer o de soportar, previo apercibimiento al obligado", "Impongan al obligado el pago de cantidades líquidas", "Sean personalísimos de hacer y el obligado se niegue a realizarlos en el plazo fijado", "Por no ser personalísimos puedan ser realizados por sujeto distinto del obligado"]'::jsonb,3,'Art. 102.1 Ley 39/2015','Cabe cuando el acto no es personalísimo y otro sujeto puede realizarlo.',null),
('adm-cm:13-82b5a2d685','adm-cm',13,'Si antes del vencimiento del plazo de audiencia los interesados manifiestan su decisión de no efectuar alegaciones:','["Se tendrá por decaído su derecho y se archivará el procedimiento", "Se tendrá por realizado el trámite", "Se ampliará de oficio el plazo para que puedan reconsiderar su decisión, que no será vinculante hasta su vencimiento", "Se suspenderá el procedimiento"]'::jsonb,1,'Art. 82.3 Ley 39/2015','El trámite se tiene por realizado.',null),
('adm-cm:13-5ef8d66f84','adm-cm',13,'Si el órgano competente para resolver considera que la infracción o la sanción revisten mayor gravedad que la propuesta, se notificará al inculpado para alegaciones en un plazo de:','["Quince días", "Diez días", "Cinco días", "Un mes"]'::jsonb,0,'Art. 90.2 Ley 39/2015','El inculpado dispone de quince días para alegar.',null),
('adm-cm:13-1d22e6f7cb','adm-cm',13,'Los trámites que deban ser cumplimentados por los interesados se realizarán, salvo plazo distinto, en el plazo de:','["Diez días a partir del siguiente al de la notificación del correspondiente acto", "Cinco días a partir del siguiente al de la notificación", "Quince días a partir del siguiente al de la notificación del correspondiente acto", "Diez días a partir del mismo día de la notificación"]'::jsonb,0,'Art. 73.1 Ley 39/2015','El plazo general es de diez días.','abr. 2026 · 1.er ejercicio'),
('adm-cm:13-8f58dec223','adm-cm',13,'La ejecución forzosa de los actos administrativos se efectuará:','["Solo con autorización judicial previa", "Siempre mediante compulsión sobre las personas", "Respetando siempre el principio de proporcionalidad y por los medios menos restrictivos de la libertad individual", "Respetando el principio de eficacia, por el medio más rápido disponible aunque no sea el menos restrictivo de la libertad individual"]'::jsonb,2,'Art. 99 Ley 39/2015','La ejecución forzosa respeta la proporcionalidad y elige el medio menos restrictivo.',null),
('adm-cm:13-c2d5cb4914','adm-cm',13,'Según el art. 54, los procedimientos podrán iniciarse:','["De oficio o a solicitud del interesado", "Solo de oficio, por propia iniciativa del órgano", "De oficio, a solicitud del interesado o por orden judicial", "Solo a solicitud"]'::jsonb,0,'Art. 54 Ley 39/2015','Las dos clases de iniciación son de oficio y a solicitud del interesado.',null),
('adm-cm:13-b52dc424c1','adm-cm',13,'La Administración puede abstenerse de resolver alegando silencio, oscuridad o insuficiencia de los preceptos legales:','["En ningún caso", "Sí, si lo autoriza el superior", "Sí, cuando la ley sea oscura", "Sí, en los procedimientos de oficio"]'::jsonb,0,'Art. 88.5 Ley 39/2015','Nunca puede abstenerse por esos motivos, aunque puede inadmitir solicitudes de derechos no previstos o manifiestamente carentes de fundamento.',null),
('adm-cm:13-fdc8efb74d','adm-cm',13,'En el procedimiento sancionador se podrá adoptar la tramitación simplificada cuando:','["El infractor sea reincidente y reconozca su responsabilidad", "Existan elementos de juicio suficientes para calificar la infracción como leve", "Existan elementos de juicio suficientes para calificar la infracción como leve o grave", "La infracción sea muy grave y urgente, o lo solicite expresamente el denunciante"]'::jsonb,1,'Art. 96.5 Ley 39/2015','Procede si la infracción se califica como leve.',null),
('adm-cm:13-537ade7a38','adm-cm',13,'Las actuaciones complementarias deberán practicarse en un plazo no superior a:','["Un mes", "Quince días", "Siete días", "Tres meses"]'::jsonb,1,'Art. 87 Ley 39/2015','El plazo para resolver queda suspendido hasta su terminación.',null),
('adm-cm:13-5bbfdd780a','adm-cm',13,'El apremio sobre el patrimonio procede cuando, en virtud del acto, haya de satisfacerse:','["Una obligación de no hacer", "Una cantidad líquida", "Una obligación de soportar", "Una obligación personalísima"]'::jsonb,1,'Art. 101.1 Ley 39/2015','Si hay que satisfacer cantidad líquida se sigue el procedimiento de apremio.',null),
('adm-cm:13-f61dfab907','adm-cm',13,'También producirá la terminación del procedimiento:','["La falta de crédito presupuestario adecuado y suficiente", "La imposibilidad material de continuarlo por causas sobrevenidas, mediante resolución motivada", "La imposibilidad material de continuarlo, que se produce automáticamente sin necesidad de resolución", "El cambio del funcionario instructor, o la falta de crédito presupuestario adecuado para continuarlo"]'::jsonb,1,'Art. 84.2 Ley 39/2015','La resolución que se dicte deberá ser motivada en todo caso.',null),
('adm-cm:13-2538f093c4','adm-cm',13,'Los actos de instrucción necesarios para determinar, conocer y comprobar los hechos se realizarán:','["Solo a instancia de los interesados y en papel, que deben proponer las actuaciones necesarias, sin que el órgano que tramite el procedimiento pueda acordarlas de oficio", "Por el órgano que tramite el procedimiento, en papel y sin uso de medios electrónicos, sin que los interesados puedan proponer actuaciones complementarias", "Por el instructor, a propuesta del Consejo de Estado", "De oficio y por medios electrónicos por el órgano que tramite el procedimiento, sin perjuicio del derecho de los interesados a proponer actuaciones"]'::jsonb,3,'Art. 75.1 Ley 39/2015','La instrucción se hace de oficio.',null),
('adm-cm:13-fb25487ce4','adm-cm',13,'En los procedimientos de responsabilidad patrimonial, el acuerdo alcanzado entre el interesado y el órgano competente deberá fijar:','["La culpa del funcionario causante del daño", "La sanción disciplinaria del empleado público responsable", "La cuantía de la indemnización, pero no el modo, que fija después el órgano competente", "La cuantía y el modo de indemnización"]'::jsonb,3,'Art. 86.5 Ley 39/2015','El acuerdo fija la cuantía y el modo de indemnización.',null),
('adm-cm:13-965e1f61cc','adm-cm',13,'En los procedimientos iniciados de oficio, la Administración podrá desistir:','["Libremente y sin necesidad de motivación", "Motivadamente, en los supuestos y con los requisitos previstos en las leyes", "Solo con autorización judicial", "Motivadamente, en cualquier supuesto, sin necesidad de previsión legal"]'::jsonb,1,'Art. 93 Ley 39/2015','El desistimiento de la Administración debe ser motivado y legalmente previsto.',null),
('adm-cm:13-1ac5edaf23','adm-cm',13,'Las Administraciones podrán celebrar acuerdos, pactos, convenios o contratos que pongan fin al procedimiento siempre que:','["El interesado sea una persona jurídica y el acuerdo se refiera a materias de contenido económico o patrimonial", "No sean contrarios al ordenamiento jurídico ni versen sobre materias no susceptibles de transacción", "Se refieran a sanciones de cuantía inferior a 3.000 euros", "Lo autorice un juez"]'::jsonb,1,'Art. 86.1 Ley 39/2015','Es la terminación convencional.',null),
('adm-cm:13-32a5b4b9e0','adm-cm',13,'Las Administraciones no iniciarán ninguna actuación material de ejecución que limite derechos de los particulares:','["Sin informe favorable del Consejo de Estado u órgano consultivo equivalente", "Sin el consentimiento expreso y por escrito del particular afectado por la actuación", "Sin que previamente haya sido adoptada la resolución que le sirva de fundamento jurídico", "Sin autorización judicial en todo caso"]'::jsonb,2,'Art. 97.1 Ley 39/2015','Es necesario un título previo: la resolución que sirve de fundamento jurídico.',null),
('adm-cm:13-3d3ded3957','adm-cm',13,'El instructor solo podrá rechazar las pruebas propuestas por los interesados cuando:','["Sean costosas para la Administración, aunque sean pertinentes y necesarias, mediante resolución motivada", "Sean manifiestamente improcedentes o innecesarias, mediante resolución motivada", "Sean improcedentes a su juicio, sin necesidad de motivar el rechazo ni notificarlo a los interesados", "Se propongan fuera del plazo de diez días"]'::jsonb,1,'Art. 77.3 Ley 39/2015','El rechazo de pruebas debe ser motivado y basarse en su improcedencia o innecesariedad manifiesta.',null),
('adm-cm:13-eaf484ff6c','adm-cm',13,'El procedimiento está sometido al principio de:','["Rogación exclusiva del interesado, que lo impulsa en todos sus trámites mediante escritos sucesivos", "Celeridad, y se impulsará de oficio en todos sus trámites y a través de medios electrónicos", "Secreto de las actuaciones", "Oralidad, y se impulsará a instancia de los interesados en cada uno de sus trámites, en papel"]'::jsonb,1,'Art. 71.1 Ley 39/2015','El impulso es de oficio, con respeto a la transparencia y la publicidad.','abr. 2026 · 1.er ejercicio'),
('adm-cm:13-a8f3effab3','adm-cm',13,'En la petición de un informe se concretará:','["El plazo de tres meses para su emisión y el sentido del informe", "El extremo o extremos acerca de los que se solicita", "El sentido que debe tener el informe y el plazo para emitirlo", "El nombre del funcionario que debe emitirlo"]'::jsonb,1,'Art. 79.2 Ley 39/2015','Hay que concretar los extremos sobre los que se pide el informe.',null),
('adm-cm:13-042cb4711d','adm-cm',13,'La acumulación de procedimientos exige, entre otros requisitos, que:','["Lo soliciten todos los interesados por escrito", "Sea el mismo órgano quien deba tramitar y resolver el procedimiento", "Estén en la misma fase de tramitación y se refieran al mismo interesado o a interesados distintos", "Los interesados sean los mismos y los procedimientos estén en la misma fase"]'::jsonb,1,'Art. 57 Ley 39/2015','Se acumulan los que guarden identidad sustancial o íntima conexión y los tramite y resuelva el mismo órgano.',null),
('adm-cm:13-c5bf7fcade','adm-cm',13,'Según el art. 53.1 d), los interesados pueden formular alegaciones y aportar documentos:','["Solo en la solicitud inicial", "Solo en el período de prueba", "En cualquier fase del procedimiento anterior al trámite de audiencia", "En cualquier fase del procedimiento, incluso después de dictarse la resolución"]'::jsonb,2,'Art. 53.1 d) Ley 39/2015','Hasta el trámite de audiencia, que deberán ser tenidos en cuenta al redactar la propuesta de resolución.',null),
('adm-cm:13-cb41475b09','adm-cm',13,'Los interesados podrán aducir alegaciones y aportar documentos:','["En cualquier momento del procedimiento anterior al trámite de audiencia", "En cualquier momento, incluso tras la resolución", "Solo tras la propuesta de resolución", "Solo en los diez primeros días desde el inicio del procedimiento"]'::jsonb,0,'Art. 76.1 Ley 39/2015','Serán tenidos en cuenta al redactar la propuesta de resolución.',null),
('adm-cm:13-2921ca9b50','adm-cm',13,'Si en un procedimiento simplificado el dictamen preceptivo del Consejo de Estado se manifiesta en contra del fondo de la propuesta de resolución:','["El órgano competente acordará continuar el procedimiento con arreglo a la tramitación ordinaria", "Se archiva el procedimiento", "Se resuelve igualmente según la propuesta de resolución", "El órgano competente acordará un nuevo trámite de audiencia y resolverá por la tramitación simplificada"]'::jsonb,0,'Art. 96.7 Ley 39/2015','Se pasa a la tramitación ordinaria.',null),
('adm-cm:13-3cd319dad0','adm-cm',13,'Cuando la sanción tenga únicamente carácter pecuniario, el reconocimiento de responsabilidad y el pago voluntario dan lugar a reducciones de:','["Exactamente el 50 % del importe de la sanción propuesta, no acumulables", "El 30 % solo por pronto pago", "El 10 %, no acumulable", "Al menos el 20 % sobre el importe de la sanción propuesta, acumulables entre sí"]'::jsonb,3,'Art. 85.3 Ley 39/2015','Las reducciones son de al menos el 20 % cada una, acumulables, y pueden incrementarse reglamentariamente.',null),
('adm-cm:13-e197a8c3fe','adm-cm',13,'Las cuestiones incidentales que se susciten en el procedimiento, incluso las que se refieran a la nulidad de actuaciones:','["Suspenden la tramitación, salvo la abstención", "Determinan el archivo provisional del procedimiento hasta su resolución por el órgano superior", "No suspenderán la tramitación del procedimiento, salvo la recusación", "Suspenden siempre la tramitación"]'::jsonb,2,'Art. 74 Ley 39/2015','Solo la recusación suspende el procedimiento.',null),
('adm-cm:13-89a21ff98b','adm-cm',13,'Según el principio de simplificación administrativa, se acordarán en un solo acto:','["Todos los recursos de un mismo interesado frente a actos distintos", "La iniciación, la instrucción y la resolución, cuando el procedimiento se tramite por la vía simplificada y lo solicite el interesado", "Todos los trámites de un mismo interesado, aunque sea obligado su cumplimiento sucesivo", "Todos los trámites que, por su naturaleza, admitan un impulso simultáneo y no sea obligado su cumplimiento sucesivo"]'::jsonb,3,'Art. 72.1 Ley 39/2015','Concentración de trámites.',null),
('adm-cm:13-7ff74ade8e','adm-cm',13,'La compulsión sobre las personas procede, en los casos que la ley expresamente lo autorice, para:','["Obligaciones no personalísimas de hacer que puedan cumplirse por otro", "Cobrar cantidades líquidas", "Cualquier acto, a elección de la Administración", "Actos que impongan una obligación personalísima de no hacer o soportar"]'::jsonb,3,'Art. 104.1 Ley 39/2015','Se aplica a obligaciones personalísimas de no hacer o soportar, respetando la dignidad y los derechos constitucionales.',null),
('adm-cm:13-242718433c','adm-cm',13,'Si la resolución va a pronunciarse sobre cuestiones conexas no planteadas por los interesados, el órgano competente debe ponerlo de manifiesto a estos por un plazo:','["De tres días", "De un mes", "No superior a quince días", "No inferior a veinte días"]'::jsonb,2,'Art. 88.1 Ley 39/2015','Se da audiencia por plazo no superior a quince días.',null),
('adm-cm:13-bf23561577','adm-cm',13,'En los procedimientos sancionadores, la fase instructora y la sancionadora:','["Corresponderán al mismo órgano, salvo que la ley disponga otra cosa", "Las realiza el denunciante y el órgano competente, respectivamente", "Se tramitan como una sola fase", "Se encomendarán a órganos distintos"]'::jsonb,3,'Art. 63.1 Ley 39/2015','Los procedimientos sancionadores se inician siempre de oficio y separan instrucción y resolución.',null),
('adm-cm:13-9dc80fb08e','adm-cm',13,'En la notificación de la práctica de una prueba se consignará el lugar, fecha y hora, con la advertencia de que el interesado:','["Puede nombrar técnicos para que le asistan", "Debe comparecer acompañado de notario o de abogado colegiado", "No puede asistir a su práctica", "Debe abonar en todo caso los gastos de la prueba"]'::jsonb,0,'Art. 78.2 Ley 39/2015','Se le advierte que puede nombrar técnicos que le asistan.',null),
('adm-cm:13-11797912e5','adm-cm',13,'En los procedimientos sancionadores, la orden superior de iniciación expresará, en la medida de lo posible:','["El sentido de la resolución que deba dictarse", "La sanción que corresponda imponer, el órgano competente para resolver, el instructor designado y el plazo máximo para dictar resolución", "El nombre del abogado defensor del presunto responsable y la sanción que corresponde imponerle según la tipificación", "La persona o personas presuntamente responsables, las conductas o hechos, su tipificación y el lugar y fecha"]'::jsonb,3,'Art. 60.2 Ley 39/2015','La orden superior debe concretar responsables, hechos, tipificación, lugar y fecha.',null),
('adm-cm:13-0776ba74bc','adm-cm',13,'En la ejecución subsidiaria, el importe de los gastos podrá liquidarse:','["De forma provisional y realizarse antes de la ejecución, a reserva de la liquidación definitiva", "Por el doble de su coste, en concepto de sanción", "Nunca, porque los gastos los asume siempre la Administración que ejecuta", "Solo tras la ejecución, de forma definitiva y sin posibilidad de liquidación provisional"]'::jsonb,0,'Art. 102.4 Ley 39/2015','Cabe liquidación provisional previa a reserva de la definitiva; los gastos corren a cargo del obligado.',null),
('adm-cm:13-e7fb149d54','adm-cm',13,'Requerirán en todo caso la aprobación expresa del Consejo de Ministros u órgano equivalente de las CCAA:','["Todos los acuerdos convencionales que pongan fin a cualquier procedimiento", "Los acuerdos de los Ayuntamientos", "Los acuerdos que versen sobre materias de la competencia directa de dicho órgano", "Los acuerdos de cuantía superior a 6.000 €"]'::jsonb,2,'Art. 86.3 Ley 39/2015','Solo los que versen sobre materias de su competencia directa.',null),
('adm-cm:13-c12d59b65e','adm-cm',13,'En la AGE, los procedimientos de responsabilidad patrimonial se resolverán, como regla general, por:','["El Ministro respectivo", "El Subsecretario", "El Presidente del Gobierno", "El Delegado del Gobierno"]'::jsonb,0,'Art. 92 Ley 39/2015','Por el Consejo de Ministros en los casos del art. 32.3 LRJSP o cuando una ley lo disponga.',null),
('adm-cm:13-56f9b31b2a','adm-cm',13,'En ningún caso se podrá imponer una sanción:','["Sin que se haya tramitado el oportuno procedimiento", "A una persona jurídica", "Superior a 600 euros sin autorización judicial", "Sin que el infractor esté asistido de abogado"]'::jsonb,0,'Art. 63.2 Ley 39/2015','La sanción exige siempre procedimiento previo.',null),
('adm-cm:13-98e567f4b7','adm-cm',13,'El acuerdo de realización de actuaciones complementarias se notificará a los interesados, concediéndoles un plazo para alegaciones tras su finalización de:','["Siete días", "Cinco días", "Quince días", "Diez días"]'::jsonb,0,'Art. 87 Ley 39/2015','Plazo de siete días para alegaciones; las actuaciones se practican en un máximo de quince días y el plazo para resolver queda suspendido.',null),
('adm-cm:13-259ff30e1c','adm-cm',13,'La comparecencia en el trámite de información pública:','["Solo pueden hacerla los vecinos del municipio afectado", "Es obligatoria para poder recurrir después la resolución", "Convierte en interesado al compareciente", "No otorga, por sí misma, la condición de interesado"]'::jsonb,3,'Art. 83.3 Ley 39/2015','La incomparecencia tampoco impide a los interesados recurrir la resolución.',null),
('adm-cm:13-8420527056','adm-cm',13,'Contra el acuerdo de acumulación de procedimientos:','["No procederá recurso alguno", "Cabe recurso de reposición", "Cabe recurso extraordinario de revisión", "Cabe recurso de alzada"]'::jsonb,0,'Art. 57 Ley 39/2015','La acumulación procede si hay identidad sustancial o íntima conexión y el mismo órgano tramita y resuelve.',null),
('adm-cm:13-b504487245','adm-cm',13,'Si la Administración acuerda de oficio la tramitación simplificada y algún interesado manifiesta su oposición expresa:','["Se mantiene la tramitación simplificada si el órgano lo motiva por razones de interés público", "Se mantiene la tramitación simplificada", "Se mantiene la tramitación simplificada si el órgano lo motiva", "La Administración deberá seguir la tramitación ordinaria"]'::jsonb,3,'Art. 96.2 Ley 39/2015','La oposición expresa de un interesado obliga a la tramitación ordinaria.',null),
('adm-cm:13-3c58a89cee','adm-cm',13,'La resolución que ponga fin al procedimiento sancionador será ejecutiva cuando:','["Lo decida motivadamente el instructor del procedimiento", "No quepa contra ella ningún recurso ordinario en vía administrativa", "Se notifique al interesado, aunque quepa contra ella recurso de alzada", "Se dicte por el órgano competente, aunque quepa contra ella recurso de alzada"]'::jsonb,1,'Art. 90.3 Ley 39/2015','Puede suspenderse cautelarmente si el interesado manifiesta que interpondrá recurso contencioso-administrativo.',null),
('adm-cm:13-3a9b25d22a','adm-cm',13,'Si la cuestión suscitada entrañase interés general, la Administración ante un desistimiento o renuncia:','["Podrá limitar sus efectos al interesado y seguirá el procedimiento", "Deberá aceptarlo de plano y declarar concluso el procedimiento para todos los interesados", "Deberá archivar el procedimiento", "Deberá pedir dictamen al Consejo de Estado"]'::jsonb,0,'Art. 94.5 Ley 39/2015','El procedimiento continúa por el interés general.',null),
('adm-cm:13-e0f9ee3a2c','adm-cm',13,'Si un informe preceptivo no se emite en plazo:','["Se entiende desfavorable a la pretensión del interesado y se continúa el procedimiento hasta su resolución", "Se entiende favorable", "Se podrá suspender el transcurso del plazo máximo legal para resolver el procedimiento", "Se archiva el procedimiento"]'::jsonb,2,'Art. 80.3 Ley 39/2015','Si no es preceptivo, se pueden proseguir las actuaciones.',null),
('adm-cm:13-dac16d1a6b','adm-cm',13,'Si un interesado solicita la tramitación simplificada y el órgano considera que no procede, podrá desestimarla en el plazo de:','["Cinco días desde su presentación, sin posibilidad de recurso", "Un mes desde su presentación, con recurso de alzada", "Diez días desde su presentación, con recurso de alzada", "Cinco días desde su presentación, con recurso potestativo de reposición"]'::jsonb,0,'Art. 96.3 Ley 39/2015','Transcurrido el plazo sin resolver, se entiende desestimada.',null),
('adm-cm:13-d30c479fea','adm-cm',13,'Los expedientes tendrán formato electrónico y se formarán mediante la agregación ordenada de documentos, con:','["Un sello en papel en cada documento", "Un resumen elaborado por el instructor con la relación de los interesados y de los trámites realizados", "La firma de todos los interesados en cada uno de los documentos que contenga", "Un índice numerado de todos los documentos que contenga cuando se remita"]'::jsonb,3,'Art. 70.2 Ley 39/2015','Deben incluir un índice numerado de todos los documentos.',null),
('adm-cm:13-aec0ba32e3','adm-cm',13,'La resolución en un procedimiento de responsabilidad patrimonial deberá pronunciarse sobre:','["La responsabilidad penal del empleado público que causó el daño y la sanción disciplinaria que le corresponda imponer", "La sanción disciplinaria al funcionario responsable y la cuantía de la indemnización", "La existencia o no de relación de causalidad, la valoración del daño y la cuantía y modo de indemnización", "La existencia de culpa o dolo del empleado, que es requisito para que nazca la responsabilidad de la Administración"]'::jsonb,2,'Art. 91.2 Ley 39/2015','Son los extremos obligatorios de la resolución.',null),
('adm-cm:13-c280885dff','adm-cm',13,'No se podrán adoptar medidas provisionales que:','["Sean proporcionadas al objetivo que se pretende garantizar, aunque se adopten antes del inicio del procedimiento en casos de urgencia", "Se adopten una vez iniciado el procedimiento, sin audiencia previa del interesado", "Afecten a la actividad económica del interesado o a su patrimonio, aunque no le causen ningún perjuicio de difícil o imposible reparación ni vulneren sus derechos", "Puedan causar perjuicio de difícil o imposible reparación a los interesados o impliquen violación de derechos amparados por las leyes"]'::jsonb,3,'Art. 56.4 Ley 39/2015','Las medidas provisionales tienen ese límite.',null),
('adm-cm:13-dea671228b','adm-cm',13,'En la tramitación simplificada, el trámite de audiencia solo se realiza cuando:','["Nunca, porque la tramitación simplificada lo suprime en todo caso", "Siempre, como en la tramitación ordinaria", "Lo pida cualquier tercero que no sea interesado", "La resolución vaya a ser desfavorable para el interesado"]'::jsonb,3,'Art. 96.6 d) Ley 39/2015','Las alegaciones al inicio se formulan en cinco días.',null),
('adm-cm:13-5f75c1890a','adm-cm',13,'Cuando la Administración establezca expresamente modelos específicos de presentación de solicitudes en un procedimiento concreto, estos serán:','["De uso obligatorio por los interesados", "Solo orientativos", "Exclusivos para personas jurídicas", "De uso voluntario"]'::jsonb,0,'Art. 66.6 Ley 39/2015','Los modelos específicos establecidos expresamente son de uso obligatorio.',null),
('adm-cm:13-fb60ffc9c6','adm-cm',13,'Si fueran varios los medios de ejecución admisibles, se elegirá:','["El más rápido para la Administración", "El que elija el interesado de entre los admisibles", "El más económico para la Administración actuante", "El menos restrictivo de la libertad individual"]'::jsonb,3,'Art. 100.2 Ley 39/2015','Se elige el menos restrictivo de la libertad individual.',null),
('adm-cm:13-b34e3d6cc0','adm-cm',13,'Según el art. 105, no se admitirán a trámite contra las actuaciones de los órganos administrativos realizadas en materia de su competencia y de acuerdo con el procedimiento legal:','["Los recursos contencioso-administrativos", "Las acciones posesorias", "Los recursos de alzada", "Las reclamaciones de responsabilidad"]'::jsonb,1,'Art. 105 Ley 39/2015','No se admiten acciones posesorias contra esas actuaciones.',null),
('adm-cm:13-f52422bb76','adm-cm',13,'De las solicitudes y escritos que presenten los interesados, estos podrán exigir:','["Una copia firmada por el titular del órgano destinatario", "La devolución de las tasas abonadas", "Una resolución inmediata sobre la admisión de la solicitud presentada", "El correspondiente recibo que acredite la fecha y hora de presentación"]'::jsonb,3,'Art. 66.3 Ley 39/2015','Pueden exigir recibo con fecha y hora de presentación.',null),
('adm-cm:13-341aa3b681','adm-cm',13,'La Administración aceptará de plano el desistimiento o la renuncia, salvo que terceros interesados personados insten la continuación en el plazo de:','["Cinco días desde que fueron notificados", "Un mes desde que fueron notificados", "Quince días desde que fueron notificados", "Diez días desde que fueron notificados"]'::jsonb,3,'Art. 94.4 Ley 39/2015','Los terceros tienen diez días para pedir la continuación.',null),
('adm-cm:13-0b712d4004','adm-cm',13,'Si se trata de obligaciones personalísimas de hacer y no se realiza la prestación, el obligado deberá:','["Resarcir los daños y perjuicios, a cuya liquidación y cobro se procederá en vía administrativa", "Ser objeto de compulsión sobre su persona hasta que realice la prestación, sin resarcimiento alguno", "Nada, la obligación se extingue", "Resarcir los daños y perjuicios, cuya liquidación y cobro solo pueden exigirse en vía judicial civil"]'::jsonb,0,'Art. 104.2 Ley 39/2015','El obligado debe resarcir daños y perjuicios.',null),
('adm-cm:13-f845a12570','adm-cm',13,'Con anterioridad al inicio del procedimiento, el órgano competente podrá abrir:','["El período de prueba", "Un período de información o actuaciones previas para conocer las circunstancias del caso y la conveniencia de iniciar", "El trámite de audiencia a los posibles interesados para que aleguen sobre la conveniencia de iniciar el procedimiento", "El trámite de información pública"]'::jsonb,1,'Art. 55.1 Ley 39/2015','Las actuaciones previas sirven para valorar si procede iniciar el procedimiento.',null),
('adm-cm:13-ee7724519b','adm-cm',13,'En el procedimiento sancionador, el órgano instructor resolverá la finalización con archivo de actuaciones, sin formular propuesta de resolución, cuando:','["La sanción que corresponda sea muy grave", "El denunciante lo solicite expresamente y retire la denuncia antes de la propuesta de resolución", "Los hechos probados no constituyan, de modo manifiesto, infracción administrativa", "El presunto infractor reconozca su responsabilidad y pague voluntariamente la sanción"]'::jsonb,2,'Art. 89.1 c) Ley 39/2015','También por inexistencia de los hechos, falta de prueba, falta de responsable o prescripción de la infracción.',null),
('adm-cm:13-a58c01574d','adm-cm',13,'Transcurridos seis meses desde el inicio de un procedimiento de responsabilidad patrimonial sin resolución ni acuerdo:','["El procedimiento caduca y se archivan las actuaciones sin pronunciamiento sobre la indemnización", "Se entiende estimada la reclamación", "Se paga automáticamente la indemnización", "Podrá entenderse que la resolución es contraria a la indemnización del particular"]'::jsonb,3,'Art. 91.3 Ley 39/2015','El silencio en responsabilidad patrimonial es desestimatorio.',null),
('adm-cm:13-1a3d16d0b8','adm-cm',13,'Las medidas provisionales adoptadas antes de iniciar el procedimiento deberán ser confirmadas, modificadas o levantadas en el acuerdo de iniciación, que deberá efectuarse:','["Dentro del mes siguiente a su adopción", "Dentro de los tres meses siguientes", "Dentro de los quince días siguientes a su adopción", "Dentro de los diez días siguientes a su adopción"]'::jsonb,2,'Art. 56.2 Ley 39/2015','Si no se inicia en ese plazo o el acuerdo no se pronuncia, las medidas quedan sin efecto.','oct. 2026 · 1.er ejercicio'),
('adm-cm:13-946969346d','adm-cm',13,'Los documentos formalizados por funcionarios con la condición de autoridad en los que se recojan hechos constatados por ellos:','["Tienen valor absoluto e irrebatible", "Solo tienen valor probatorio si los ratifica un juez o el instructor del procedimiento", "No tienen valor probatorio", "Harán prueba de estos salvo que se acredite lo contrario"]'::jsonb,3,'Art. 77.5 Ley 39/2015','Gozan de presunción de veracidad salvo prueba en contrario.',null),
('adm-cm:13-2fa63fd8ab','adm-cm',13,'Salvo que reste menos para su tramitación ordinaria, los procedimientos de tramitación simplificada deberán resolverse en:','["Tres meses desde el siguiente al que se notifique el acuerdo de tramitación simplificada", "Seis meses desde el inicio del procedimiento", "Treinta días desde el siguiente al que se notifique el acuerdo de tramitación simplificada", "Quince días desde el siguiente al que se notifique el acuerdo de tramitación simplificada"]'::jsonb,2,'Art. 96.6 Ley 39/2015','El plazo es de treinta días.',null),
('adm-cm:13-53560b6a9f','adm-cm',13,'Se entiende por propia iniciativa:','["La petición de un órgano sin competencia de iniciación", "La denuncia de un particular que pone los hechos en conocimiento del órgano competente para iniciar, sin que este tenga conocimiento directo de las circunstancias", "La actuación derivada del conocimiento directo o indirecto de las circunstancias o hechos por el órgano que tiene la competencia de iniciación", "La orden emitida por un órgano superior jerárquico del competente para iniciar, tras conocer los hechos por una denuncia o por una petición razonada de otro órgano"]'::jsonb,2,'Art. 59 Ley 39/2015','Es el conocimiento directo o indirecto por el propio órgano competente.',null),
('adm-cm:13-540ebeb51c','adm-cm',13,'En la resolución del procedimiento sancionador no se podrán aceptar hechos distintos de los determinados en el curso del procedimiento:','["Salvo que resulten más graves, en cuyo caso se notificarán al inculpado para que formule alegaciones", "Salvo en las infracciones leves, en las que sí pueden aceptarse", "Salvo que lo pida el denunciante", "Con independencia de su diferente valoración jurídica"]'::jsonb,3,'Art. 90.2 Ley 39/2015','Se protege el derecho de defensa del inculpado.',null),
('adm-cm:13-67d6714607','adm-cm',13,'En el procedimiento de responsabilidad patrimonial iniciado de oficio, el acuerdo de iniciación se notificará a los presuntos lesionados, concediéndoles un plazo para alegaciones y pruebas de:','["Un mes", "Cinco días", "Diez días", "Quince días"]'::jsonb,2,'Art. 65.2 Ley 39/2015','Se les concede diez días para aportar alegaciones, documentos o información y proponer pruebas.',null),
('adm-cm:13-6e040053be','adm-cm',13,'En los procedimientos tramitados a solicitud del interesado, la resolución será congruente con las peticiones formuladas:','["Solo si el instructor lo propone y el interesado no se opone", "Pudiendo agravar su situación inicial si así lo exige el interés público", "Salvo que sea una persona jurídica", "Sin que en ningún caso pueda agravar su situación inicial"]'::jsonb,3,'Art. 88.2 Ley 39/2015','Sin perjuicio de la potestad de incoar de oficio un nuevo procedimiento.',null),
('adm-cm:13-416dc40f6f','adm-cm',13,'La presentación de una denuncia:','["Convierte al denunciante en interesado en el procedimiento sancionador que se inicie", "Obliga a iniciar el procedimiento y a sancionar", "No confiere, por sí sola, la condición de interesado en el procedimiento", "Requiere asistencia de abogado"]'::jsonb,2,'Art. 62.5 Ley 39/2015','El denunciante no es interesado por el solo hecho de denunciar.',null),
('adm-cm:13-17b514610d','adm-cm',13,'Según el art. 62.1, se entiende por denuncia:','["La solicitud de un interesado para que se inicie un procedimiento en su favor", "El acto por el que cualquier persona, en cumplimiento o no de una obligación legal, pone en conocimiento de un órgano administrativo un hecho que pudiera justificar la iniciación de oficio", "La propuesta de iniciación formulada por un órgano administrativo sin competencia para iniciar, que tiene conocimiento de los hechos por razón de sus funciones de inspección, averiguación o investigación", "La orden de un superior"]'::jsonb,1,'Art. 62.1 Ley 39/2015','Definición legal de la denuncia.',null),
('adm-cm:13-3fe28a2dbe','adm-cm',13,'En los procedimientos de responsabilidad patrimonial ante la AGE, es preceptivo el dictamen del Consejo de Estado cuando la indemnización reclamada sea de cuantía igual o superior a:','["50.000 euros", "6.000 euros", "100.000 euros", "30.000 euros"]'::jsonb,0,'Art. 81.2 Ley 39/2015','Desde 50.000 € (o la cuantía fijada por la legislación autonómica) es preceptivo el dictamen.',null),
('adm-cm:13-f7142ada05','adm-cm',13,'En el despacho de los expedientes se guardará:','["El orden que prefiera el funcionario responsable", "El orden alfabético de los interesados, salvo orden motivada en contrario del superior jerárquico del instructor", "El orden riguroso de incoación en asuntos de homogénea naturaleza, salvo orden motivada en contrario", "El orden de prioridad que fije cada interesado en su solicitud, o el que indique el superior jerárquico en cada caso concreto"]'::jsonb,2,'Art. 71.2 Ley 39/2015','Su incumplimiento puede dar lugar a responsabilidad disciplinaria.',null),
('adm-cm:13-84aac65304','adm-cm',13,'El órgano que ordene un acto de ejecución material de resoluciones está obligado a:','["Publicarlo en el BOE y en el boletín autonómico antes de iniciar la actuación material, sin necesidad de notificación personal", "Solicitar autorización judicial", "Esperar a que el acto sea firme en vía administrativa y solicitar autorización judicial para ejecutarlo", "Notificar al particular interesado la resolución que autorice la actuación administrativa"]'::jsonb,3,'Art. 97.2 Ley 39/2015','Debe notificar al particular la resolución que autorice la actuación.',null),
('adm-cm:13-a79f6e9427','adm-cm',13,'NO forma parte del expediente administrativo:','["La información auxiliar o de apoyo, como notas, borradores u opiniones, salvo los informes solicitados antes de la resolución", "Las notificaciones practicadas", "Las pruebas practicadas", "Los informes preceptivos, que se incorporan a un expediente auxiliar distinto del principal y no se remiten al juzgado"]'::jsonb,0,'Art. 70.4 Ley 39/2015','Notas, borradores, opiniones, resúmenes y comunicaciones internas no forman parte del expediente.',null),
('adm-cm:13-32feafbfaa','adm-cm',13,'Las declaraciones responsables y las comunicaciones permiten el reconocimiento o ejercicio de un derecho o el inicio de una actividad:','["Tras la resolución expresa que reconozca el derecho, que deberá dictarse en un mes", "A los tres meses de su presentación si la Administración no se opone", "Desde el día de su presentación, sin perjuicio de las facultades de comprobación de la Administración", "Desde el día de su presentación, sin que la Administración pueda comprobar después lo declarado"]'::jsonb,2,'Art. 69.3 Ley 39/2015','Producen efectos desde su presentación.',null),
('adm-cm:13-9162a96ffe','adm-cm',13,'Si el escrito de iniciación se formuló por dos o más interesados, el desistimiento o la renuncia:','["No está permitido una vez iniciado el procedimiento", "Requiere el acuerdo unánime de todos los que firmaron el escrito de iniciación", "Solo afectará a aquellos que la hubiesen formulado", "Afectará a todos los interesados, salvo que alguno inste la continuación en diez días"]'::jsonb,2,'Art. 94.2 Ley 39/2015','El desistimiento solo afecta a quien lo formula.',null),
('adm-cm:13-d559588246','adm-cm',13,'Según la Ley 39/2015, el expediente administrativo es:','["La carpeta física en la que se archivan los escritos de los interesados", "El acto administrativo que pone fin al procedimiento", "Cualquier documento que se presente en un registro electrónico", "El conjunto ordenado de documentos y actuaciones que sirven de antecedente y fundamento a la resolución administrativa, y las diligencias encaminadas a ejecutarla"]'::jsonb,3,'Art. 70.1 Ley 39/2015','Los expedientes tienen formato electrónico.',null),
('adm-cm:13-42ca464f9b','adm-cm',13,'¿Forman parte del expediente administrativo las notas, borradores y opiniones de carácter auxiliar?','["Sí, todos ellos, porque reflejan la actividad del órgano", "No, y además deben destruirse al terminar el procedimiento", "No, salvo que se trate de informes preceptivos o facultativos solicitados antes de la resolución", "Sí, todos ellos, porque reflejan la actividad interna del órgano y deben estar a disposición de los interesados"]'::jsonb,2,'Art. 70.4 Ley 39/2015','Tampoco forman parte las comunicaciones e informes internos o entre órganos o entidades administrativas, ni los juicios de valor emitidos por las Administraciones.',null),
('adm-cm:13-32546f981d','adm-cm',13,'Al remitir un expediente electrónico, este debe ir acompañado de:','["El original en papel de cada uno de los documentos que lo integran", "La firma manuscrita del jefe de la unidad que lo tramita y lo remite", "Una copia completa en soporte óptico, como un CD o un DVD", "Un índice numerado de todos los documentos que contenga"]'::jsonb,3,'Art. 70.2 Ley 39/2015','El índice garantiza la integridad del expediente y permite su recuperación.',null),
('adm-cm:14-f7f901536b','adm-cm',14,'Contra las resoluciones y los actos de trámite cualificados caben los recursos de:','["Alzada y potestativo de reposición", "Alzada y extraordinario de revisión, únicamente", "Reposición obligatoria y alzada", "Súplica y potestativo de reposición"]'::jsonb,0,'Art. 112.1 Ley 39/2015','Caben el recurso de alzada y el potestativo de reposición.',null),
('adm-cm:14-0c3c3469df','adm-cm',14,'La interposición de un recurso administrativo, como regla general:','["Suspende la ejecución del acto, salvo que una disposición establezca lo contrario", "No suspende la ejecución del acto, salvo que una disposición establezca lo contrario", "Suspende la ejecución del acto durante el plazo para resolver el recurso, salvo que el órgano acuerde lo contrario", "No suspende la ejecución del acto, sin que ninguna disposición normativa pueda establecer otra cosa"]'::jsonb,1,'Art. 117.1 Ley 39/2015','La interposición de cualquier recurso no suspende la ejecución del acto impugnado, salvo disposición en contrario.',null)
